"use client"

import { useEffect, useState, type ReactNode } from "react"
import { usePathname, useRouter } from "next/navigation"
import {
  ChevronDown,
  Home,
  Menu,
  Monitor,
  Moon,
  PanelLeftClose,
  PanelLeft,
  Sun,
  UserCircle2,
} from "lucide-react"
import { Button } from "../../button"
import { cn } from "../../../lib/utils"
import { useAdminRouteProgress } from "../../../lib/admin-route-progress"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../../dropdown-menu"
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "../../sheet"
import { MobileSidebarPanel, Sidebar } from "./sidebar"
import { ThemeToggle } from "../../theme-toggle"
import { Page, PageContent } from "../../layout"
import { TypographyH2 } from "../../typography"
import { useTextSize } from "../../text-size-provider"
import { useTheme } from "../../theme-provider"
import { ScrollToTop } from "../../scroll-to-top"
import { useAdminLayout } from "./layout-context"
import { AdminAuthLoadingScreen } from "./admin-auth-loading-screen"
import {
  ADMIN_HEADER_ROLE_LINE_CLASS,
  ADMIN_MAIN_SCROLL_CLASS,
  ADMIN_PAGE_CONTENT_CLASS,
  ADMIN_SHEET_NAV_CLASS,
} from "../../../lib/layout-shell"

const HEADER_ICON_BTN_MOBILE = cn(
  "h-11 min-h-11 w-11 min-w-11 shrink-0 rounded-lg border-border/70 bg-background/90 text-muted-foreground shadow-sm",
  "hover:border-primary/40 hover:bg-primary/5 hover:text-primary hover:shadow active:scale-[0.98] md:hidden [&_svg]:size-5"
)

const HEADER_ICON_BTN_DESKTOP = cn(
  "hidden h-10 w-10 shrink-0 rounded-lg border-border/70 bg-background/90 text-muted-foreground shadow-sm",
  "hover:border-primary/40 hover:bg-primary/5 hover:text-primary hover:shadow active:scale-[0.98] md:inline-flex [&_svg]:size-5"
)

const HEADER_PROFILE_TRIGGER = cn(
  "group relative inline-flex min-h-12 min-w-12 items-center gap-3 rounded-lg border border-border/70 bg-background/95 px-2.5 py-1.5 pr-3 text-left shadow-sm ring-1 ring-black/5 backdrop-blur-xl",
  "transition-all duration-200 hover:-translate-y-px hover:border-primary/25 hover:bg-primary/[0.04] hover:shadow-md",
  "aria-expanded:border-primary/25 aria-expanded:bg-primary/[0.05] aria-expanded:shadow-md",
  "focus-visible:ring-4 focus-visible:ring-ring/20 focus-visible:outline-none supports-[backdrop-filter]:bg-background/75"
)

const HEADER_PROFILE_AVATAR = cn(
  "flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-primary/15 bg-gradient-to-br from-primary/15 to-primary/5",
  "text-sm font-extrabold tracking-wide text-primary shadow-inner transition-all duration-200",
  "group-hover:border-primary/25 group-hover:from-primary/20 group-hover:to-primary/10 group-hover:shadow-sm",
  "group-aria-expanded:border-primary/25 group-aria-expanded:from-primary/20 group-aria-expanded:to-primary/10"
)

function initials(name: string): string {
  const p = name.trim().split(/\s+/).filter(Boolean)
  if (p.length === 0) return "?"
  if (p.length === 1) return p[0]!.slice(0, 2).toUpperCase()
  return `${p[0]![0] ?? ""}${p[p.length - 1]![0] ?? ""}`.toUpperCase()
}

function roleSummary(user: {
  roles: { name: string; displayName?: string }[]
}): string {
  if (!user.roles.length) return "Chưa gán vai trò"
  return user.roles.map((r) => r.displayName || r.name).join(" · ")
}

export function AdminShell({
  children,
  classMain,
  isSidebar = true,
}: {
  children: ReactNode
  classMain?: string
  isSidebar?: boolean
}) {
  const pathname = usePathname()
  const router = useRouter()
  const { startIfNavigating } = useAdminRouteProgress()
  const {
    user,
    clientReady,
    siteName,
    siteDescription,
    brandingReady,
    loginPath,
    isAuthPath,
    canAccessApp,
    clearSession,
    sessionEventName,
    mobileHeaderTitle = "B2B Admin",
    fullWidthPaths = ["/graph"],
    homePath = "/",
    profilePath = "/profile",
    publicSitePath,
    publicSiteLabel = "Trang chủ",
    accessDeniedReason = "staff_only",
  } = useAdminLayout()
  const { theme, setTheme } = useTheme()
  const { size, setSize } = useTextSize()
  const displayName = user?.name?.trim() || user?.email || "Người dùng HUB"
  const avatarUrl = user?.image?.trim() || null
  const onAuthRoute = isAuthPath(pathname)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
  const [mobileNavOpen, setMobileNavOpen] = useState(false)

  // Force editor toolbar sticky via JS to overcome any CSS specificity issues
  useEffect(() => {
    const forceToolbarSticky = () => {
      document
        .querySelectorAll<HTMLElement>(".editor-toolbar")
        .forEach((el) => {
          el.style.setProperty("position", "sticky", "important")
          el.style.setProperty("top", "0px", "important")
        })
    }
    forceToolbarSticky()
    const timer = setTimeout(forceToolbarSticky, 500)
    const observer = new MutationObserver(forceToolbarSticky)
    observer.observe(document.body, { childList: true, subtree: true })
    return () => {
      clearTimeout(timer)
      observer.disconnect()
    }
  }, [])

  useEffect(() => {
    if (!clientReady) return

    if (onAuthRoute) {
      if (user && canAccessApp(user)) {
        router.replace(homePath)
        return
      }
      if (user && !canAccessApp(user)) {
        clearSession()
        window.dispatchEvent(new Event(sessionEventName))
        router.replace(`${loginPath}?reason=${accessDeniedReason}`)
      }
      return
    }

    if (!user) {
      router.replace(loginPath)
      return
    }
    if (!canAccessApp(user)) {
      clearSession()
      window.dispatchEvent(new Event(sessionEventName))
      router.replace(`${loginPath}?reason=${accessDeniedReason}`)
    }
  }, [
    accessDeniedReason,
    canAccessApp,
    clearSession,
    clientReady,
    homePath,
    loginPath,
    onAuthRoute,
    router,
    sessionEventName,
    user,
  ])

  if (onAuthRoute) {
    if (!clientReady) {
      return (
        <AdminAuthLoadingScreen
          message="Đang tải…"
          siteName={brandingReady ? siteName : undefined}
          siteDescription={brandingReady ? siteDescription : undefined}
        />
      )
    }
    if (user && canAccessApp(user)) {
      return (
        <AdminAuthLoadingScreen
          message="Đang chuyển về bảng điều khiển…"
          siteName={brandingReady ? siteName : undefined}
          siteDescription={brandingReady ? siteDescription : undefined}
        />
      )
    }
    return (
      <>
        <div className="fixed top-4 right-4 z-50 rounded-lg border border-border bg-background/90 p-0.5 shadow-sm backdrop-blur-sm">
          <ThemeToggle />
        </div>
        {children}
      </>
    )
  }

  if (!clientReady || !user) {
    return (
      <AdminAuthLoadingScreen
        message="Đang tải…"
        siteName={brandingReady ? siteName : undefined}
        siteDescription={brandingReady ? siteDescription : undefined}
      />
    )
  }

  const rolesDisplay = roleSummary(user)

  return (
    <>
      <div className="flex h-screen w-full flex-col bg-background font-sans text-foreground md:flex-row">
        <Sheet open={mobileNavOpen} onOpenChange={setMobileNavOpen}>
          <SheetContent
            id="admin-mobile-nav"
            side="left"
            showCloseButton
            className={ADMIN_SHEET_NAV_CLASS}
          >
            <SheetHeader className="sr-only">
              <SheetTitle>Menu điều hướng</SheetTitle>
            </SheetHeader>
            <MobileSidebarPanel onNavigate={() => setMobileNavOpen(false)} />
          </SheetContent>
        </Sheet>

        {isSidebar && <Sidebar collapsed={sidebarCollapsed} />}

        <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
          <header
            data-admin-header="true"
            className="sticky top-0 z-10 flex min-h-16 shrink-0 items-center justify-between border-b border-border/70 bg-background/85 px-3 shadow-[0_1px_0_0_hsl(var(--border)/0.4)] backdrop-blur-xl supports-[backdrop-filter]:bg-background/75 sm:min-h-[4.5rem] sm:px-5 lg:px-6"
          >
            <div className="flex min-w-0 items-center gap-2 sm:gap-3">
              <Button
                type="button"
                variant="outline"
                size="icon"
                className={HEADER_ICON_BTN_MOBILE}
                onClick={() => setMobileNavOpen(true)}
                aria-label="Mở menu điều hướng"
                aria-expanded={mobileNavOpen}
                aria-controls="admin-mobile-nav"
              >
                <Menu aria-hidden className="size-5" />
              </Button>
              <TypographyH2 className="shrink-0 truncate text-lg font-bold text-primary sm:text-xl md:hidden">
                {mobileHeaderTitle}
              </TypographyH2>
              <Button
                type="button"
                variant="outline"
                size="icon"
                className={HEADER_ICON_BTN_DESKTOP}
                onClick={() => setSidebarCollapsed((c) => !c)}
                aria-label={sidebarCollapsed ? "Mở sidebar" : "Thu gọn sidebar"}
                title={sidebarCollapsed ? "Mở sidebar" : "Thu gọn sidebar"}
                aria-pressed={!sidebarCollapsed}
              >
                {sidebarCollapsed ? (
                  <PanelLeft aria-hidden className="size-5" />
                ) : (
                  <PanelLeftClose aria-hidden className="size-5" />
                )}
              </Button>
            </div>
            <div className="flex-1" />
            <div className="flex items-center gap-2 sm:gap-3">
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <button
                      type="button"
                      className={HEADER_PROFILE_TRIGGER}
                      aria-label="Mở menu tài khoản và tuỳ chỉnh giao diện"
                    />
                  }
                >
                  <div className="hidden min-w-0 text-right sm:block">
                    <p className="max-w-[220px] truncate text-sm leading-none font-bold text-foreground">
                      {displayName}
                    </p>
                    <p
                      className={cn(
                        ADMIN_HEADER_ROLE_LINE_CLASS,
                        "mt-1 max-w-[220px] truncate text-[11px] text-muted-foreground/90"
                      )}
                      title={rolesDisplay}
                    >
                      {rolesDisplay}
                    </p>
                  </div>
                  <div className={HEADER_PROFILE_AVATAR}>
                    {avatarUrl ? (
                      <img
                        src={avatarUrl}
                        alt=""
                        className="size-full rounded-lg object-cover"
                      />
                    ) : (
                      initials(displayName)
                    )}
                  </div>
                  <ChevronDown className="hidden size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-aria-expanded:rotate-180 sm:block" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-64 p-2">
                  <div className="px-2 py-1.5">
                    <div className="flex items-center gap-2.5">
                      <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-primary/20 bg-primary/10 text-xs font-bold text-primary">
                        {avatarUrl ? (
                          <img
                            src={avatarUrl}
                            alt=""
                            className="size-full rounded-lg object-cover"
                          />
                        ) : (
                          initials(displayName)
                        )}
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-semibold text-foreground">
                          {displayName}
                        </p>
                        <p
                          className="truncate text-xs text-muted-foreground"
                          title={rolesDisplay}
                        >
                          {rolesDisplay}
                        </p>
                      </div>
                    </div>
                  </div>
                  <DropdownMenuSeparator />
                  <DropdownMenuGroup>
                    {publicSitePath ? (
                      <DropdownMenuItem
                        className="cursor-pointer rounded-md px-2 py-1.5"
                        onClick={() => {
                          startIfNavigating(publicSitePath)
                          router.push(publicSitePath)
                        }}
                      >
                        <Home className="size-4 text-muted-foreground" />
                        {publicSiteLabel}
                      </DropdownMenuItem>
                    ) : null}
                    <DropdownMenuItem
                      className="cursor-pointer rounded-md px-2 py-1.5"
                      onClick={() => {
                        startIfNavigating(profilePath)
                        router.push(profilePath)
                      }}
                    >
                      <UserCircle2 className="size-4 text-muted-foreground" />
                      Hồ sơ
                    </DropdownMenuItem>
                  </DropdownMenuGroup>
                  <DropdownMenuSeparator />
                  <div className="space-y-2 px-2 py-1">
                    <p className="text-[10px] font-semibold tracking-wide text-muted-foreground uppercase">
                      Tuỳ chỉnh
                    </p>
                    <DropdownMenuRadioGroup
                      value={theme}
                      onValueChange={(value) =>
                        setTheme(value as "light" | "dark" | "system")
                      }
                    >
                      <div className="grid grid-cols-3 gap-1">
                        <DropdownMenuRadioItem
                          value="light"
                          title="Sáng"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5"
                        >
                          <Sun className="size-4 text-muted-foreground" />
                        </DropdownMenuRadioItem>
                        <DropdownMenuRadioItem
                          value="dark"
                          title="Tối"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5"
                        >
                          <Moon className="size-4 text-muted-foreground" />
                        </DropdownMenuRadioItem>
                        <DropdownMenuRadioItem
                          value="system"
                          title="Theo hệ thống"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5"
                        >
                          <Monitor className="size-4 text-muted-foreground" />
                        </DropdownMenuRadioItem>
                      </div>
                    </DropdownMenuRadioGroup>
                    <DropdownMenuRadioGroup
                      value={size}
                      onValueChange={(value) =>
                        setSize(value as "sm" | "base" | "lg")
                      }
                    >
                      <div className="grid grid-cols-3 gap-1">
                        <DropdownMenuRadioItem
                          value="sm"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5 text-xs font-bold"
                        >
                          S
                        </DropdownMenuRadioItem>
                        <DropdownMenuRadioItem
                          value="base"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5 text-xs font-bold"
                        >
                          M
                        </DropdownMenuRadioItem>
                        <DropdownMenuRadioItem
                          value="lg"
                          className="cursor-pointer justify-center rounded-md border border-border px-2 py-1.5 text-xs font-bold"
                        >
                          L
                        </DropdownMenuRadioItem>
                      </div>
                    </DropdownMenuRadioGroup>
                  </div>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </header>
          <main className={cn(ADMIN_MAIN_SCROLL_CLASS, classMain)}>
            {fullWidthPaths.includes(pathname) ? (
              children
            ) : (
              <Page as="div">
                <PageContent className={ADMIN_PAGE_CONTENT_CLASS}>
                  {children}
                </PageContent>
              </Page>
            )}
          </main>
        </div>
      </div>
      <ScrollToTop />
    </>
  )
}

src/components/admin/shell/sidebar.tsx.content:
"use client"

import { useEffect, useState } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { useAdminNavLink } from "../../../lib/admin-nav-link"
import { ShieldCheck, ChevronDown, ChevronsUpDown, LogOut } from "lucide-react"
import { Button } from "../../button"
import { cn } from "../../../lib/utils"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "../../collapsible"
import { useAdminLayout } from "./layout-context"
import type {
  AdminLayoutUser,
  AdminMenuLeaf,
  AdminMenuTreeItem,
} from "../types"
import { getLegacyVisibleMenuLeaves, getVisibleMenuItems } from "../menu-utils"

function displayNameOf(user: AdminLayoutUser | null): string {
  return user?.name?.trim() || user?.email || "Người dùng HUB"
}

function roleSummaryOf(user: AdminLayoutUser | null): string {
  const labels = (user?.roles ?? [])
    .map((role) => role.displayName || role.name)
    .filter(Boolean)
  if (!labels.length) return "Chưa gán vai trò"
  return labels.join(" · ")
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return "HU"
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase()
  return `${parts[0]![0] ?? ""}${parts[parts.length - 1]![0] ?? ""}`.toUpperCase()
}

function SidebarLeafLink({
  item,
  isActive,
  collapsed,
  onClick,
  nested = false,
}: {
  item: AdminMenuLeaf
  isActive: boolean
  collapsed: boolean
  onClick?: () => void
  nested?: boolean
}) {
  const Icon = item.icon
  const {
    isPending,
    prefetch,
    onClick: onNavClick,
  } = useAdminNavLink(item.href)

  return (
    <Link
      href={item.href}
      title={item.label}
      prefetch
      onMouseEnter={prefetch}
      onFocus={prefetch}
      onClick={(event) => onNavClick(event, onClick)}
      className={cn(
        "group relative flex items-center overflow-hidden rounded-lg transition-all duration-200",
        collapsed
          ? "justify-center px-2 py-3"
          : nested
            ? "gap-3 px-3 py-1"
            : "gap-3 px-3 py-1",
        isPending && !isActive && "opacity-75",
        isActive
          ? nested
            ? "bg-white/20 text-white"
            : "bg-white/20 text-white"
          : "text-white/88 hover:bg-white/15 hover:text-white"
      )}
    >
      {isActive && !collapsed ? (
        <span
          className={cn(
            "absolute left-0 rounded-r-full",
            nested
              ? "inset-y-2.5 w-px bg-white/35"
              : "inset-y-2 w-1 bg-white/85"
          )}
        />
      ) : null}
      <span
        className={cn(
          "flex shrink-0 items-center justify-center rounded-lg transition-all duration-200",
          collapsed ? "size-9" : nested ? "size-8" : "size-8"
        )}
      >
        <Icon
          className={cn(
            "shrink-0 transition-transform duration-200 group-hover:scale-105",
            nested ? "size-[1.05rem]" : "size-[1.1rem]"
          )}
        />
      </span>
      {!collapsed && (
        <span
          className={cn(
            "min-w-0 flex-1 truncate",
            nested
              ? "text-[0.98rem] font-medium"
              : "text-[1.02rem] font-semibold"
          )}
        >
          {item.label}
        </span>
      )}
    </Link>
  )
}

function normalizeMenuPath(path: string): string {
  return path.replace(/\/+$/, "") || "/"
}

function collectMenuHrefs(items: AdminMenuTreeItem[]): string[] {
  const hrefs: string[] = []
  for (const item of items) {
    if (item.type === "leaf") {
      hrefs.push(item.href)
      continue
    }
    for (const child of item.children) {
      hrefs.push(child.href)
    }
  }
  return hrefs
}

function isLeafActive(
  pathname: string,
  href: string,
  allHrefs: string[]
): boolean {
  const path = normalizeMenuPath(pathname)
  const target = normalizeMenuPath(href)
  if (path === target) return true
  if (!path.startsWith(`${target}/`)) return false

  // Prefix match for detail/edit routes — but defer to a longer menu href
  // (e.g. /admin must not stay active on /admin/rbac when /admin/rbac exists).
  return !allHrefs.some((other) => {
    if (other === href) return false
    const candidate = normalizeMenuPath(other)
    if (candidate === target || !candidate.startsWith(`${target}/`)) return false
    return path === candidate || path.startsWith(`${candidate}/`)
  })
}

function isGroupActive(
  pathname: string,
  items: AdminMenuLeaf[],
  allHrefs: string[]
): boolean {
  return items.some((item) => isLeafActive(pathname, item.href, allHrefs))
}

function LegacyCollapsedNav({
  visible,
  pathname,
  allHrefs,
  onLinkClick,
}: {
  visible: AdminMenuLeaf[]
  pathname: string
  allHrefs: string[]
  onLinkClick?: () => void
}) {
  return (
    <>
      {visible.map((item) => (
        <SidebarLeafLink
          key={item.href}
          item={item}
          isActive={isLeafActive(pathname, item.href, allHrefs)}
          collapsed
          onClick={onLinkClick}
        />
      ))}
    </>
  )
}

function TreeNav({
  visible,
  pathname,
  allHrefs,
  onLinkClick,
}: {
  visible: AdminMenuTreeItem[]
  pathname: string
  allHrefs: string[]
  onLinkClick?: () => void
}) {
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({})

  useEffect(() => {
    setOpenGroups((prev) => {
      const next: Record<string, boolean> = {}

      for (const item of visible) {
        if (item.type !== "group") continue
        const isActive = isGroupActive(pathname, item.children, allHrefs)
        next[item.label] = prev[item.label] ?? isActive
        if (isActive) {
          next[item.label] = true
        }
      }

      return next
    })
  }, [pathname, visible, allHrefs])

  return (
    <>
      {visible.map((item) => {
        if (item.type === "leaf") {
          return (
            <SidebarLeafLink
              key={item.href}
              item={item}
              isActive={isLeafActive(pathname, item.href, allHrefs)}
              collapsed={false}
              onClick={onLinkClick}
            />
          )
        }

        const groupActive = isGroupActive(pathname, item.children, allHrefs)
        return (
          <Collapsible
            key={item.label}
            open={openGroups[item.label] ?? groupActive}
            onOpenChange={(open) =>
              setOpenGroups((prev) => ({ ...prev, [item.label]: open }))
            }
            className="rounded-lg"
          >
            <CollapsibleTrigger
              className={cn(
                "group flex w-full items-center gap-3 rounded-lg px-3 py-1.5 text-left transition-all duration-200",
                groupActive
                  ? "mb-1 bg-white/20 text-white"
                  : "text-white/90 hover:bg-white/15 hover:text-white"
              )}
            >
              <span
                className={cn(
                  "flex size-8 shrink-0 items-center justify-center rounded-lg"
                )}
              >
                <item.icon className="size-[1.1rem]" />
              </span>
              <div className="min-w-0 flex-1">
                <p className="truncate text-[1.02rem] font-semibold">
                  {item.label}
                </p>
                <p className="truncate text-[11px] text-white/55">
                  {item.children.length} mục
                </p>
              </div>
              <ChevronDown className="size-4 shrink-0 text-white/55 transition-transform duration-200" />
            </CollapsibleTrigger>
            <CollapsibleContent className="px-2 pb-1">
              <div className="ml-4 space-y-1 border-l border-white/12 pl-3">
                {item.children.map((child) => (
                  <SidebarLeafLink
                    key={child.href}
                    item={child}
                    isActive={isLeafActive(pathname, child.href, allHrefs)}
                    collapsed={false}
                    nested
                    onClick={onLinkClick}
                  />
                ))}
              </div>
            </CollapsibleContent>
          </Collapsible>
        )
      })}
    </>
  )
}

export function SidebarNavLinks({
  collapsed,
  onLinkClick,
  className,
}: {
  collapsed: boolean
  onLinkClick?: () => void
  className?: string
}) {
  const pathname = usePathname()
  const { user, menuTree } = useAdminLayout()
  const visible = getVisibleMenuItems(user, menuTree)
  const collapsedVisible = getLegacyVisibleMenuLeaves(user, menuTree)
  const allMenuHrefs = collectMenuHrefs(visible)

  return (
    <nav
      className={cn(
        "flex-1 overflow-y-auto",
        collapsed ? "p-2" : "p-4",
        className
      )}
    >
      {!collapsed && (
        <div className="px-3 pt-1 pb-2 text-[11px] font-semibold tracking-[0.16em] text-white/52 uppercase">
          Platform
        </div>
      )}
      <div className={cn("space-y-1.5", collapsed ? "" : "space-y-2")}>
        {collapsed ? (
          <LegacyCollapsedNav
            visible={collapsedVisible}
            pathname={pathname}
            allHrefs={allMenuHrefs}
            onLinkClick={onLinkClick}
          />
        ) : (
          <TreeNav
            visible={visible}
            pathname={pathname}
            allHrefs={allMenuHrefs}
            onLinkClick={onLinkClick}
          />
        )}
      </div>
    </nav>
  )
}

/** Menu dạng drawer cho màn hình nhỏ (Sheet). */
export function MobileSidebarPanel({ onNavigate }: { onNavigate: () => void }) {
  const {
    user,
    logout,
    siteName,
    siteDescription,
    homePath = "/",
    profilePath = "/profile",
  } = useAdminLayout()
  const displayName = displayNameOf(user)
  const roleText = roleSummaryOf(user)
  const avatarUrl = user?.image?.trim() || null

  return (
    <div className="flex h-full flex-col bg-primary text-white">
      <div className="shrink-0 px-4 pt-5 pb-4">
        <Link
          href={homePath}
          className="group flex items-center gap-3 rounded-lg px-2 py-2 transition-all duration-200 hover:bg-white/15"
          onClick={onNavigate}
        >
          <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-white/12 ring-1 ring-white/12 transition-transform duration-200 group-hover:scale-[1.03]">
            <ShieldCheck className="size-5 text-white" />
          </div>
          <div className="min-w-0">
            <p className="truncate font-heading text-xl font-bold tracking-tight text-white">
              {siteName}
            </p>
            <p className="truncate text-sm text-white/72">{siteDescription}</p>
          </div>
        </Link>
      </div>
      <SidebarNavLinks collapsed={false} onLinkClick={onNavigate} />
      <div className="mt-auto shrink-0 p-4">
        <div className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/6 px-3 py-3 shadow-[0_8px_20px_rgba(7,16,48,0.18)]">
          <Link
            href={profilePath}
            onClick={onNavigate}
            className="flex min-w-0 flex-1 items-center gap-3"
          >
            <div className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-white/14 text-sm font-semibold text-white">
              {avatarUrl ? (
                <img
                  src={avatarUrl}
                  alt=""
                  className="size-full object-cover"
                />
              ) : (
                initialsOf(displayName)
              )}
            </div>
            <div className="min-w-0">
              <p className="truncate text-base font-semibold text-white">
                {displayName}
              </p>
              <p className="truncate text-sm text-white/68">{roleText}</p>
            </div>
            <ChevronsUpDown className="size-4 shrink-0 text-white/50" />
          </Link>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-9 shrink-0 rounded-lg text-white/72 hover:bg-white/15 hover:text-white"
            onClick={() => {
              onNavigate()
              void logout()
            }}
            aria-label="Đăng xuất"
          >
            <LogOut aria-hidden className="size-4" />
          </Button>
        </div>
      </div>
    </div>
  )
}

type SidebarProps = {
  collapsed: boolean
}

export function Sidebar({ collapsed }: SidebarProps) {
  const { logout, siteName, siteDescription, homePath = "/" } = useAdminLayout()

  return (
    <aside
      className={cn(
        "sticky top-0 hidden h-screen shrink-0 flex-col overflow-hidden border-r border-[#1A2D65] bg-primary text-white transition-[width] duration-300 ease-out md:flex",
        collapsed ? "w-[4.5rem]" : "w-80"
      )}
    >
      <div
        className={cn(
          "shrink-0",
          collapsed ? "flex justify-center px-2 py-3" : "px-4 pt-5 pb-4"
        )}
      >
        <Link
          href={homePath}
          className={cn(
            "group flex transition-all duration-200 hover:bg-white/15",
            collapsed
              ? "justify-center rounded-lg p-2.5"
              : "items-center gap-3 rounded-lg px-2 py-2"
          )}
          title="Trang chủ"
        >
          <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-white/12 ring-1 ring-white/12 transition-transform duration-200 group-hover:scale-[1.03]">
            <ShieldCheck className="size-5 text-white" />
          </div>
          {!collapsed && (
            <div className="min-w-0">
              <p className="truncate font-heading text-[1.7rem] font-bold tracking-tight text-white">
                {siteName}
              </p>
              <p className="truncate text-sm text-white/72">
                {siteDescription}
              </p>
            </div>
          )}
        </Link>
      </div>
      <SidebarNavLinks collapsed={collapsed} />
      <div className={cn("mt-auto shrink-0", collapsed ? "p-2" : "p-4")}>
        {collapsed ? (
          <Button
            type="button"
            title="Đăng xuất"
            aria-label="Đăng xuất"
            onClick={() => logout()}
            variant="ghost"
            className="size-10 rounded-lg text-white/72 hover:bg-white/15 hover:text-white"
          >
            <LogOut aria-hidden className="size-4" />
          </Button>
        ) : (
          <div className="align-center flex items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/6 shadow-[0_10px_24px_rgba(8,17,52,0.2)]">
            <Button
              type="button"
              aria-label="Đăng xuất"
              onClick={() => logout()}
              variant="ghost"
              className="h-full w-full px-3 py-3"
            >
              <LogOut aria-hidden className="size-4" />
              Đăng xuất
            </Button>
          </div>
        )}
      </div>
    </aside>
  )
}

src/components/admin/storage/admin-stora.content:
"use client"

import { useRef, useState } from "react"

import { Button } from "../../button"

import { ConfirmActionDialog } from "../../dialogs"

import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../dialog"

import {
  ADMIN_DIALOG_CONTENT_FULL_BLEED_CLASS,
  ADMIN_DIALOG_FOOTER_FLUSH_CLASS,
} from "../../../lib/layout-shell"

import { AdminStoragePickerPanel } from "./admin-storage-picker-panel"

import type {
  AdminStoragePickerAdapters,
  AdminStoragePickerFolderScope,
  AdminStoragePickerUploadConfig,
} from "./types"

export type AdminStorageImagePickerDialogProps = {
  open: boolean

  onOpenChange: (open: boolean) => void

  adapters: AdminStoragePickerAdapters

  onSelect: (urls: string[]) => void

  title?: string

  multiSelect?: boolean

  imagesOnly?: boolean

  folderScope?: AdminStoragePickerFolderScope | null

  upload?: AdminStoragePickerUploadConfig

  canDelete?: boolean
}

export function AdminStorageImagePickerDialog({
  open,

  onOpenChange,

  adapters,

  onSelect,

  title = "Chọn ảnh từ kho lưu trữ",

  multiSelect = true,

  imagesOnly = true,

  folderScope = null,

  upload,

  canDelete = true,
}: AdminStorageImagePickerDialogProps) {
  const [selectionCount, setSelectionCount] = useState(0)

  const [deletingBulk, setDeletingBulk] = useState(false)

  const [bulkDeleteConfirmOpen, setBulkDeleteConfirmOpen] = useState(false)

  const confirmPickRef = useRef<(() => void) | null>(null)

  const clearSelectionRef = useRef<(() => void) | null>(null)

  const bulkDeleteRef = useRef<(() => void | Promise<void>) | null>(null)

  const closeDialog = () => onOpenChange(false)

  return (
    <>
      <Dialog
        open={open}
        onOpenChange={(next) => {
          if (!next) {
            setSelectionCount(0)

            setBulkDeleteConfirmOpen(false)
          }

          onOpenChange(next)
        }}
      >
        <DialogContent
          className={`${ADMIN_DIALOG_CONTENT_FULL_BLEED_CLASS} max-w-[min(96vw,72rem)] sm:max-w-[72rem]`}
        >
          <DialogHeader className="shrink-0 border-b px-6 py-4">
            <DialogTitle>{title}</DialogTitle>
          </DialogHeader>

          <div className="min-h-0 flex-1 overflow-y-auto px-4 py-4 sm:px-6">
            {open ? (
              <AdminStoragePickerPanel
                adapters={adapters}
                imagesOnly={imagesOnly}
                multiSelect={multiSelect}
                folderScope={folderScope}
                upload={upload}
                canDelete={canDelete}
                onSelectionCountChange={setSelectionCount}
                confirmPickRef={confirmPickRef}
                clearSelectionRef={clearSelectionRef}
                bulkDeleteRef={bulkDeleteRef}
                onDeletingBulkChange={setDeletingBulk}
                onPick={(urls) => {
                  onSelect(urls)

                  onOpenChange(false)
                }}
              />
            ) : null}
          </div>

          {multiSelect ? (
            <DialogFooter className={ADMIN_DIALOG_FOOTER_FLUSH_CLASS}>
              <p
                className="min-w-0 text-sm text-muted-foreground"
                aria-live="polite"
                aria-atomic="true"
              >
                {selectionCount > 0
                  ? `Đã chọn ${selectionCount} ảnh — giữ khi đổi trang`
                  : "Tick ảnh trên bảng hoặc bấm «Xác nhận» khi đã chọn xong"}
              </p>

              <div className="flex w-full flex-col-reverse gap-2 sm:w-auto sm:flex-row sm:justify-end">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={deletingBulk}
                  onClick={closeDialog}
                >
                  Hủy
                </Button>

                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={selectionCount === 0 || deletingBulk}
                  onClick={() => clearSelectionRef.current?.()}
                >
                  Bỏ chọn
                </Button>

                {canDelete ? (
                  <Button
                    type="button"
                    variant="destructive"
                    size="sm"
                    disabled={selectionCount === 0 || deletingBulk}
                    onClick={() => setBulkDeleteConfirmOpen(true)}
                  >
                    Xóa khỏi kho
                  </Button>
                ) : null}

                <Button
                  type="button"
                  size="sm"
                  disabled={selectionCount === 0 || deletingBulk}
                  onClick={() => confirmPickRef.current?.()}
                >
                  Xác nhận{selectionCount > 0 ? ` (${selectionCount})` : ""}
                </Button>
              </div>
            </DialogFooter>
          ) : null}
        </DialogContent>
      </Dialog>

      {canDelete ? (
        <ConfirmActionDialog
          open={bulkDeleteConfirmOpen}
          onOpenChange={setBulkDeleteConfirmOpen}
          title="Xóa file khỏi kho lưu trữ"
          description={
            <>
              Bạn sắp xóa{" "}
              <strong className="tabular-nums">{selectionCount}</strong> file
              trên disk. Thao tác không gỡ URL đã gán trên form sản phẩm.
            </>
          }
          confirmLabel="Xóa khỏi kho"
          cancelLabel="Hủy"
          confirmDestructive
          confirmLoading={deletingBulk}
          onConfirm={async () => {
            await bulkDeleteRef.current?.()

            setBulkDeleteConfirmOpen(false)
          }}
        />
      ) : null}
    </>
  )
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { Film, Play } from "lucide-react"
import { FileTypeIcon, FileTypeIconSm } from "../../file-type-icon"
import { defineDataTableActionsColumn } from "../../data-table"
import { formatAdminDateTime } from "../../../lib/format-admin-datetime"
import type { AdminStorageFileRow } from "./types"

import {
  formatStorageFileSize,
  isImageStorageRow,
  resolveStorageAssetUrl,
  storageThumbnailUrl,
} from "./storage-asset-url"

import { AdminStoragePickerRowActions } from "./admin-storage-picker-row-actions"

function isVideoStorageRow(
  row: Pick<AdminStorageFileRow, "mediaKind" | "mimeType">
): boolean {
  return (
    row.mediaKind === "video" || row.mimeType?.startsWith("video/") === true
  )
}

export type AdminStoragePickerColumnsProps = {
  onPick: (row: AdminStorageFileRow) => void
  onDelete?: (row: AdminStorageFileRow) => void
  canPick?: (row: AdminStorageFileRow) => boolean
  isSelected?: (row: AdminStorageFileRow) => boolean
  multiSelect?: boolean
  canDelete?: boolean
  deletingPath?: string | null
}

export function getAdminStoragePickerColumns({
  onPick,
  onDelete,
  canPick = isImageStorageRow,
  isSelected,
  multiSelect = false,
  canDelete = false,
  deletingPath = null,
}: AdminStoragePickerColumnsProps): ColumnDef<AdminStorageFileRow, unknown>[] {
  return [
    {
      id: "preview",
      header: "Xem trước",
      enableSorting: false,
      enableColumnFilter: false,
      size: 80,
      meta: { className: "w-[88px] min-w-[88px] max-w-[88px]" },
      cell: ({ row }) => {
        const item = row.original
        const pickable = canPick(item)
        if (isImageStorageRow(item)) {
          return (
            <button
              type="button"
              disabled={!pickable}
              onClick={() => pickable && onPick(item)}
              className={[
                "flex size-16 cursor-pointer items-center justify-center overflow-hidden rounded-md border bg-muted disabled:cursor-not-allowed disabled:opacity-50",
              ].join(" ")}
            >
              <img
                src={storageThumbnailUrl(item)}
                alt={item.originalName}
                className="size-full object-cover"
                loading="lazy"
                decoding="async"
              />
            </button>
          )
        }

        if (isVideoStorageRow(item)) {
          return (
            <div className="relative flex size-16 items-center justify-center overflow-hidden rounded-md border border-border bg-muted">
              <Film className="size-8 text-muted-foreground" />
              <span className="absolute inset-0 flex items-center justify-center bg-black/25">
                <Play className="size-6 fill-white text-white" />
              </span>
            </div>
          )
        }

        return <FileTypeIcon filename={item.originalName} />
      },
    },

    {
      accessorKey: "originalName",
      header: "Tên file",
      enableSorting: false,
      enableColumnFilter: false,
      cell: ({ getValue, row }) => (
        <div className="flex min-w-0 items-center gap-2">
          <FileTypeIconSm filename={row.original.originalName} />
          <a
            href={resolveStorageAssetUrl(row.original)}
            target="_blank"
            rel="noopener noreferrer"
            className="truncate text-sm font-medium underline-offset-2 hover:underline"
            title={row.original.originalName}
            onClick={(e) => e.stopPropagation()}
          >
            {String(getValue())}
          </a>
        </div>
      ),
    },
    {
      accessorKey: "size",
      header: "Kích thước",
      enableSorting: false,
      enableColumnFilter: false,
      size: 100,
      meta: { className: "w-[100px] min-w-[100px] max-w-[100px]" },
      cell: ({ getValue }) => (
        <span className="text-sm text-muted-foreground tabular-nums">
          {formatStorageFileSize(Number(getValue() ?? 0))}
        </span>
      ),
    },

    {
      accessorKey: "createdAt",
      header: "Ngày tải",
      enableSorting: false,
      enableColumnFilter: false,
      size: 140,
      meta: { className: "w-[140px] min-w-[140px] max-w-[140px]" },
      cell: ({ getValue }) => (
        <span className="text-xs text-muted-foreground tabular-nums">
          {formatAdminDateTime(getValue() as number | string)}
        </span>
      ),
    },

    defineDataTableActionsColumn<AdminStorageFileRow>({
      cell: ({ row }) => {
        const item = row.original
        const pickable = canPick(item)
        const selected = Boolean(isSelected?.(item))
        const isDeleting = deletingPath === item.relativePath

        return (
          <AdminStoragePickerRowActions
            row={item}
            pickable={pickable}
            selected={selected}
            multiSelect={multiSelect}
            canDelete={canDelete}
            deleting={isDeleting}
            onPick={() => onPick(item)}
            onDelete={onDelete ? () => onDelete(item) : undefined}
          />
        )
      },
    }),
  ]
}

"use client"

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MutableRefObject,
} from "react"
import type { OnChangeFn, Row, RowSelectionState } from "@tanstack/react-table"
import type { StorageRealm } from "@workspace/api-client"
import { Button } from "../../button"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../../tabs"
import { AdminPageLoading } from "../pages/admin-page-loading"
import {
  ADMIN_LIST_TABS_LIST_CLASS,
  ADMIN_LIST_TABS_TRIGGER_CLASS,
} from "../../../lib/layout-shell"
import { toast } from "../../sonner"
import {
  FileText,
  FolderOpen,
  Image as ImageIcon,
  Loader2,
  Music,
  Upload,
  Video,
} from "lucide-react"
import { getAdminStoragePickerColumns } from "./admin-storage-picker-columns"
import { AdminStoragePickerTable } from "./admin-storage-picker-table"
import {
  extractStorageRelativePath,
  formatStorageDeleteError,
  isImageStorageRow,
  resolveStorageAssetUrl,
} from "./storage-asset-url"
import type {
  AdminStoragePickerAdapters,
  AdminStoragePickerFolderScope,
  AdminStoragePickerUploadConfig,
  AdminStorageFileRow,
} from "./types"
import { useAdminStoragePickerList } from "./use-admin-storage-picker-list"

const REALM_ORDER: StorageRealm[] = ["images", "files", "videos", "audio"]

const REALM_ICONS: Record<StorageRealm, typeof ImageIcon> = {
  images: ImageIcon,
  files: FileText,
  videos: Video,
  audio: Music,
}

export type AdminStoragePickerPanelProps = {
  adapters: AdminStoragePickerAdapters
  onPick: (urls: string[]) => void
  imagesOnly?: boolean
  multiSelect?: boolean
  folderScope?: AdminStoragePickerFolderScope | null
  upload?: AdminStoragePickerUploadConfig
  canDelete?: boolean
  className?: string
  onSelectionCountChange?: (count: number) => void
  confirmPickRef?: MutableRefObject<(() => void) | null>
  clearSelectionRef?: MutableRefObject<(() => void) | null>
  bulkDeleteRef?: MutableRefObject<(() => void | Promise<void>) | null>
  onDeletingBulkChange?: (deleting: boolean) => void
}

export function AdminStoragePickerPanel({
  adapters,
  onPick,
  imagesOnly = true,
  multiSelect = true,
  folderScope = null,
  upload,
  canDelete = true,
  className,
  onSelectionCountChange,
  confirmPickRef,
  clearSelectionRef,
  bulkDeleteRef,
  onDeletingBulkChange,
}: AdminStoragePickerPanelProps) {
  const locked = Boolean(folderScope)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [uploading, setUploading] = useState(false)
  const [deletingPath, setDeletingPath] = useState<string | null>(null)
  const [deletingBulk, setDeletingBulk] = useState(false)
  const [bootstrapping, setBootstrapping] = useState(
    Boolean(folderScope?.onBootstrap)
  )
  const [activeRealm, setActiveRealm] = useState<StorageRealm>(
    folderScope?.realm ?? "images"
  )
  const [activeFolderPath, setActiveFolderPath] = useState(
    folderScope?.folderPath ?? ""
  )
  const includeDescendants = false
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(20)
  const [pickedMap, setPickedMap] = useState<Map<string, string>>(
    () => new Map()
  )

  const { rows, realms, loading, isFetching, total, reload } =
    useAdminStoragePickerList(
      adapters,
      activeRealm,
      activeFolderPath,
      page,
      pageSize,
      locked ? false : includeDescendants
    )

  useEffect(() => {
    if (!folderScope) return
    let cancelled = false
    void (async () => {
      setBootstrapping(true)
      try {
        const path = folderScope.onBootstrap
          ? (await folderScope.onBootstrap()).folderPath
          : folderScope.folderPath
        if (!cancelled) {
          setActiveRealm(folderScope.realm ?? "images")
          setActiveFolderPath(path)
          setPage(1)
        }
      } catch (err) {
        if (!cancelled) {
          toast.error(
            err instanceof Error ? err.message : "Không mở được folder sản phẩm"
          )
        }
      } finally {
        if (!cancelled) setBootstrapping(false)
      }
    })()
    return () => {
      cancelled = true
    }
  }, [folderScope])

  const realmTabs = useMemo(() => {
    const byId = new Map(realms.map((r) => [r.id, r]))
    return REALM_ORDER.map((id) => {
      const fromApi = byId.get(id)
      return (
        fromApi ?? {
          id,
          label:
            id === "images"
              ? "Hình ảnh"
              : id === "files"
                ? "Tệp tin"
                : id === "videos"
                  ? "Video"
                  : "Âm thanh",
          count: 0,
        }
      )
    })
  }, [realms])

  const currentFolderLabel = locked
    ? (folderScope?.folderLabel ?? "Sản phẩm")
    : activeFolderPath || "Kho lưu trữ"

  const canPickRow = useCallback(
    (row: AdminStorageFileRow) => !imagesOnly || isImageStorageRow(row),
    [imagesOnly]
  )

  const removeFromPicked = useCallback((relativePath: string) => {
    setPickedMap((prev) => {
      if (!prev.has(relativePath)) return prev
      const next = new Map(prev)
      next.delete(relativePath)
      return next
    })
  }, [])

  const handleDeleteRow = useCallback(
    async (row: AdminStorageFileRow) => {
      if (!canDelete || deletingPath) return
      setDeletingPath(row.relativePath)
      try {
        await adapters.deleteFile(row.relativePath)
        removeFromPicked(row.relativePath)
        toast.success("Đã xóa file khỏi kho")
        await reload()
      } catch (err) {
        const raw = err instanceof Error ? err.message : "Lỗi xóa file"
        toast.error(formatStorageDeleteError(raw))
      } finally {
        setDeletingPath(null)
      }
    },
    [adapters, canDelete, deletingPath, reload, removeFromPicked]
  )

  const handleBulkDelete = useCallback(
    async (paths: string[]) => {
      const normalized = [
        ...new Set(
          paths
            .map((p) => extractStorageRelativePath(p) ?? p.trim())
            .filter(Boolean)
        ),
      ]
      if (!canDelete || !normalized.length || deletingBulk) return
      setDeletingBulk(true)
      onDeletingBulkChange?.(true)
      const pending = toast.loading(`Đang xóa ${normalized.length} file…`)
      try {
        const result = await adapters.bulkDeleteFiles(normalized)
        const failedPaths = new Set(result.errors.map((entry) => entry.path))
        for (const path of normalized) {
          if (!failedPaths.has(path)) removeFromPicked(path)
        }
        setPickedMap((prev) => {
          const next = new Map(prev)
          for (const [key] of prev) {
            const rel = extractStorageRelativePath(key) ?? key
            if (normalized.includes(rel) && !failedPaths.has(rel)) {
              next.delete(key)
            }
          }
          return next
        })
        await reload()
        const errorHint = result.errors[0]
          ? formatStorageDeleteError(result.errors[0].message)
          : ""
        if (result.deleted > 0 && result.failed === 0) {
          toast.success(`Đã xóa ${result.deleted} file`, { id: pending })
        } else if (result.deleted > 0 && result.failed > 0) {
          toast.warning(
            `Đã xóa ${result.deleted}/${normalized.length} file. ${result.failed} file lỗi${errorHint ? `: ${errorHint}` : ""}`,
            { id: pending }
          )
        } else {
          toast.error(errorHint || "Không xóa được file nào", { id: pending })
        }
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi xóa hàng loạt", {
          id: pending,
        })
      } finally {
        setDeletingBulk(false)
        onDeletingBulkChange?.(false)
      }
    },
    [
      adapters,
      canDelete,
      deletingBulk,
      onDeletingBulkChange,
      reload,
      removeFromPicked,
    ]
  )

  const deletePickedRows = useCallback(async () => {
    const paths = [...pickedMap.keys()]
    if (!paths.length) {
      toast.message("Chưa chọn file nào để xóa")
      return
    }
    await handleBulkDelete(paths)
  }, [handleBulkDelete, pickedMap])

  const togglePickRow = useCallback(
    (row: AdminStorageFileRow) => {
      if (!canPickRow(row)) {
        toast.message("Chỉ có thể chọn file ảnh.")
        return
      }
      const url = resolveStorageAssetUrl(row)
      if (!multiSelect) {
        onPick([url])
        return
      }
      setPickedMap((prev) => {
        const next = new Map(prev)
        if (next.has(row.relativePath)) next.delete(row.relativePath)
        else next.set(row.relativePath, url)
        return next
      })
    },
    [canPickRow, multiSelect, onPick]
  )

  const selectedRowIds = useMemo(() => {
    const state: RowSelectionState = {}
    for (const row of rows) {
      if (pickedMap.has(row.relativePath)) {
        state[row.relativePath] = true
      }
    }
    return state
  }, [pickedMap, rows])

  const handleSelectedRowIdsChange = useCallback<OnChangeFn<RowSelectionState>>(
    (updater) => {
      setPickedMap((prev) => {
        const current: RowSelectionState = {}
        for (const row of rows) {
          if (prev.has(row.relativePath)) {
            current[row.relativePath] = true
          }
        }
        const nextState =
          typeof updater === "function" ? updater(current) : updater
        const next = new Map(prev)
        for (const row of rows) {
          const id = row.relativePath
          if (nextState[id]) {
            next.set(id, resolveStorageAssetUrl(row))
          } else {
            next.delete(id)
          }
        }
        return next
      })
    },
    [rows]
  )

  const canSelectTableRow = useCallback(
    (row: Row<AdminStorageFileRow>) => canPickRow(row.original),
    [canPickRow]
  )

  const clearPicked = useCallback(() => {
    setPickedMap(new Map())
  }, [])

  const confirmPicked = useCallback(() => {
    const urls = [...pickedMap.values()]
    if (!urls.length) {
      toast.message("Chưa chọn ảnh nào")
      return
    }
    onPick(urls)
    clearPicked()
  }, [clearPicked, onPick, pickedMap])

  useEffect(() => {
    onSelectionCountChange?.(pickedMap.size)
  }, [onSelectionCountChange, pickedMap.size])

  useEffect(() => {
    if (!confirmPickRef) return
    confirmPickRef.current = multiSelect ? confirmPicked : null
    return () => {
      confirmPickRef.current = null
    }
  }, [confirmPickRef, confirmPicked, multiSelect])

  useEffect(() => {
    if (!clearSelectionRef) return
    clearSelectionRef.current = multiSelect ? clearPicked : null
    return () => {
      clearSelectionRef.current = null
    }
  }, [clearPicked, clearSelectionRef, multiSelect])

  useEffect(() => {
    if (!bulkDeleteRef) return
    bulkDeleteRef.current =
      canDelete && multiSelect ? () => deletePickedRows() : null
    return () => {
      bulkDeleteRef.current = null
    }
  }, [bulkDeleteRef, canDelete, deletePickedRows, multiSelect])

  const columns = useMemo(
    () =>
      getAdminStoragePickerColumns({
        onPick: togglePickRow,
        onDelete: canDelete ? handleDeleteRow : undefined,
        canPick: canPickRow,
        isSelected: (row) => pickedMap.has(row.relativePath),
        multiSelect,
        canDelete,
        deletingPath,
      }),
    [
      canDelete,
      canPickRow,
      deletingPath,
      handleDeleteRow,
      multiSelect,
      pickedMap,
      togglePickRow,
    ]
  )

  const runUpload = useCallback(
    async (files: File[]) => {
      if (!files.length || !upload) return
      if (upload.disabled) {
        toast.error("Nhập tên hoặc SKU sản phẩm trước khi tải ảnh lên")
        return
      }
      setUploading(true)
      const pending = toast.loading(`Đang tải lên ${files.length} ảnh…`)
      try {
        const uploadedUrls = await upload.uploadFiles(files)
        await reload()
        if (uploadedUrls.length > 0) {
          toast.success(`Đã lưu ${uploadedUrls.length} ảnh`, { id: pending })
          if (multiSelect) {
            setPickedMap((prev) => {
              const next = new Map(prev)
              for (const url of uploadedUrls) {
                const relativePath = extractStorageRelativePath(url)
                if (relativePath) next.set(relativePath, url)
                else next.set(url, url)
              }
              return next
            })
          } else {
            onPick(uploadedUrls)
          }
        } else {
          toast.error("Không tải được ảnh nào", { id: pending })
        }
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Lỗi tải ảnh", {
          id: pending,
        })
      } finally {
        setUploading(false)
        if (fileInputRef.current) fileInputRef.current.value = ""
      }
    },
    [multiSelect, onPick, reload, upload]
  )

  const openUploadPicker = useCallback(() => {
    if (upload?.disabled) {
      toast.error("Nhập tên hoặc SKU sản phẩm trước khi tải ảnh lên")
      return
    }
    fileInputRef.current?.click()
  }, [upload?.disabled])

  if (bootstrapping || (loading && rows.length === 0 && !locked)) {
    return <AdminPageLoading variant="list" />
  }

  const uploadButton = upload ? (
    <Button
      type="button"
      variant="default"
      size="sm"
      className="shrink-0 gap-1.5"
      disabled={uploading || upload.disabled}
      onClick={openUploadPicker}
    >
      {uploading ? (
        <Loader2 className="size-4 animate-spin" />
      ) : (
        <Upload className="size-4" />
      )}
      {uploading ? "Đang tải…" : (upload.label ?? "Tải ảnh lên")}
    </Button>
  ) : null

  const tableBlock = (
    <AdminStoragePickerTable
      tableScope={`admin-storage-picker-${activeRealm}-${activeFolderPath || "root"}`}
      data={rows}
      columns={columns}
      isLoading={loading}
      isFetching={isFetching}
      emptyLabel={`Chưa có ảnh trong «${currentFolderLabel}».`}
      emptySummary={`Không có file trong ${currentFolderLabel}`}
      itemLabel="ảnh"
      page={page}
      pageSize={pageSize}
      total={total}
      onPageChange={setPage}
      onPageSizeChange={setPageSize}
      multiSelect={multiSelect}
      selectedRowIds={selectedRowIds}
      onSelectedRowIdsChange={handleSelectedRowIdsChange}
      canSelectRow={canSelectTableRow}
      emptyState={
        !loading && rows.length === 0 && upload ? (
          <div className="flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed bg-muted/20 px-4 py-10 text-center">
            <FolderOpen className="size-10 text-muted-foreground" />
            <p className="text-sm font-medium">Chưa có ảnh trong folder này</p>
            <p className="text-xs text-muted-foreground">
              Tải ảnh lên hoặc chọn từ kho sau khi đã có file
            </p>
            {uploadButton}
          </div>
        ) : undefined
      }
    />
  )

  return (
    <div className={className}>
      {locked && folderScope ? (
        <div className="space-y-4">
          <div className="flex flex-wrap items-start justify-between gap-3 rounded-lg border bg-muted/20 px-4 py-3">
            <div className="min-w-0 space-y-1">
              <p className="text-sm font-medium">
                {folderScope.parentLabel ?? "Sản phẩm"} /{" "}
                {folderScope.folderLabel}
              </p>
              <p className="text-xs text-muted-foreground">
                Chỉ hiển thị ảnh trong folder sản phẩm đang chỉnh sửa.
                {multiSelect
                  ? " Tick nhiều ảnh rồi «Xác nhận» — hoặc xóa file khỏi kho bằng nút Xóa."
                  : ""}
              </p>
            </div>
            {uploadButton}
          </div>
          {upload ? (
            <input
              ref={fileInputRef}
              type="file"
              accept={upload.accept ?? "image/*"}
              multiple
              className="hidden"
              onChange={(e) => {
                void runUpload(Array.from(e.target.files ?? []))
              }}
            />
          ) : null}
          {tableBlock}
        </div>
      ) : (
        <Tabs
          value={activeRealm}
          onValueChange={(value) => {
            setActiveRealm(value as StorageRealm)
            setActiveFolderPath("")
            setPage(1)
          }}
        >
          <div className="flex flex-wrap items-center gap-2">
            <TabsList className={`${ADMIN_LIST_TABS_LIST_CLASS} flex-wrap`}>
              {realmTabs.map((realm) => {
                const Icon = REALM_ICONS[realm.id as StorageRealm] ?? ImageIcon
                return (
                  <TabsTrigger
                    key={realm.id}
                    value={realm.id}
                    className={ADMIN_LIST_TABS_TRIGGER_CLASS}
                  >
                    <Icon className="size-4" />
                    {realm.label}
                  </TabsTrigger>
                )
              })}
            </TabsList>
            <p className="w-full text-xs text-muted-foreground">
              {imagesOnly
                ? multiSelect
                  ? "Tick nhiều ảnh, «Xác nhận» ở cuối dialog — có thể xóa file khỏi kho."
                  : "Bấm «Chọn» để gán ảnh."
                : "Duyệt kho lưu trữ."}
            </p>
          </div>
          {realmTabs.map((realm) => (
            <TabsContent key={realm.id} value={realm.id} className="space-y-4">
              {activeRealm === realm.id ? tableBlock : null}
            </TabsContent>
          ))}
        </Tabs>
      )}
    </div>
  )
}

"use client"

import { Check, ExternalLink, Settings2, Trash2, X } from "lucide-react"
import {
  DataTableRowActionsMenu,
  type DataTableRowActionItem,
} from "../../data-table"
import type { AdminStorageFileRow } from "./types"
import { resolveStorageAssetUrl } from "./storage-asset-url"

export type AdminStoragePickerRowActionsProps = {
  row: AdminStorageFileRow
  pickable: boolean
  selected: boolean
  multiSelect: boolean
  canDelete: boolean
  deleting?: boolean
  onPick: () => void
  onDelete?: () => void | Promise<void>
}

function deleteConfirm(row: AdminStorageFileRow) {
  return {
    title: "Xóa file khỏi kho?",
    description: (
      <>
        File <strong>{row.originalName}</strong> sẽ bị xóa vĩnh viễn khỏi kho
        lưu trữ. URL đã gán trên form sản phẩm không tự gỡ.
      </>
    ),
    confirmLabel: "Xóa khỏi kho",
    destructive: true,
  }
}

export function AdminStoragePickerRowActions({
  row,
  pickable,
  selected,
  multiSelect,
  canDelete,
  deleting,
  onPick,
  onDelete,
}: AdminStoragePickerRowActionsProps) {
  const actions: DataTableRowActionItem[] = []

  if (pickable) {
    if (multiSelect) {
      actions.push({
        key: selected ? "unpick" : "pick",
        label: selected ? "Bỏ chọn" : "Chọn",
        hint: selected
          ? "Gỡ ảnh khỏi danh sách đang chọn"
          : "Thêm ảnh vào danh sách chọn",
        onClick: onPick,
        icon: selected ? <X /> : <Check />,
        group: "primary",
        confirm: false,
      })
    } else {
      actions.push({
        key: "pick",
        label: "Chọn ảnh",
        hint: "Gán ảnh này vào sản phẩm",
        onClick: onPick,
        icon: <Check />,
        group: "primary",
        confirm: false,
      })
    }
  }

  actions.push({
    key: "open",
    label: "Mở tab mới",
    hint: "Xem file trong tab trình duyệt",
    onClick: () => {
      window.open(resolveStorageAssetUrl(row), "_blank", "noopener,noreferrer")
    },
    icon: <ExternalLink />,
    group: "primary",
    confirm: false,
  })

  if (canDelete && onDelete && !deleting) {
    actions.push({
      key: "delete",
      label: "Xóa khỏi kho",
      hint: "Xóa file vĩnh viễn trên disk",
      onClick: onDelete,
      icon: <Trash2 />,
      group: "danger",
      menuVariant: "destructive",
      confirm: deleteConfirm(row),
    })
  }

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={deleting}
      autoConfirmDangerousActions
      groups={{
        primary: { label: "Thao tác", icon: Settings2 },
        danger: { label: "Xóa", sublabel: true },
      }}
    />
  )
}

"use client"

import type {
