import type { ColumnDef, Table, VisibilityState } from "@tanstack/react-table"
import { resolveDataTableColumnId } from "./data-table-columns"
import { DATA_TABLE_ACTIONS_COLUMN_ID } from "./table-row-actions"

export const DATA_TABLE_ALWAYS_VISIBLE_COLUMN_IDS = new Set([
  "_select",
  "stt",
  "_expand",
  DATA_TABLE_ACTIONS_COLUMN_ID,
  "attendanceActions",
])

type ColumnMetaLike = {
  hideInTable?: boolean
  defaultHidden?: boolean
  enableHiding?: boolean
  isIndexColumn?: boolean
  isActionsColumn?: boolean
}

function walkColumns<TData>(
  columns: ColumnDef<TData, unknown>[]
): ColumnDef<TData, unknown>[] {
  const result: ColumnDef<TData, unknown>[] = []
  for (const column of columns) {
    const group = column as ColumnDef<TData, unknown> & {
      columns?: ColumnDef<TData, unknown>[]
    }
    if (group.columns?.length) {
      result.push(...walkColumns(group.columns))
      continue
    }
    result.push(column)
  }
  return result
}

export function isDataTableColumnHideable<TData>(
  column: ColumnDef<TData, unknown>
): boolean {
  const id = resolveDataTableColumnId(column)
  if (id && DATA_TABLE_ALWAYS_VISIBLE_COLUMN_IDS.has(id)) return false
  const meta = column.meta as ColumnMetaLike | undefined
  if (meta?.isIndexColumn || meta?.isActionsColumn) return false
  if (meta?.enableHiding === false) return false
  return Boolean(id)
}

export function buildDefaultTableColumnVisibility<TData>(
  columns: ColumnDef<TData, unknown>[],
  stored?: VisibilityState | null
): VisibilityState {
  const visibility: VisibilityState = {}
  for (const column of walkColumns(columns)) {
    const id = resolveDataTableColumnId(column)
    if (!id || !isDataTableColumnHideable(column)) continue
    const meta = column.meta as ColumnMetaLike | undefined
    if (stored && stored[id] !== undefined) {
      visibility[id] = stored[id]
    } else if (meta?.hideInTable || meta?.defaultHidden) {
      visibility[id] = false
    } else {
      visibility[id] = true
    }
  }
  return visibility
}

export function readStoredColumnVisibility(
  storageKey: string | undefined
): VisibilityState | null {
  if (!storageKey || typeof window === "undefined") return null
  try {
    const raw = localStorage.getItem(storageKey)
    if (!raw) return null
    const parsed = JSON.parse(raw) as unknown
    if (!parsed || typeof parsed !== "object") return null
    return parsed as VisibilityState
  } catch {
    return null
  }
}

export function tableColumnVisibilityLabel<TData>(
  table: Table<TData>,
  columnId: string
): string {
  const column = table.getColumn(columnId)
  if (!column) return columnId
  const meta = column.columnDef.meta as { filterLabel?: string } | undefined
  if (meta?.filterLabel?.trim()) return meta.filterLabel.trim()
  const header = column.columnDef.header
  if (typeof header === "string" && header.trim()) return header.trim()
  return columnId
}

export function getHideableTableColumnOptions<TData>(
  table: Table<TData>
): Array<{ value: string; label: string }> {
  return table
    .getAllLeafColumns()
    .filter((column) => isDataTableColumnHideable(column.columnDef))
    .map((column) => ({
      value: column.id,
      label: tableColumnVisibilityLabel(table, column.id),
    }))
}

import type { ColumnDef } from "@tanstack/react-table"
import { cn } from "../../lib/utils"
import { resolveDataTableColumnId } from "./data-table-columns"
import { DATA_TABLE_ACTIONS_COLUMN_ID } from "./table-row-actions"

type ColumnMetaLike = {
  className?: string
  isActionsColumn?: boolean
  isIndexColumn?: boolean
  disableCellLineClamp?: boolean
}

/** Số dòng tối đa hiển thị trong ô dữ liệu (ellipsis sau dòng thứ 5). */
export const DATA_TABLE_CELL_MAX_LINES = 5

export const DATA_TABLE_CELL_CONTENT_CLAMP_CLASS =
  "line-clamp-5 break-words min-w-0 w-full"

export const DATA_TABLE_INDEX_COLUMN_ID = "stt"
export const DATA_TABLE_EXPAND_COLUMN_ID = "_expand"
export const DATA_TABLE_SELECTION_COLUMN_ID = "_select"
export const DATA_TABLE_REORDER_COLUMN_ID = "_reorder"

/** Min-width mặc định cho cột dữ liệu (ngoài checkbox, STT, expand, thao tác). */
export const DATA_TABLE_DEFAULT_DATA_COLUMN_MIN_WIDTH_CLASS = "min-w-[180px]"
export const DATA_TABLE_DEFAULT_DATA_COLUMN_MIN_SIZE = 180

const COLUMN_EXPLICIT_WIDTH_CLASS =
  /\b(min-w-|max-w-|w-\[|w-\d|w-auto|w-full|w-fit)\b/

export function columnHasExplicitWidthClass(
  meta: ColumnMetaLike | undefined
): boolean {
  return Boolean(
    meta?.className && COLUMN_EXPLICIT_WIDTH_CLASS.test(meta.className)
  )
}

export function columnDefHasExplicitSize(columnDef: {
  size?: number
  minSize?: number
  maxSize?: number
}): boolean {
  return (
    columnDef.size != null ||
    columnDef.minSize != null ||
    columnDef.maxSize != null
  )
}

export function isDataTableActionsColumn(
  columnId: string,
  meta: ColumnMetaLike | undefined
): boolean {
  return (
    columnId === DATA_TABLE_ACTIONS_COLUMN_ID || meta?.isActionsColumn === true
  )
}

/** Checkbox, STT, expand cây, thao tác — không dùng min-width dữ liệu mặc định. */
export function isDataTableStructuralColumn(
  columnId: string,
  meta: ColumnMetaLike | undefined
): boolean {
  return (
    columnId === DATA_TABLE_SELECTION_COLUMN_ID ||
    columnId === DATA_TABLE_REORDER_COLUMN_ID ||
    columnId === DATA_TABLE_INDEX_COLUMN_ID ||
    columnId === DATA_TABLE_EXPAND_COLUMN_ID ||
    columnId === "_index" ||
    columnId === "attendanceActions" ||
    meta?.isIndexColumn === true ||
    isDataTableActionsColumn(columnId, meta)
  )
}

export function shouldClampDataTableCellContent(
  columnId: string,
  meta: ColumnMetaLike | undefined
): boolean {
  if (isDataTableStructuralColumn(columnId, meta)) return false
  if (meta?.disableCellLineClamp) return false
  return true
}

export function dataTableCellContentClampClassName(
  columnId: string,
  meta: ColumnMetaLike | undefined
): string | undefined {
  return shouldClampDataTableCellContent(columnId, meta)
    ? DATA_TABLE_CELL_CONTENT_CLAMP_CLASS
    : undefined
}

export function dataTableCellWidthClassName(
  columnId: string,
  meta: ColumnMetaLike | undefined,
  columnDef?: { size?: number; minSize?: number; maxSize?: number }
): string {
  const hasExplicit =
    columnHasExplicitWidthClass(meta) ||
    Boolean(columnDef && columnDefHasExplicitSize(columnDef))
  const isStructural = isDataTableStructuralColumn(columnId, meta)
  return cn(
    "align-middle whitespace-normal",
    isStructural || hasExplicit
      ? "min-w-0"
      : DATA_TABLE_DEFAULT_DATA_COLUMN_MIN_WIDTH_CLASS,
    meta?.className
  )
}

/**
 * Gắn `min-w-[180px]` + `minSize: 180` cho cột dữ liệu khi page chưa khai báo width.
 */
export function applyDefaultDataColumnWidths<TData>(
  columns: ColumnDef<TData, unknown>[]
): ColumnDef<TData, unknown>[] {
  return columns.map((column) => {
    const group = column as ColumnDef<TData, unknown> & {
      columns?: ColumnDef<TData, unknown>[]
    }
    const children = group.columns
      ? applyDefaultDataColumnWidths(group.columns)
      : undefined

    const id = resolveDataTableColumnId(column) ?? ""
    const meta = column.meta as ColumnMetaLike | undefined
    const base = children ? { ...column, columns: children } : column

    if (isDataTableStructuralColumn(id, meta)) {
      return base
    }

    const hasExplicit =
      columnHasExplicitWidthClass(meta) || columnDefHasExplicitSize(column)

    if (hasExplicit) {
      return base
    }

    return {
      ...base,
      minSize: DATA_TABLE_DEFAULT_DATA_COLUMN_MIN_SIZE,
      meta: {
        ...meta,
        className: cn(
          DATA_TABLE_DEFAULT_DATA_COLUMN_MIN_WIDTH_CLASS,
          meta?.className
        ),
      },
    }
  })
}

import type { ColumnDef } from "@tanstack/react-table"
import { applyDefaultDataColumnWidths } from "./data-table-column-width"
import {
  DATA_TABLE_ACTIONS_COLUMN_ID,
  TABLE_ACTIONS_COLUMN_META,
} from "./table-row-actions"

export function resolveDataTableColumnId<TData>(
  column: ColumnDef<TData, unknown>
): string | undefined {
  if (column.id) return column.id
  const accessorKey = (column as { accessorKey?: unknown }).accessorKey
  if (typeof accessorKey === "string") return accessorKey
  return undefined
}

export function dataTableColumnsHasActionsColumn<TData>(
  columns: ColumnDef<TData, unknown>[]
): boolean {
  const walk = (cols: ColumnDef<TData, unknown>[]): boolean => {
    for (const col of cols) {
      const group = col as ColumnDef<TData, unknown> & {
        columns?: ColumnDef<TData, unknown>[]
      }
      if (group.columns?.length && walk(group.columns)) return true
      const id = resolveDataTableColumnId(col)
      if (id === DATA_TABLE_ACTIONS_COLUMN_ID || col.meta?.isActionsColumn) {
        return true
      }
    }
    return false
  }
  return walk(columns)
}

/** Gộp meta chuẩn cho cột `actions` / `isActionsColumn` — không cần khai báo meta thủ công. */
export function normalizeDataTableColumns<TData>(
  columns: ColumnDef<TData, unknown>[]
): ColumnDef<TData, unknown>[] {
  const normalized = columns.map((column) => {
    const groupColumn = column as ColumnDef<TData, unknown> & {
      columns?: ColumnDef<TData, unknown>[]
    }
    const children = groupColumn.columns
      ? normalizeDataTableColumns(groupColumn.columns)
      : undefined
    const id = resolveDataTableColumnId(column)
    const isActions =
      id === DATA_TABLE_ACTIONS_COLUMN_ID ||
      column.meta?.isActionsColumn === true

    if (!isActions && !children) return column

    if (!isActions && children) {
      return { ...column, columns: children }
    }

    return {
      ...column,
      ...(id === DATA_TABLE_ACTIONS_COLUMN_ID && !column.id
        ? { id: DATA_TABLE_ACTIONS_COLUMN_ID }
        : {}),
      enableColumnFilter: column.enableColumnFilter ?? false,
      enableSorting: column.enableSorting ?? false,
      ...(children ? { columns: children } : {}),
      meta: {
        ...TABLE_ACTIONS_COLUMN_META,
        ...column.meta,
      },
    }
  })
  return applyDefaultDataColumnWidths(normalized)
}

type DefineDataTableActionsColumnOptions<TData> = {
  header?: string
  enableColumnFilter?: boolean
  filterFn?: ColumnDef<TData, unknown>["filterFn"]
  columnMeta?: ColumnDef<TData, unknown>["meta"]
  cell: NonNullable<ColumnDef<TData, unknown>["cell"]>
}

/** Cột thao tác tùy chỉnh — tự gắn `id` + meta chuẩn để menu chuột phải đồng bộ với menu ⋯. */
export function defineDataTableActionsColumn<TData>(
  options: DefineDataTableActionsColumnOptions<TData>
): ColumnDef<TData, unknown> {
  const {
    header = "Thao tác",
    enableColumnFilter = false,
    filterFn,
    columnMeta,
    cell,
  } = options

  return {
    id: DATA_TABLE_ACTIONS_COLUMN_ID,
    header,
    enableSorting: false,
    enableColumnFilter,
    ...(filterFn ? { filterFn } : {}),
    meta: { ...TABLE_ACTIONS_COLUMN_META, ...columnMeta },
    cell,
  }
}

src/components/data-table/data-table-hor.content:
"use client"

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react"
import { cn } from "../../lib/utils"

const TABLE_CONTAINER_SELECTOR = '[data-slot="table-container"]'
const SCROLL_EDGE_THRESHOLD_PX = 6

export type DataTableHorizontalScrollProps = {
  children: ReactNode
  /** Thanh cuộn ngang phía trên bảng (đồng bộ với table-container). @default false */
  enabled?: boolean
  className?: string
  /** Đổi khi bảng mount lại (loading, số dòng…) để gắn lại listener scroll. */
  watchKey?: string | number
}

export function DataTableHorizontalScroll({
  children,
  enabled = false,
  className,
  watchKey,
}: DataTableHorizontalScrollProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const topScrollRef = useRef<HTMLDivElement>(null)
  const scrollElRef = useRef<HTMLElement | null>(null)
  const syncingRef = useRef(false)
  const [showTopBar, setShowTopBar] = useState(false)
  const [spacerWidth, setSpacerWidth] = useState(0)

  const updateMetrics = useCallback(() => {
    const el = scrollElRef.current
    if (!el) {
      setShowTopBar(false)
      setSpacerWidth(0)
      return
    }
    const needsHorizontalScroll =
      el.scrollWidth > el.clientWidth + SCROLL_EDGE_THRESHOLD_PX
    setShowTopBar(needsHorizontalScroll)
    setSpacerWidth(el.scrollWidth)
    if (topScrollRef.current) {
      topScrollRef.current.scrollLeft = el.scrollLeft
    }
  }, [])

  const syncFromTable = useCallback(() => {
    const el = scrollElRef.current
    const top = topScrollRef.current
    if (!el || !top || syncingRef.current) return
    syncingRef.current = true
    top.scrollLeft = el.scrollLeft
    syncingRef.current = false
  }, [])

  const syncFromTop = useCallback(() => {
    const el = scrollElRef.current
    const top = topScrollRef.current
    if (!el || !top || syncingRef.current) return
    syncingRef.current = true
    el.scrollLeft = top.scrollLeft
    syncingRef.current = false
  }, [])

  useEffect(() => {
    if (!enabled) return
    const root = rootRef.current
    if (!root) return

    let resizeObserver: ResizeObserver | null = null
    let rafId = 0

    const detach = () => {
      cancelAnimationFrame(rafId)
      resizeObserver?.disconnect()
      resizeObserver = null
      scrollElRef.current?.removeEventListener("scroll", syncFromTable)
      topScrollRef.current?.removeEventListener("scroll", syncFromTop)
      scrollElRef.current = null
    }

    const attach = () => {
      detach()
      const el = root.querySelector(
        TABLE_CONTAINER_SELECTOR
      ) as HTMLElement | null
      if (!el) return false
      scrollElRef.current = el
      updateMetrics()
      el.addEventListener("scroll", syncFromTable, { passive: true })
      topScrollRef.current?.addEventListener("scroll", syncFromTop, {
        passive: true,
      })
      resizeObserver = new ResizeObserver(() => {
        cancelAnimationFrame(rafId)
        rafId = requestAnimationFrame(updateMetrics)
      })
      resizeObserver.observe(el)
      const table = el.querySelector("table")
      if (table) resizeObserver.observe(table)
      return true
    }

    if (!attach()) {
      rafId = requestAnimationFrame(() => attach())
    }

    return detach
  }, [enabled, syncFromTable, syncFromTop, updateMetrics, watchKey])

  if (!enabled) {
    return <div className={className}>{children}</div>
  }

  return (
    <div ref={rootRef} className={cn("flex flex-col", className)}>
      <div
        ref={topScrollRef}
        className={cn(
          "shrink-0 overflow-x-auto overflow-y-hidden border-b border-border/60 bg-muted/15",
          !showTopBar &&
            "pointer-events-none h-0 overflow-hidden border-b-0 opacity-0"
        )}
        style={showTopBar ? { height: "0.75rem" } : undefined}
        onScroll={syncFromTop}
        aria-hidden={!showTopBar}
        tabIndex={showTopBar ? 0 : -1}
        aria-label="Cuộn ngang bảng"
      >
        <div aria-hidden style={{ width: spacerWidth, height: 1 }} />
      </div>
      {children}
    </div>
  )
}

src/components/data-table/data-table-pag.content:
"use client"

import { useEffect, useId, useMemo, useState } from "react"
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  Loader2,
  Rows3,
} from "lucide-react"
import { Button } from "../button"
import { Input } from "../input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../select"
import { cn } from "../../lib/utils"

/** Mức page size dùng chung (API admin cho phép tới 5000). */
export const ADMIN_DATA_TABLE_PAGE_SIZE_OPTIONS = [
  10, 15, 20, 25, 50, 100, 500, 1000,
] as const

export const ADMIN_DATA_TABLE_MIN_PAGE_SIZE = 1
export const ADMIN_DATA_TABLE_MAX_PAGE_SIZE = 5000

const CUSTOM_PAGE_SIZE_VALUE = "__custom__"

export type AdminDataTableServerPaginationConfig = {
  mode?: "server"
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
  pageSizeOptions?: readonly number[]
  maxPageSize?: number
  emptySummary?: string
  itemLabel?: string
  isLoading?: boolean
  /** Số dòng thực tế đang hiển thị (thường = `data.length` từ server). */
  currentPageRowCount?: number
  /** Trang / limit server trả về sau chuẩn hóa — đồng bộ UI khi khác state client. */
  appliedPage?: number
  appliedPageSize?: number
  /** Nút "Tất cả" — gọi khi user muốn tải/hiển thị đủ bản ghi (server fetch). */
  onShowAllRows?: () => void
  showAllPageSizeOption?: boolean
}

export type AdminDataTableClientPaginationConfig = {
  mode: "client"
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
  pageSizeOptions?: readonly number[]
  maxPageSize?: number
  emptySummary?: string
  itemLabel?: string
  isLoading?: boolean
  currentPageRowCount?: number
  appliedPage?: number
  appliedPageSize?: number
  /** Hiện nút đặt page size = tổng bản ghi đã lọc (client). @default true */
  showAllPageSizeOption?: boolean
  onShowAllRows?: () => void
}

export type AdminDataTablePaginationConfig =
  | AdminDataTableServerPaginationConfig
  | AdminDataTableClientPaginationConfig

export type AdminDataTablePaginationProps = AdminDataTablePaginationConfig

function clampPageSize(value: number, maxPageSize: number): number {
  if (!Number.isFinite(value)) return ADMIN_DATA_TABLE_MIN_PAGE_SIZE
  return Math.min(
    maxPageSize,
    Math.max(ADMIN_DATA_TABLE_MIN_PAGE_SIZE, Math.floor(value))
  )
}

function buildVisiblePages(
  page: number,
  totalPages: number
): Array<number | "ellipsis"> {
  if (totalPages <= 1) return totalPages === 1 ? [1] : []
  if (totalPages <= 7) {
    return Array.from({ length: totalPages }, (_, i) => i + 1)
  }

  const pages = new Set<number>([1, totalPages, page, page - 1, page + 1])
  const sorted = [...pages]
    .filter((p) => p >= 1 && p <= totalPages)
    .sort((a, b) => a - b)

  const result: Array<number | "ellipsis"> = []
  let prev = 0
  for (const p of sorted) {
    if (prev && p - prev > 1) result.push("ellipsis")
    result.push(p)
    prev = p
  }
  return result
}

function resolvePageSizeOptions(
  pageSize: number,
  pageSizeOptions?: readonly number[]
): number[] {
  const base = [...(pageSizeOptions ?? ADMIN_DATA_TABLE_PAGE_SIZE_OPTIONS)]
  const merged = new Set(base)
  merged.add(pageSize)
  return [...merged].sort((a, b) => a - b)
}

export function AdminDataTablePagination({
  page,
  pageSize,
  total,
  onPageChange,
  onPageSizeChange,
  pageSizeOptions,
  maxPageSize = ADMIN_DATA_TABLE_MAX_PAGE_SIZE,
  emptySummary = "Không có dữ liệu",
  itemLabel,
  isLoading = false,
  currentPageRowCount,
  appliedPage,
  appliedPageSize,
  showAllPageSizeOption = true,
  onShowAllRows,
}: AdminDataTablePaginationProps) {
  const pageSizeSelectId = useId()
  const pageJumpId = useId()
  const empty = !isLoading && total === 0
  const navDisabled = isLoading || empty

  const displayPageSize = appliedPageSize ?? pageSize
  const displayPage = appliedPage ?? page

  const resolvedPageSizeOptions = useMemo(
    () => resolvePageSizeOptions(displayPageSize, pageSizeOptions),
    [displayPageSize, pageSizeOptions]
  )

  const pageSizeInPresets = resolvedPageSizeOptions.includes(displayPageSize)

  const [customPageSizeMode, setCustomPageSizeMode] = useState(
    () => !pageSizeInPresets
  )
  const [draftPageSize, setDraftPageSize] = useState(String(displayPageSize))
  const [draftPage, setDraftPage] = useState(String(displayPage))

  useEffect(() => {
    setDraftPageSize(String(displayPageSize))
    if (pageSizeInPresets) setCustomPageSizeMode(false)
  }, [displayPageSize, pageSizeInPresets])

  useEffect(() => {
    setDraftPage(String(displayPage))
  }, [displayPage])

  const totalPages = Math.max(
    1,
    Math.ceil(total / Math.max(1, displayPageSize))
  )
  const safePage = Math.min(Math.max(1, displayPage), totalPages)

  useEffect(() => {
    if (isLoading || total <= 0) return
    if (appliedPage != null && appliedPage !== page) {
      onPageChange(appliedPage)
      return
    }
    if (page > totalPages) {
      onPageChange(totalPages)
    }
  }, [appliedPage, isLoading, onPageChange, page, total, totalPages])

  useEffect(() => {
    if (isLoading) return
    if (appliedPageSize != null && appliedPageSize !== pageSize) {
      onPageSizeChange(appliedPageSize)
    }
  }, [appliedPageSize, isLoading, onPageSizeChange, pageSize])

  const from = empty || total <= 0 ? 0 : (safePage - 1) * displayPageSize + 1
  const rowsOnPage =
    currentPageRowCount ??
    (empty || total <= 0
      ? 0
      : Math.min(displayPageSize, Math.max(0, total - from + 1)))
  const to =
    empty || total <= 0 || rowsOnPage <= 0
      ? 0
      : Math.min(from + rowsOnPage - 1, total)
  const showingAll =
    !empty && total > 0 && displayPageSize >= total && rowsOnPage >= total

  const summary = useMemo(() => {
    if (isLoading && empty) return "Đang tải…"
    if (empty) return emptySummary
    if (showingAll) {
      return itemLabel
        ? `Hiển thị tất cả ${total} ${itemLabel}`
        : `Hiển thị tất cả ${total}`
    }
    return itemLabel
      ? `Hiển thị ${from}–${to} / ${total} ${itemLabel}`
      : `Hiển thị ${from}–${to} / ${total}`
  }, [empty, emptySummary, from, isLoading, itemLabel, showingAll, to, total])

  const visiblePages = useMemo(
    () => buildVisiblePages(safePage, totalPages),
    [safePage, totalPages]
  )

  const commitPageSize = () => {
    const parsed = Number.parseInt(draftPageSize.trim(), 10)
    const next = clampPageSize(parsed, maxPageSize)
    setDraftPageSize(String(next))
    if (next !== pageSize) onPageSizeChange(next)
  }

  const commitPageJump = () => {
    const parsed = Number.parseInt(draftPage.trim(), 10)
    if (!Number.isFinite(parsed)) {
      setDraftPage(String(safePage))
      return
    }
    const next = Math.min(totalPages, Math.max(1, parsed))
    setDraftPage(String(next))
    if (next !== safePage) onPageChange(next)
  }

  const showAllRows = () => {
    if (onShowAllRows) {
      onShowAllRows()
      return
    }
    if (total <= 0) return
    const next = clampPageSize(total, maxPageSize)
    setDraftPageSize(String(next))
    setCustomPageSizeMode(false)
    if (next !== pageSize) onPageSizeChange(next)
  }

  const canShowAll =
    total > 0 &&
    displayPageSize < total &&
    (onShowAllRows != null || (showAllPageSizeOption && total <= maxPageSize))

  const selectValue = customPageSizeMode
    ? CUSTOM_PAGE_SIZE_VALUE
    : String(displayPageSize)

  const showPageJump = totalPages > 7

  return (
    <div
      className="flex w-full min-w-0 flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"
      aria-busy={isLoading}
    >
      <p
        className="min-w-0 text-sm text-muted-foreground"
        aria-live="polite"
        aria-atomic="true"
      >
        {isLoading ? (
          <span className="inline-flex items-center gap-2">
            <Loader2
              className="size-3.5 shrink-0 animate-spin text-muted-foreground/80"
              aria-hidden
            />
            <span>{summary}</span>
          </span>
        ) : (
          <span>
            {empty ? (
              summary
            ) : (
              <>
                {showingAll ? (
                  <>
                    Hiển thị tất cả{" "}
                    <span className="font-medium text-foreground tabular-nums">
                      {total}
                    </span>
                    {itemLabel ? ` ${itemLabel}` : null}
                  </>
                ) : (
                  <>
                    Hiển thị{" "}
                    <span className="font-medium text-foreground tabular-nums">
                      {from}–{to}
                    </span>{" "}
                    /{" "}
                    <span className="font-medium text-foreground tabular-nums">
                      {total}
                    </span>
                    {itemLabel ? ` ${itemLabel}` : null}
                  </>
                )}
              </>
            )}
          </span>
        )}
      </p>

      <div className="flex flex-wrap items-center justify-end gap-2 sm:gap-2.5">
        <div
          className="flex items-center gap-1.5 rounded-lg border border-border/70 bg-background p-1 shadow-xs"
          role="group"
          aria-label="Số dòng mỗi trang"
        >
          <label
            htmlFor={
              customPageSizeMode
                ? `${pageSizeSelectId}-custom`
                : pageSizeSelectId
            }
            className="inline-flex items-center gap-1.5 ps-1.5 text-xs font-medium whitespace-nowrap text-muted-foreground"
          >
            <Rows3 className="size-3.5 shrink-0 opacity-70" aria-hidden />
            <span className="hidden min-[420px]:inline">Mỗi trang</span>
          </label>

          {customPageSizeMode ? (
            <Input
              id={`${pageSizeSelectId}-custom`}
              type="number"
              inputMode="numeric"
              min={ADMIN_DATA_TABLE_MIN_PAGE_SIZE}
              max={maxPageSize}
              disabled={navDisabled}
              value={draftPageSize}
              onChange={(e) => setDraftPageSize(e.target.value)}
              onBlur={commitPageSize}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  commitPageSize()
                }
                if (e.key === "Escape") {
                  setDraftPageSize(String(displayPageSize))
                  setCustomPageSizeMode(!pageSizeInPresets)
                }
              }}
              aria-label="Nhập số dòng mỗi trang"
              title={`Nhập từ ${ADMIN_DATA_TABLE_MIN_PAGE_SIZE} đến ${maxPageSize}, Enter để áp dụng`}
              className="h-8 w-[4.5rem] border-0 bg-transparent px-2 shadow-none focus-visible:ring-1"
              autoFocus
            />
          ) : (
            <Select
              value={selectValue}
              onValueChange={(value) => {
                if (value === CUSTOM_PAGE_SIZE_VALUE) {
                  setCustomPageSizeMode(true)
                  return
                }
                const next = clampPageSize(Number(value), maxPageSize)
                setDraftPageSize(String(next))
                if (next !== displayPageSize) onPageSizeChange(next)
              }}
              disabled={navDisabled}
            >
              <SelectTrigger
                id={pageSizeSelectId}
                size="sm"
                className="h-8 min-w-[4.5rem] border-0 bg-transparent shadow-none focus-visible:ring-1"
                aria-label="Chọn số dòng mỗi trang"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent align="end">
                {resolvedPageSizeOptions.map((size) => (
                  <SelectItem key={size} value={String(size)}>
                    {size}
                  </SelectItem>
                ))}
                <SelectItem value={CUSTOM_PAGE_SIZE_VALUE}>
                  Tùy chỉnh…
                </SelectItem>
              </SelectContent>
            </Select>
          )}

          {canShowAll ? (
            <Button
              type="button"
              variant="secondary"
              size="sm"
              className="h-8 shrink-0 rounded-md px-2.5 text-xs"
              disabled={navDisabled}
              onClick={showAllRows}
              title="Hiển thị toàn bộ dòng đang có trong bảng"
            >
              Tất cả
            </Button>
          ) : null}
        </div>

        <nav
          className="flex items-center gap-0.5 rounded-lg border border-border/70 bg-background p-0.5 shadow-xs"
          aria-label="Phân trang bảng"
        >
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 shrink-0 rounded-md"
            disabled={safePage <= 1 || navDisabled}
            onClick={() => onPageChange(1)}
            aria-label="Trang đầu"
            title="Trang đầu"
          >
            <ChevronsLeft className="size-4" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 shrink-0 rounded-md"
            disabled={safePage <= 1 || navDisabled}
            onClick={() => onPageChange(Math.max(1, safePage - 1))}
            aria-label="Trang trước"
            title="Trang trước"
          >
            <ChevronLeft className="size-4" />
          </Button>

          <div className="hidden items-center gap-0.5 px-0.5 min-[480px]:flex">
            {visiblePages.map((item, index) =>
              item === "ellipsis" ? (
                <span
                  key={`ellipsis-${index}`}
                  className="flex size-8 items-center justify-center text-sm text-muted-foreground select-none"
                  aria-hidden
                >
                  …
                </span>
              ) : (
                <Button
                  key={item}
                  type="button"
                  variant={item === safePage ? "default" : "ghost"}
                  size="icon"
                  className={cn(
                    "size-8 shrink-0 rounded-md text-sm tabular-nums",
                    item === safePage && "pointer-events-none shadow-sm"
                  )}
                  disabled={navDisabled}
                  onClick={() => onPageChange(item)}
                  aria-label={`Trang ${item}`}
                  aria-current={item === safePage ? "page" : undefined}
                >
                  {item}
                </Button>
              )
            )}
          </div>

          <span className="px-2 text-xs font-medium text-muted-foreground tabular-nums max-[479px]:inline min-[480px]:hidden">
            {safePage}/{totalPages}
          </span>

          {showPageJump ? (
            <div className="hidden items-center gap-1 px-1 lg:flex">
              <label htmlFor={pageJumpId} className="sr-only">
                Nhảy tới trang
              </label>
              <Input
                id={pageJumpId}
                type="number"
                inputMode="numeric"
                min={1}
                max={totalPages}
                disabled={navDisabled}
                value={draftPage}
                onChange={(e) => setDraftPage(e.target.value)}
                onBlur={commitPageJump}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault()
                    commitPageJump()
                  }
                }}
                aria-label={`Trang (1–${totalPages})`}
                title="Nhập số trang, Enter để chuyển"
                className="h-8 w-12 border-0 bg-muted/40 px-1.5 text-center text-xs tabular-nums shadow-none focus-visible:ring-1"
              />
              <span className="text-xs text-muted-foreground tabular-nums">
                / {totalPages}
              </span>
            </div>
          ) : null}

          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 shrink-0 rounded-md"
            disabled={safePage >= totalPages || navDisabled}
            onClick={() => onPageChange(Math.min(totalPages, safePage + 1))}
            aria-label="Trang sau"
            title="Trang sau"
          >
            <ChevronRight className="size-4" />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-8 shrink-0 rounded-md"
            disabled={safePage >= totalPages || navDisabled}
            onClick={() => onPageChange(totalPages)}
            aria-label="Trang cuối"
            title="Trang cuối"
          >
            <ChevronsRight className="size-4" />
          </Button>
        </nav>
      </div>
    </div>
  )
}

src/components/data-table/data-table-row.content:
"use client"

import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useRef,
  type ReactNode,
} from "react"

import type { DataTableRowActionGroupId } from "./table-row-actions"

import type { DataTableRowActionItem } from "./table-row-actions"

import {
  getDisplayableRowActions,
  type RowActionsMenuGroupConfig,
} from "./row-actions-menu-shared"

import {
  DataTableRowActionConfirmRunnerProvider,
  useRowActionConfirm,
} from "./row-action-confirm"

const DEFAULT_TABLE_SCOPE_ID = "default"

const DataTableScopeContext = createContext<string>(DEFAULT_TABLE_SCOPE_ID)

export function DataTableScopeProvider({
  scopeId,

  children,
}: {
  scopeId: string

  children: ReactNode
}) {
  return (
    <DataTableScopeContext.Provider value={scopeId}>
      {children}
    </DataTableScopeContext.Provider>
  )
}

export function useDataTableScopeId(): string {
  return useContext(DataTableScopeContext)
}

function buildScopedRowKey(scopeId: string, rowId: string): string {
  return `${scopeId}::${rowId}`
}

export type RegisteredDataTableRowActions = {
  actions: DataTableRowActionItem[]

  groups?: Partial<Record<DataTableRowActionGroupId, RowActionsMenuGroupConfig>>

  busy?: boolean

  autoConfirmDangerousActions?: boolean
}

type DataTableRowActionsRegistryValue = {
  registerScoped: (
    scopeId: string,

    rowId: string,

    entry: RegisteredDataTableRowActions | null
  ) => void

  getScoped: (
    scopeId: string,

    rowId: string
  ) => RegisteredDataTableRowActions | null

  hasVisibleActionsScoped: (scopeId: string, rowId: string) => boolean
}

const DataTableRowActionsRegistryContext =
  createContext<DataTableRowActionsRegistryValue | null>(null)

const DataTableRowActionsRowIdContext = createContext<string | null>(null)

function rowHasVisibleActions(
  entry: RegisteredDataTableRowActions | null
): boolean {
  if (!entry) return false

  return getDisplayableRowActions(entry.actions).length > 0
}

export function DataTableRowActionsRegistryProvider({
  children,
}: {
  children: ReactNode
}) {
  const registryRef = useRef(new Map<string, RegisteredDataTableRowActions>())

  const value = useMemo<DataTableRowActionsRegistryValue>(
    () => ({
      registerScoped: (scopeId, rowId, entry) => {
        const key = buildScopedRowKey(scopeId, rowId)

        if (entry == null) {
          registryRef.current.delete(key)

          return
        }

        registryRef.current.set(key, entry)
      },

      getScoped: (scopeId, rowId) =>
        registryRef.current.get(buildScopedRowKey(scopeId, rowId)) ?? null,

      hasVisibleActionsScoped: (scopeId, rowId) =>
        rowHasVisibleActions(
          registryRef.current.get(buildScopedRowKey(scopeId, rowId)) ?? null
        ),
    }),

    []
  )

  return (
    <DataTableRowActionsRegistryContext.Provider value={value}>
      {children}
    </DataTableRowActionsRegistryContext.Provider>
  )
}

export function DataTableRowActionsRowProvider({
  rowId,

  children,
}: {
  rowId: string

  children: ReactNode
}) {
  const registry = useDataTableRowActionsRegistryOptional()

  const scopeId = useDataTableScopeId()

  const { runAction, confirmDialog } = useRowActionConfirm(false)

  const runRowAction = useCallback(
    (action: DataTableRowActionItem) => {
      const entry = registry?.getScoped(scopeId, rowId)

      const autoConfirm = entry?.autoConfirmDangerousActions ?? false

      runAction(action, autoConfirm)
    },

    [registry, rowId, runAction, scopeId]
  )

  return (
    <DataTableRowActionsRowIdContext.Provider value={rowId}>
      <DataTableRowActionConfirmRunnerProvider
        runAction={runRowAction}
        confirmDialog={confirmDialog}
      >
        {children}
      </DataTableRowActionConfirmRunnerProvider>
    </DataTableRowActionsRowIdContext.Provider>
  )
}

export function useDataTableRowActionsRegistry() {
  const ctx = useContext(DataTableRowActionsRegistryContext)

  if (!ctx) {
    throw new Error(
      "useDataTableRowActionsRegistry phải nằm trong DataTableRowActionsRegistryProvider"
    )
  }

  return ctx
}

export function useDataTableRowActionsRegistryOptional() {
  return useContext(DataTableRowActionsRegistryContext)
}

export function useDataTableRowActionsRowId() {
  return useContext(DataTableRowActionsRowIdContext)
}

export function useRegisterDataTableRowActions(
  entry: RegisteredDataTableRowActions | null
) {
  const rowId = useDataTableRowActionsRowId()

  const scopeId = useDataTableScopeId()

  const registry = useDataTableRowActionsRegistryOptional()

  // Đăng ký đồng bộ khi render — chuột phải đọc registry trong cùng commit với cell ⋯.
  if (registry && rowId) {
    registry.registerScoped(scopeId, rowId, entry)
  }

  useLayoutEffect(() => {
    if (!registry || !rowId) return

    registry.registerScoped(scopeId, rowId, entry)
  })

  useLayoutEffect(() => {
    if (!registry || !rowId) return

    return () => registry.registerScoped(scopeId, rowId, null)
  }, [registry, rowId, scopeId])
}

/** Chỉ đăng ký thao tác dòng (không render nút ⋯) — dùng khi cell tự quyết định UI. */

export function DataTableRowActionsRegistrar(
  props: RegisteredDataTableRowActions | null
) {
  useRegisterDataTableRowActions(props)

  return null
}

/** Dòng không có menu ⋯ — tránh menu chuột phải trống (vd. hàng nhóm cây). */
export function DataTableRowActionsClearRegistrar() {
  useRegisterDataTableRowActions(null)

  return null
}

"use client"

import {
  useState,
  type ComponentProps,
  type CSSProperties,
  type Ref,
  type ReactNode,
} from "react"
import { flushSync } from "react-dom"
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuGroup,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "../context-menu"
import { TableRow } from "../table"
import { cn } from "../../lib/utils"
import {
  groupRowActions,
  RowActionMenuItemBody,
  RowActionsMenuGroups,
  rowActionsGroupLabelClassName,
} from "./row-actions-menu-shared"
import {
  useDataTableRowActionsRegistryOptional,
  useDataTableScopeId,
  type RegisteredDataTableRowActions,
} from "./data-table-row-actions-registry"
import type { DataTableRowActionItem } from "./table-row-actions"
import { useDataTableRowActionRunnerOptional } from "./row-action-confirm"

function ContextMenuRowActionItem({
  action,
  onRun,
  busy,
}: {
  action: DataTableRowActionItem
  onRun: (action: DataTableRowActionItem) => void
  busy?: boolean
}) {
  return (
    <ContextMenuItem
      disabled={action.disabled || busy}
      variant={action.menuVariant ?? "default"}
      label={action.label}
      onClick={() => {
        onRun(action)
      }}
      title={action.title}
      className="items-start gap-2.5 py-2"
    >
      <RowActionMenuItemBody action={action} />
    </ContextMenuItem>
  )
}

function DataTableRowContextMenuContent({
  entry,
  runAction,
}: {
  entry: RegisteredDataTableRowActions
  runAction: (action: DataTableRowActionItem) => void
}) {
  const { groups, byGroup, orderedGroups } = groupRowActions(
    entry.actions,
    entry.groups
  )

  if (orderedGroups.length === 0) {
    return (
      <ContextMenuContent className="w-64 p-1.5">
        <ContextMenuItem disabled className="text-muted-foreground">
          Không có thao tác khả dụng
        </ContextMenuItem>
      </ContextMenuContent>
    )
  }

  return (
    <ContextMenuContent className="w-64 p-1.5">
      <RowActionsMenuGroups
        orderedGroups={orderedGroups}
        groups={groups}
        byGroup={byGroup}
        renderSeparator={() => <ContextMenuSeparator />}
        renderGroup={(children) => (
          <ContextMenuGroup>{children}</ContextMenuGroup>
        )}
        renderGroupLabel={(config, GroupIcon) =>
          config.sublabel ? (
            <ContextMenuLabel className={rowActionsGroupLabelClassName(config)}>
              {config.label}
            </ContextMenuLabel>
          ) : (
            <ContextMenuLabel className={rowActionsGroupLabelClassName(config)}>
              {GroupIcon ? (
                <GroupIcon className="size-3.5 shrink-0 text-primary" />
              ) : null}
              {config.label}
            </ContextMenuLabel>
          )
        }
        renderItem={(action) => (
          <ContextMenuRowActionItem
            key={action.key}
            action={action}
            onRun={runAction}
            busy={entry.busy}
          />
        )}
      />
    </ContextMenuContent>
  )
}

export type DataTableRowContextMenuProps = {
  rowId: string
  enabled?: boolean
  rowRef?: Ref<HTMLTableRowElement>
  className?: string
  style?: CSSProperties
  children: ReactNode
} & Omit<ComponentProps<typeof TableRow>, "children" | "className" | "style">

export function DataTableRowContextMenu({
  rowId,
  enabled = true,
  rowRef,
  className,
  style,
  children,
  ...tableRowProps
}: DataTableRowContextMenuProps) {
  const registry = useDataTableRowActionsRegistryOptional()
  const scopeId = useDataTableScopeId()
  const runAction = useDataTableRowActionRunnerOptional()
  const [menuOpen, setMenuOpen] = useState(false)

  const resolveRowActions = () => {
    if (!registry) return null
    const entry = registry.getScoped(scopeId, rowId)
    if (!entry || !registry.hasVisibleActionsScoped(scopeId, rowId)) {
      return null
    }
    return entry
  }

  const openEntry = menuOpen ? resolveRowActions() : null

  if (!enabled || !registry) {
    return (
      <TableRow
        ref={rowRef}
        className={className}
        style={style}
        {...tableRowProps}
      >
        {children}
      </TableRow>
    )
  }

  return (
    <ContextMenu
      open={menuOpen}
      onOpenChange={(open) => {
        if (open) {
          if (!resolveRowActions()) {
            setMenuOpen(false)
            return
          }
          flushSync(() => {
            setMenuOpen(true)
          })
          return
        }
        setMenuOpen(false)
      }}
    >
      <ContextMenuTrigger
        render={(triggerProps) => {
          const {
            ref: triggerRef,
            className: triggerClassName,
            style: triggerStyle,
            ...restTrigger
          } = triggerProps

          return (
            <TableRow
              {...tableRowProps}
              {...restTrigger}
              className={cn(className, triggerClassName)}
              style={{ ...style, ...triggerStyle }}
              onContextMenu={(event) => {
                restTrigger.onContextMenu?.(event)
                if (event.defaultPrevented) return
                if (!resolveRowActions()) {
                  event.preventDefault()
                }
              }}
              ref={(node) => {
                if (typeof triggerRef === "function") {
                  triggerRef(node)
                } else if (triggerRef) {
                  triggerRef.current = node
                }
                if (typeof rowRef === "function") {
                  rowRef(node)
                } else if (rowRef) {
                  rowRef.current = node
                }
              }}
            />
          )
        }}
      >
        {children}
      </ContextMenuTrigger>
      {menuOpen ? (
        runAction && openEntry ? (
          <DataTableRowContextMenuContent
            entry={openEntry}
            runAction={runAction}
          />
        ) : (
          <ContextMenuContent className="w-64 p-1.5">
            <ContextMenuItem disabled className="text-muted-foreground">
              Không có thao tác khả dụng
            </ContextMenuItem>
          </ContextMenuContent>
        )
      ) : null}
    </ContextMenu>
  )
}

import type { Row } from "@tanstack/react-table"

/** STT phẳng: `1.`, `2.` … */
export function formatFlatRowIndex(order: number, offset = 0): string {
  return `${offset + order + 1}.`
}

/**
 * STT cây theo cấp anh em: `1.`, `1.1.`, `1.2.`, `2.` …
 * `rootOffset` chỉ cộng vào số gốc (phân trang).
 */
export function formatHierarchicalRowIndex(
  row: Row<unknown>,
  rootOffset = 0
): string {
  const chain: Row<unknown>[] = []
  let current: Row<unknown> | undefined = row
  while (current) {
    chain.unshift(current)
    current = current.getParentRow()
  }
  const parts = chain.map((item, level) =>
    level === 0 ? item.index + 1 + rootOffset : item.index + 1
  )
  return `${parts.join(".")}.`
}

export function formatHierarchicalIndexFromPath(path: number[]): string {
  if (path.length === 0) return ""
  return `${path.join(".")}.`
}

