"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { Loader2 } from "lucide-react"
import { Input } from "../input"
import { cn } from "../../lib/utils"

export type DataTableUserSearchOption = {
  id: string | number
  label: string
  sublabel?: string
}

export type DataTableUserSearchHandlers = {
  onSearch: (query: string) => Promise<DataTableUserSearchOption[]>
  onResolveUser?: (id: string) => Promise<DataTableUserSearchOption | null>
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

function debounce<TArgs extends unknown[]>(
  fn: (...args: TArgs) => void,
  wait: number
) {
  let timer: ReturnType<typeof setTimeout> | undefined
  const debouncedFn = (...args: TArgs) => {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => fn(...args), wait)
  }
  debouncedFn.cancel = () => {
    if (timer) clearTimeout(timer)
  }
  return debouncedFn
}

function formatUserOption(option: DataTableUserSearchOption): string {
  const label = option.label?.trim()
  const sub = option.sublabel?.trim()
  if (label && sub && label !== sub) return `${label} · ${sub}`
  return label || sub || String(option.id)
}

type DataTableUserSearchFilterProps = {
  controlId: string
  value: string
  onChange: (value: string | undefined) => void
  placeholder?: string
  disabled?: boolean
  handlers: DataTableUserSearchHandlers
}

export function DataTableUserSearchFilter({
  controlId,
  value,
  onChange,
  placeholder = "Tên, email hoặc ID…",
  disabled = false,
  handlers,
}: DataTableUserSearchFilterProps) {
  const listId = `${controlId}-suggestions`
  const rootRef = useRef<HTMLDivElement>(null)
  const [inputText, setInputText] = useState("")
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [suggestions, setSuggestions] = useState<DataTableUserSearchOption[]>(
    []
  )
  const [debouncedSearch, setDebouncedSearch] = useState("")

  const debouncedSetSearch = useMemo(
    () => debounce((next: string) => setDebouncedSearch(next), 300),
    []
  )

  useEffect(
    () => () => {
      debouncedSetSearch.cancel()
    },
    [debouncedSetSearch]
  )

  useEffect(() => {
    const trimmed = value.trim()
    if (!trimmed) {
      setInputText("")
      return
    }
    if (!UUID_RE.test(trimmed) || !handlers.onResolveUser) {
      setInputText(trimmed)
      return
    }
    let cancelled = false
    void handlers
      .onResolveUser(trimmed)
      .then((user) => {
        if (!cancelled) {
          setInputText(user ? formatUserOption(user) : trimmed)
        }
      })
      .catch(() => {
        if (!cancelled) setInputText(trimmed)
      })
    return () => {
      cancelled = true
    }
  }, [handlers, value])

  useEffect(() => {
    const q = debouncedSearch.trim()
    if (!open || q.length < 2) {
      setSuggestions([])
      setLoading(false)
      return
    }

    let cancelled = false
    setLoading(true)
    void handlers
      .onSearch(q)
      .then((items) => {
        if (!cancelled) setSuggestions(items)
      })
      .catch(() => {
        if (!cancelled) setSuggestions([])
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })

    return () => {
      cancelled = true
    }
  }, [debouncedSearch, handlers, open])

  useEffect(() => {
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener("mousedown", onPointerDown)
    return () => document.removeEventListener("mousedown", onPointerDown)
  }, [])

  const applyUser = useCallback(
    (user: DataTableUserSearchOption) => {
      onChange(String(user.id))
      setInputText(formatUserOption(user))
      setOpen(false)
      setSuggestions([])
    },
    [onChange]
  )

  const handleInputChange = (next: string) => {
    setInputText(next)
    setOpen(true)
    debouncedSetSearch(next)
    onChange(next.trim() ? next : undefined)
  }

  const showSuggestions =
    open &&
    (loading || suggestions.length > 0 || debouncedSearch.trim().length >= 2)

  return (
    <div ref={rootRef} className="relative min-w-0">
      <Input
        id={controlId}
        value={inputText}
        onChange={(e) => handleInputChange(e.target.value)}
        onFocus={() => setOpen(true)}
        placeholder={placeholder}
        className="h-8 w-full rounded-md text-sm shadow-none"
        disabled={disabled}
        role="combobox"
        aria-expanded={showSuggestions}
        aria-controls={showSuggestions ? listId : undefined}
        aria-autocomplete="list"
        autoComplete="off"
      />
      {showSuggestions ? (
        <ul
          id={listId}
          role="listbox"
          className="absolute top-[calc(100%+4px)] z-50 max-h-56 w-full overflow-y-auto rounded-lg border border-border bg-popover p-1 shadow-md"
        >
          {loading ? (
            <li className="flex items-center gap-2 px-2 py-2 text-xs text-muted-foreground">
              <Loader2 className="size-3.5 animate-spin" />
              Đang tìm…
            </li>
          ) : null}
          {!loading && suggestions.length === 0 ? (
            <li className="px-2 py-2 text-xs text-muted-foreground">
              Không tìm thấy — vẫn lọc theo ID nếu bạn nhập trực tiếp.
            </li>
          ) : null}
          {suggestions.map((user) => (
            <li
              key={String(user.id)}
              role="option"
              aria-selected={value === String(user.id)}
            >
              <button
                type="button"
                className={cn(
                  "flex w-full flex-col items-start rounded-md px-2 py-1.5 text-left text-xs hover:bg-accent",
                  value === String(user.id) && "bg-accent/60"
                )}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => applyUser(user)}
              >
                <span className="font-medium text-foreground">
                  {user.label}
                </span>
                {user.sublabel ? (
                  <span className="font-mono text-[10px] text-muted-foreground">
                    {user.sublabel}
                    {user.id != null
                      ? ` · ${String(user.id).slice(0, 8)}…`
                      : null}
                  </span>
                ) : null}
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}

src/components/data-table/define-export-.content:
import type { ColumnDef } from "@tanstack/react-table"
import {
  formatAdminDateTime,
  isParsableDateTime,
} from "../../lib/format-admin-datetime"

export type LinkedUserRef = {
  id: string
  name: string | null
  email: string
}

type RelationExportField<T> = {
  id: string
  header: string
  getValue: (row: T) => unknown
  exportWidth?: number
  defaultHidden?: boolean
}

const DATE_RANGE_FIELD_IDS = new Set([
  "createdAt",
  "updatedAt",
  "deletedAt",
  "startDate",
  "endDate",
  "checkinStart",
  "checkinEnd",
  "checkoutStart",
  "checkoutEnd",
  "registrationStart",
  "registrationEnd",
])

function resolveRelationFilterVariant(fieldId: string): "text" | "date-range" {
  if (DATE_RANGE_FIELD_IDS.has(fieldId) || /At$/.test(fieldId)) {
    return "date-range"
  }
  return "text"
}

/** `meta.selectOptions` cho cột boolean/xuất bản — dùng khi export Excel. */
export function defineBooleanSelectExportMeta(
  trueLabel: string,
  falseLabel: string
): { selectOptions: Array<{ value: string; label: string }> } {
  return {
    selectOptions: [
      { value: "true", label: trueLabel },
      { value: "false", label: falseLabel },
    ],
  }
}

function formatRelationCellValue(value: unknown): string {
  if (value == null || value === "") return ""
  if (typeof value === "boolean") return value ? "Có" : "Không"
  if (typeof value === "number" && !isParsableDateTime(value)) {
    return String(value)
  }
  if (isParsableDateTime(value)) {
    const formatted = formatAdminDateTime(value as string | Date | number)
    return formatted === "—" ? "" : formatted
  }
  return String(value)
}

/**
 * Gộp object quan hệ (populate) với field phẳng từ API (assignedToId, assignedToName…).
 */
export function resolveLinkedUser(
  nested: LinkedUserRef | null | undefined,
  flat?: {
    id?: string | null
    name?: string | null
    email?: string | null
  } | null
): LinkedUserRef | null {
  if (nested && (nested.id || nested.email || nested.name)) {
    return {
      id: nested.id || flat?.id || "",
      name: nested.name ?? flat?.name ?? null,
      email: nested.email || flat?.email || "",
    }
  }
  if (flat?.id) {
    return {
      id: flat.id,
      name: flat.name ?? null,
      email: flat.email ?? "",
    }
  }
  return null
}

/**
 * Cột ẩn mặc định cho dữ liệu quan hệ (FK, populate từ API).
 * Bật hiển thị qua "Hiện cột" — cell render giá trị thật, không để trống.
 */
export function defineRelationExportColumns<T>(
  fields: RelationExportField<T>[],
  options?: { enableColumnFilter?: boolean }
): ColumnDef<T, unknown>[] {
  const enableColumnFilter = options?.enableColumnFilter ?? true
  return fields.map((field) => {
    const filterVariant = resolveRelationFilterVariant(field.id)
    const isDateRange = filterVariant === "date-range"
    return {
      id: field.id,
      header: field.header,
      accessorFn: (row) => field.getValue(row),
      enableSorting: false,
      enableColumnFilter,
      ...(enableColumnFilter && !isDateRange ? { filterFn: () => true } : {}),
      meta: {
        defaultHidden: field.defaultHidden ?? true,
        ...(enableColumnFilter
          ? {
              filterVariant,
              filterPlaceholder:
                filterVariant === "date-range" ? "Chọn khoảng ngày" : "Lọc…",
            }
          : { disableColumnFilter: true }),
        exportHeader: field.header,
        exportValue: (row: T) => formatRelationCellValue(field.getValue(row)),
        exportWidth: field.exportWidth,
      },
      cell: ({ row }) => {
        const text = formatRelationCellValue(field.getValue(row.original))
        return text || "—"
      },
    }
  })
}

function linkedUserLabel(user: LinkedUserRef | null | undefined): string {
  if (!user) return ""
  return user.name?.trim() || user.email || user.id
}

/**
 * Cột hiển thị + xuất cho quan hệ User (assignedTo, submittedBy, author…).
 */
export function defineLinkedUserColumns<T>(options: {
  scope: string
  header: string
  getUser: (row: T) => LinkedUserRef | null | undefined
  /** Ẩn cột hiển thị mặc định — vẫn xuất qua "Hiện cột". */
  defaultHidden?: boolean
}): ColumnDef<T, unknown>[] {
  const { scope, header, getUser, defaultHidden = false } = options
  return [
    {
      id: `${scope}Name`,
      header,
      accessorFn: (row) => linkedUserLabel(getUser(row)),
      enableSorting: false,
      enableColumnFilter: true,
      filterFn: () => true,
      meta: {
        defaultHidden,
        filterVariant: "text",
        filterPlaceholder: "Lọc…",
        exportHeader: header,
        exportValue: (row: T) => linkedUserLabel(getUser(row)),
      },
      cell: ({ row }) => linkedUserLabel(getUser(row.original)) || "—",
    },
    ...defineRelationExportColumns<T>([
      {
        id: `${scope}Email`,
        header: `Email — ${header}`,
        getValue: (row) => getUser(row)?.email ?? "",
      },
      {
        id: `${scope}Id`,
        header: `ID — ${header}`,
        getValue: (row) => getUser(row)?.id ?? "",
        defaultHidden: true,
      },
    ]),
  ]
}

src/components/data-table/row-action-con.content:
"use client"

import {
  createContext,
  useCallback,
  useContext,
  useState,
  type ReactNode,
} from "react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "../alert-dialog"
import type { DataTableRowActionItem } from "./table-row-actions"

export type DataTableRowActionConfirm =
  | boolean
  | {
      title: string
      description?: ReactNode
      confirmLabel?: string
      destructive?: boolean
    }

export type ResolvedDataTableRowActionConfirm = {
  title: string
  description?: ReactNode
  confirmLabel: string
  destructive?: boolean
}

const DANGER_ACTION_KEYS = new Set([
  "soft-delete",
  "purge",
  "delete",
  "restore",
  "toggle-active",
  "toggle-inactive",
  "activate",
  "deactivate",
])

function defaultConfirmForAction(
  action: DataTableRowActionItem
): ResolvedDataTableRowActionConfirm | undefined {
  if (action.key === "soft-delete" || action.key === "delete") {
    return {
      title: "Đưa bản ghi vào thùng rác?",
      description:
        action.hint ??
        "Bản ghi sẽ được chuyển vào thùng rác và có thể khôi phục sau.",
      confirmLabel: action.label || "Xóa tạm",
      destructive: true,
    }
  }

  if (action.key === "purge") {
    return {
      title: "Xóa vĩnh viễn bản ghi?",
      description: action.hint ?? "Hành động này không thể hoàn tác.",
      confirmLabel: action.label || "Xóa vĩnh viễn",
      destructive: true,
    }
  }

  if (action.key === "restore") {
    return {
      title: "Khôi phục bản ghi?",
      description: action.hint ?? "Bản ghi sẽ trở lại danh sách chính.",
      confirmLabel: action.label || "Khôi phục",
    }
  }

  if (action.key === "toggle-inactive" || action.key === "deactivate") {
    return {
      title: "Khoá tài khoản?",
      description:
        action.hint ??
        "Tài khoản sẽ bị vô hiệu hóa và phiên đăng nhập hiện tại có thể bị thu hồi.",
      confirmLabel: action.label || "Khoá",
      destructive: true,
    }
  }

  if (action.key === "toggle-active" || action.key === "activate") {
    return {
      title: "Kích hoạt tài khoản?",
      description: action.hint ?? "Cho phép đăng nhập và sử dụng lại.",
      confirmLabel: action.label || "Kích hoạt",
    }
  }

  if (action.menuVariant === "destructive" || action.group === "danger") {
    return {
      title: "Xác nhận thao tác?",
      description: action.hint ?? "Thao tác này có thể không hoàn tác.",
      confirmLabel: action.label || "Xác nhận",
      destructive: true,
    }
  }

  return undefined
}

/** Confirm có tên bản ghi — dùng với menu ⋯ admin. */
export function buildAdminRowActionConfirm(
  key: string,
  recordLabel: string,
  labels?: {
    softDelete?: string
    purge?: string
    restore?: string
    lock?: string
    activate?: string
  }
): DataTableRowActionConfirm | undefined {
  const quoted = `«${recordLabel}»`
  if (key === "soft-delete" || key === "delete") {
    return {
      title: `Đưa ${quoted} vào thùng rác?`,
      description:
        "Bản ghi sẽ được chuyển vào thùng rác và có thể khôi phục sau.",
      confirmLabel: labels?.softDelete ?? "Xóa tạm",
      destructive: true,
    }
  }
  if (key === "purge") {
    return {
      title: `Xóa vĩnh viễn ${quoted}?`,
      description: "Hành động này không thể hoàn tác.",
      confirmLabel: labels?.purge ?? "Xóa vĩnh viễn",
      destructive: true,
    }
  }
  if (key === "restore") {
    return {
      title: `Khôi phục ${quoted}?`,
      description: "Bản ghi sẽ trở lại danh sách chính.",
      confirmLabel: labels?.restore ?? "Khôi phục",
    }
  }
  if (key === "toggle-inactive" || key === "deactivate") {
    return {
      title: `Khoá ${quoted}?`,
      description:
        "Tài khoản sẽ bị vô hiệu hóa và phiên đăng nhập hiện tại có thể bị thu hồi.",
      confirmLabel: labels?.lock ?? "Khoá",
      destructive: true,
    }
  }
  if (key === "toggle-active" || key === "activate") {
    return {
      title: `Kích hoạt ${quoted}?`,
      description: "Cho phép đăng nhập và sử dụng lại.",
      confirmLabel: labels?.activate ?? "Kích hoạt",
    }
  }
  return defaultConfirmForAction({
    key,
    label: "",
    onClick: () => {},
  })
}

/** `confirm: false` tắt; không khai báo + `autoConfirm` → mặc định theo loại thao tác. */
export function resolveRowActionConfirm(
  action: DataTableRowActionItem,
  autoConfirm = true
): DataTableRowActionConfirm | undefined {
  if (action.confirm === false) return undefined
  if (action.confirm === true) {
    return (
      defaultConfirmForAction(action) ?? {
        title: "Xác nhận thao tác?",
        confirmLabel: "Xác nhận",
      }
    )
  }
  if (action.confirm && typeof action.confirm === "object") {
    return action.confirm
  }

  if (!autoConfirm) return undefined

  if (
    DANGER_ACTION_KEYS.has(action.key) ||
    action.menuVariant === "destructive" ||
    action.group === "danger"
  ) {
    return defaultConfirmForAction(action)
  }

  return undefined
}

export function normalizeResolvedRowActionConfirm(
  action: DataTableRowActionItem,
  autoConfirm = true
): ResolvedDataTableRowActionConfirm | null {
  const resolved = resolveRowActionConfirm(action, autoConfirm)
  if (!resolved) return null

  if (resolved === true) {
    return {
      title: "Xác nhận thao tác?",
      description: action.hint ?? "Bạn có chắc muốn tiếp tục?",
      confirmLabel: action.label || "Xác nhận",
      destructive:
        action.menuVariant === "destructive" || action.group === "danger",
    }
  }

  return {
    title: resolved.title,
    description: resolved.description ?? action.hint,
    confirmLabel: resolved.confirmLabel ?? action.label ?? "Xác nhận",
    destructive: resolved.destructive,
  }
}

type PendingRowAction = {
  action: DataTableRowActionItem
  confirm: ResolvedDataTableRowActionConfirm
}

type RowActionConfirmRunnerContextValue = {
  runAction: (action: DataTableRowActionItem) => void
}

const RowActionConfirmRunnerContext =
  createContext<RowActionConfirmRunnerContextValue | null>(null)

export function DataTableRowActionConfirmRunnerProvider({
  autoConfirmDangerousActions = false,
  children,
  confirmDialog,
  runAction,
}: {
  autoConfirmDangerousActions?: boolean
  children: ReactNode
  confirmDialog: ReactNode
  runAction: (action: DataTableRowActionItem) => void
}) {
  void autoConfirmDangerousActions
  return (
    <RowActionConfirmRunnerContext.Provider value={{ runAction }}>
      {children}
      {confirmDialog}
    </RowActionConfirmRunnerContext.Provider>
  )
}

export function useDataTableRowActionRunnerOptional() {
  return useContext(RowActionConfirmRunnerContext)?.runAction ?? null
}

export function useRowActionConfirm(
  defaultAutoConfirmDangerousActions = false
) {
  const [pendingAction, setPendingAction] = useState<PendingRowAction | null>(
    null
  )
  const [running, setRunning] = useState(false)

  const runAction = useCallback(
    (action: DataTableRowActionItem, autoConfirm?: boolean) => {
      if (action.disabled) return
      const auto =
        autoConfirm !== undefined
          ? autoConfirm
          : defaultAutoConfirmDangerousActions
      const confirm = normalizeResolvedRowActionConfirm(action, auto)
      if (confirm) {
        setPendingAction({ action, confirm })
        return
      }
      void action.onClick()
    },
    [defaultAutoConfirmDangerousActions]
  )

  const handleConfirm = useCallback(async () => {
    if (!pendingAction) return
    setRunning(true)
    try {
      await pendingAction.action.onClick()
      setPendingAction(null)
    } catch {
      // Giữ dialog mở; handler thường đã toast lỗi.
    } finally {
      setRunning(false)
    }
  }, [pendingAction])

  const handleCancel = useCallback(() => {
    if (running) return
    setPendingAction(null)
  }, [running])

  return {
    runAction,
    confirmDialog: (
      <RowActionConfirmDialog
        pending={pendingAction}
        running={running}
        onCancel={handleCancel}
        onConfirm={handleConfirm}
      />
    ),
  }
}

type RowActionConfirmDialogProps = {
  pending: PendingRowAction | null
  running: boolean
  onCancel: () => void
  onConfirm: () => void
}

export function RowActionConfirmDialog({
  pending,
  running,
  onCancel,
  onConfirm,
}: RowActionConfirmDialogProps) {
  const isOpen = pending != null
  const confirm = pending?.confirm

  const title = confirm?.title ?? "Xác nhận thao tác"
  const description = confirm?.description ?? "Bạn có chắc muốn tiếp tục?"
  const confirmLabel = confirm?.confirmLabel ?? "Xác nhận"
  const isDestructive = Boolean(confirm?.destructive)

  return (
    <AlertDialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) onCancel()
      }}
    >
      <AlertDialogContent className="sm:max-w-md">
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel onClick={onCancel} disabled={running}>
            Hủy
          </AlertDialogCancel>
          <AlertDialogAction
            type="button"
            onClick={(event) => {
              event.preventDefault()
              void onConfirm()
            }}
            disabled={running}
            className={
              isDestructive
                ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                : undefined
            }
          >
            {running ? "Đang xử lý..." : confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

src/components/data-table/row-actions-me.content:
"use client"

import type { ComponentType, ReactNode, ReactElement } from "react"
import { cn } from "../../lib/utils"
import type {
  DataTableRowActionGroupId,
  DataTableRowActionItem,
} from "./table-row-actions"

export type RowActionsMenuGroupConfig = {
  label: string
  icon?: ComponentType<{ className?: string }>
  header?: ReactNode
  /** Nhãn nhóm kiểu phụ (11px, không uppercase) */
  sublabel?: boolean
}

export const ROW_ACTIONS_GROUP_ORDER: DataTableRowActionGroupId[] = [
  "primary",
  "status",
  "danger",
]

export const ROW_ACTIONS_DEFAULT_GROUPS: Record<
  DataTableRowActionGroupId,
  RowActionsMenuGroupConfig
> = {
  primary: { label: "Thao tác", sublabel: false },
  status: { label: "Trạng thái", sublabel: true },
  danger: { label: "Xóa / quản lý", sublabel: true },
}

export function defaultRowActionMenuIconStyles(
  key: string,
  variant?: "default" | "destructive"
) {
  if (
    variant === "destructive" ||
    key.includes("purge") ||
    key.includes("delete")
  ) {
    return {
      iconBgClassName: "bg-destructive/10",
      iconClassName: "text-destructive",
    }
  }
  if (key === "view") {
    return {
      iconBgClassName: "bg-primary/10",
      iconClassName: "text-primary",
    }
  }
  if (key === "edit") {
    return {
      iconBgClassName: "bg-sky-500/15",
      iconClassName: "text-sky-700 dark:text-sky-400",
    }
  }
  if (key === "toggle-active" || key === "activate") {
    return {
      iconBgClassName: "bg-emerald-500/15",
      iconClassName: "text-emerald-700 dark:text-emerald-400",
    }
  }
  if (key === "toggle-inactive" || key === "deactivate") {
    return {
      iconBgClassName: "bg-amber-500/15",
      iconClassName: "text-amber-700 dark:text-amber-400",
    }
  }
  if (key === "restore") {
    return {
      iconBgClassName: "bg-violet-500/15",
      iconClassName: "text-violet-700 dark:text-violet-400",
    }
  }
  return {
    iconBgClassName: "bg-muted",
    iconClassName: "text-muted-foreground",
  }
}

/** Thao tác hiển thị trong menu ⋯ và chuột phải — ẩn khi `hidden` hoặc `disabled` (vd. không đủ quyền). */
export function getDisplayableRowActions(
  actions: DataTableRowActionItem[]
): DataTableRowActionItem[] {
  return actions.filter((action) => !action.hidden && !action.disabled)
}

export function groupRowActions(
  actions: DataTableRowActionItem[],
  groupsOverride?: Partial<
    Record<DataTableRowActionGroupId, RowActionsMenuGroupConfig>
  >
) {
  const visible = getDisplayableRowActions(actions)
  const groups = { ...ROW_ACTIONS_DEFAULT_GROUPS, ...groupsOverride }
  const byGroup = new Map<DataTableRowActionGroupId, DataTableRowActionItem[]>()

  for (const action of visible) {
    const groupId = action.group ?? "primary"
    const list = byGroup.get(groupId) ?? []
    list.push(action)
    byGroup.set(groupId, list)
  }

  const orderedGroups = ROW_ACTIONS_GROUP_ORDER.filter(
    (id) => (byGroup.get(id)?.length ?? 0) > 0
  )

  return { visible, groups, byGroup, orderedGroups }
}

export function RowActionsMenuGroups({
  orderedGroups,
  groups,
  byGroup,
  renderItem,
  renderSeparator,
  renderGroup,
  renderGroupLabel,
}: {
  orderedGroups: DataTableRowActionGroupId[]
  groups: Record<DataTableRowActionGroupId, RowActionsMenuGroupConfig>
  byGroup: Map<DataTableRowActionGroupId, DataTableRowActionItem[]>
  renderItem: (action: DataTableRowActionItem) => ReactElement
  renderSeparator: () => ReactElement
  renderGroup: (children: ReactNode) => ReactElement
  renderGroupLabel: (
    config: RowActionsMenuGroupConfig,
    GroupIcon?: ComponentType<{ className?: string }>
  ) => ReactElement
}) {
  return (
    <>
      {orderedGroups.map((groupId, index) => {
        const config = groups[groupId]
        const items = byGroup.get(groupId) ?? []
        const GroupIcon = config.icon

        return (
          <div key={groupId}>
            {index > 0 ? renderSeparator() : null}
            {renderGroup(
              <>
                {renderGroupLabel(config, GroupIcon)}
                {config.header ? (
                  <div className="mb-1.5 px-1">{config.header}</div>
                ) : null}
                {items.map((action) => renderItem(action))}
              </>
            )}
          </div>
        )
      })}
    </>
  )
}

export function rowActionsGroupLabelClassName(
  config: RowActionsMenuGroupConfig
): string {
  return config.sublabel
    ? "px-1 py-1 text-[11px] font-medium text-muted-foreground"
    : "flex items-center gap-2 px-1 py-1.5 text-xs font-semibold tracking-wide text-muted-foreground uppercase"
}

export function RowActionMenuItemBody({
  action,
}: {
  action: DataTableRowActionItem
}) {
  const styles = defaultRowActionMenuIconStyles(action.key, action.menuVariant)
  const iconBg = action.iconBgClassName ?? styles.iconBgClassName
  const iconColor = action.iconClassName ?? styles.iconClassName

  return (
    <>
      <span
        className={cn(
          "mt-0.5 flex size-7 shrink-0 items-center justify-center rounded-md",
          iconBg
        )}
      >
        {action.icon ? (
          <span
            className={cn("inline-flex [&>svg]:size-3.5", iconColor)}
            aria-hidden
          >
            {action.icon}
          </span>
        ) : null}
      </span>
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="leading-tight font-medium">{action.label}</span>
        {action.hint ? (
          <span className="text-[11px] leading-snug text-muted-foreground">
            {action.hint}
          </span>
        ) : action.disabled && action.title ? (
          <span className="text-[11px] leading-snug text-muted-foreground">
            {action.title}
          </span>
        ) : null}
      </span>
    </>
  )
}

