import type { RowData } from "@tanstack/react-table"
import type { DataTableUserSearchHandlers } from "./data-table-user-search-filter"

declare module "@tanstack/react-table" {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData extends RowData, TValue> {
    filterVariant?:
      | "text"
      | "select"
      | "multi-select"
      | "tree-select"
      | "tree-multi-select"
      | "number"
      | "number-range"
      | "date"
      | "date-range"
      | "user-search"
    filterPlaceholder?: string
    /** Placeholder ô min khi `filterVariant: "number-range"`. */
    numberRangeMinPlaceholder?: string
    /** Placeholder ô max khi `filterVariant: "number-range"`. */
    numberRangeMaxPlaceholder?: string
    /** Gợi ý người dùng khi `filterVariant: "user-search"`. */
    userSearchHandlers?: DataTableUserSearchHandlers
    /** Nhãn ô lọc ngoài bảng (mặc định: header cột) */
    filterLabel?: string
    selectOptions?: { value: string; label: string }[]
    /** Cấu hình tree-select: value/label/children (parent có children sẽ disabled) */
    treeOptions?: {
      value: string
      label: string
      children?: { value: string; label: string }[]
    }[]
    /** Không hiển thị ô lọc dưới header (vd. cột nút) */
    disableColumnFilter?: boolean
    /** Cột STT / số thứ tự do DataTable tự chèn — không lọc, không nhân đôi. */
    isIndexColumn?: boolean
    /** Cột menu thao tác (id `actions` hoặc meta này) — DataTable gộp meta chuẩn. */
    isActionsColumn?: boolean
    /** Ẩn khỏi bảng UI; bật lại qua "Hiện cột" hoặc vẫn xuất Excel khi được bật. */
    hideInTable?: boolean
    /** Ẩn mặc định trong bảng (vẫn bật qua "Hiện cột"). */
    defaultHidden?: boolean
    /** `false` = không cho ẩn/hiện qua "Hiện cột". */
    enableHiding?: boolean
    /** @deprecated alias — dùng `enableHiding` */
    enableColumnHiding?: boolean
    /** Bỏ qua khi xuất CSV (cột thao tác, icon, …) */
    excludeFromExport?: boolean
    /** Nhãn riêng khi xuất file, nếu khác header đang hiển thị trong bảng. */
    exportHeader?: string
    /** Nội dung riêng khi xuất file, hữu ích cho cell render phức tạp hoặc nested data. */
    exportValue?: (row: TData) => unknown
    /** Độ rộng cột XLSX mong muốn (đơn vị ký tự Excel). */
    exportWidth?: number
    /** Bật xuống dòng trong ô XLSX. */
    exportWrap?: boolean
    /** Class áp dụng lên `th`/`td` (vd. min-w-[120px]). */
    className?: string
    /** Tắt giới hạn tối đa 5 dòng nội dung ô (mặc định: bật cho cột dữ liệu). */
    disableCellLineClamp?: boolean
  }
}

export {}

src/components/data-table/table-row-acti.content:
"use client"

import { MoreHorizontal } from "lucide-react"
import { Button } from "../button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../dropdown-menu"
import { cn } from "../../lib/utils"
import {
  DATA_TABLE_ROW_ACTIONS_TRIGGER_CLASS,
  type DataTableRowActionGroupId,
  type DataTableRowActionItem,
} from "./table-row-actions"
import {
  useDataTableRowActionRunnerOptional,
  useRowActionConfirm,
} from "./row-action-confirm"
import {
  getDisplayableRowActions,
  groupRowActions,
  RowActionMenuItemBody,
  RowActionsMenuGroups,
  rowActionsGroupLabelClassName,
  type RowActionsMenuGroupConfig,
} from "./row-actions-menu-shared"
import { useRegisterDataTableRowActions } from "./data-table-row-actions-registry"

export type { RowActionsMenuGroupConfig }

function DropdownRowActionItem({
  action,
  onRun,
  busy,
}: {
  action: DataTableRowActionItem
  onRun: (action: DataTableRowActionItem) => void
  busy?: boolean
}) {
  return (
    <DropdownMenuItem
      disabled={action.disabled || busy}
      variant={action.menuVariant ?? "default"}
      onClick={(event) => {
        event.preventDefault()
        onRun(action)
      }}
      title={action.title}
      className="items-start gap-2.5 py-2"
    >
      <RowActionMenuItemBody action={action} />
    </DropdownMenuItem>
  )
}

export type DataTableRowActionsMenuProps = {
  actions: DataTableRowActionItem[]
  groups?: Partial<Record<DataTableRowActionGroupId, RowActionsMenuGroupConfig>>
  busy?: boolean
  triggerLabel?: string
  align?: "start" | "center" | "end"
  className?: string
  /**
   * Tự hiện dialog xác nhận với thao tác danger khi action không khai báo `confirm`.
   * Mặc định `true`; đặt `false` khi mỗi action đã có `confirm` riêng hoặc dùng `pageConfirm`.
   */
  autoConfirmDangerousActions?: boolean
}

export function DataTableRowActionsMenu({
  actions,
  groups: groupsOverride,
  busy,
  triggerLabel = "Mở menu thao tác",
  align = "end",
  className,
  autoConfirmDangerousActions = true,
}: DataTableRowActionsMenuProps) {
  const sharedRunAction = useDataTableRowActionRunnerOptional()
  const localConfirm = useRowActionConfirm(autoConfirmDangerousActions)
  const runAction =
    sharedRunAction ??
    ((action: DataTableRowActionItem) => localConfirm.runAction(action))
  const confirmDialog = sharedRunAction ? null : localConfirm.confirmDialog

  const { visible, groups, byGroup, orderedGroups } = groupRowActions(
    actions,
    groupsOverride
  )

  useRegisterDataTableRowActions({
    actions: getDisplayableRowActions(actions),
    groups: groupsOverride,
    busy,
    autoConfirmDangerousActions,
  })

  if (visible.length === 0) {
    return <span className="block h-8 w-full" aria-hidden />
  }

  return (
    <>
      <div className={cn("flex w-full justify-center", className)}>
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                type="button"
                variant="outline"
                size="sm"
                className={DATA_TABLE_ROW_ACTIONS_TRIGGER_CLASS}
                disabled={busy}
                aria-label={triggerLabel}
              />
            }
          >
            <MoreHorizontal className="size-4" aria-hidden />
            <span className="sr-only">{triggerLabel}</span>
          </DropdownMenuTrigger>
          <DropdownMenuContent align={align} className="w-64 p-1.5">
            <RowActionsMenuGroups
              orderedGroups={orderedGroups}
              groups={groups}
              byGroup={byGroup}
              renderSeparator={() => <DropdownMenuSeparator />}
              renderGroup={(children) => (
                <DropdownMenuGroup>{children}</DropdownMenuGroup>
              )}
              renderGroupLabel={(config, GroupIcon) =>
                config.sublabel ? (
                  <DropdownMenuLabel
                    className={rowActionsGroupLabelClassName(config)}
                  >
                    {config.label}
                  </DropdownMenuLabel>
                ) : (
                  <DropdownMenuLabel
                    className={rowActionsGroupLabelClassName(config)}
                  >
                    {GroupIcon ? (
                      <GroupIcon className="size-3.5 shrink-0 text-primary" />
                    ) : null}
                    {config.label}
                  </DropdownMenuLabel>
                )
              }
              renderItem={(action) => (
                <DropdownRowActionItem
                  key={action.key}
                  action={action}
                  onRun={runAction}
                  busy={busy}
                />
              )}
            />
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      {confirmDialog}
    </>
  )
}

"use client"

import type { ComponentProps, ReactNode } from "react"
import { Button } from "../button"
import { cn } from "../../lib/utils"
import type { DataTableRowActionConfirm } from "./row-action-confirm"
import { useRowActionConfirm } from "./row-action-confirm"
import { useRegisterDataTableRowActions } from "./data-table-row-actions-registry"
import { getDisplayableRowActions } from "./row-actions-menu-shared"

/** Id mặc định cột thao tác — DataTable tự gộp meta khi khớp id này. */
export const DATA_TABLE_ACTIONS_COLUMN_ID = "actions"

/** Nút ⋯ cột thao tác — kích thước cố định, variant outline mặc định. */
export const DATA_TABLE_ROW_ACTIONS_TRIGGER_CLASS = "size-8 shrink-0 p-0"

/** Meta chuẩn cho cột hành động (ẩn filter, loại khỏi export, căn giữa menu ⋯). */
export const TABLE_ACTIONS_COLUMN_META = {
  disableColumnFilter: true,
  excludeFromExport: true,
  isActionsColumn: true,
  className:
    "w-[72px] min-w-[72px] max-w-[80px] px-1 text-center align-middle [&>div]:flex [&>div]:w-full [&>div]:justify-center",
} as const

const defaultActionButtonClass = "h-8 gap-1.5"

export type DataTableRowActionGroupId = "primary" | "status" | "danger"

export type DataTableRowActionItem = {
  key: string
  label: string
  onClick: () => void | Promise<void>
  icon?: ReactNode
  variant?: ComponentProps<typeof Button>["variant"]
  size?: ComponentProps<typeof Button>["size"]
  /** Không hiển thị trong menu ⋯ / chuột phải (cùng hiệu lực với `hidden`). */
  disabled?: boolean
  title?: string
  className?: string
  /** Ẩn hoàn toàn — dùng khi không đủ quyền. */
  hidden?: boolean
  /** Nhóm trong menu dropdown (mặc định: primary). */
  group?: DataTableRowActionGroupId
  /** Gợi ý phụ dưới nhãn trong menu. */
  hint?: string
  iconBgClassName?: string
  iconClassName?: string
  menuVariant?: "default" | "destructive"
  /**
   * Dialog xác nhận trước khi gọi `onClick`.
   * `false` = tắt; không khai báo = menu tự bật với thao tác danger/toggle (xem `autoConfirmDangerousActions`).
   */
  confirm?: DataTableRowActionConfirm | false
}

export function DataTableRowActions({
  actions,
  children,
  className,
  autoConfirmDangerousActions = true,
}: {
  actions?: DataTableRowActionItem[]
  children?: ReactNode
  className?: string
  autoConfirmDangerousActions?: boolean
}) {
  const { runAction, confirmDialog } = useRowActionConfirm(
    autoConfirmDangerousActions
  )

  const displayableActions = actions ? getDisplayableRowActions(actions) : null

  useRegisterDataTableRowActions(
    displayableActions
      ? {
          actions: displayableActions,
          autoConfirmDangerousActions,
        }
      : null
  )

  return (
    <>
      <div className={cn("flex flex-wrap items-center gap-2", className)}>
        {displayableActions
          ? displayableActions.map((action) => (
              <DataTableRowActionButton
                key={action.key}
                label={action.label}
                onClick={() => runAction(action)}
                icon={action.icon}
                variant={action.variant}
                size={action.size}
                disabled={action.disabled}
                title={action.title}
                className={action.className}
              />
            ))
          : children}
      </div>
      {confirmDialog}
    </>
  )
}

export function DataTableRowActionButton({
  label,
  onClick,
  icon,
  variant = "outline",
  size = "sm",
  disabled,
  title,
  className,
}: {
  label: string
  onClick: () => void | Promise<void>
  icon?: ReactNode
  variant?: ComponentProps<typeof Button>["variant"]
  size?: ComponentProps<typeof Button>["size"]
  disabled?: boolean
  title?: string
  className?: string
}) {
  return (
    <Button
      type="button"
      variant={variant}
      size={size}
      className={cn(defaultActionButtonClass, className)}
      onClick={onClick}
      disabled={disabled}
      title={title}
    >
      {icon ? (
        <span className="inline-flex shrink-0 [&>svg]:size-3.5" aria-hidden>
          {icon}
        </span>
      ) : null}
      {label}
    </Button>
  )
}

