"use client"

import {
  isValidElement,
  useCallback,
  useMemo,
  useState,
  type ReactNode,
} from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Check, Copy } from "lucide-react"

import { cn } from "../lib/utils"
import { Badge } from "./badge"
import { Label } from "./label"
import { Separator } from "./separator"

/** Thuộc tính `data-copy-text` trên node con — nguồn chuẩn khi hiển thị Badge / JSX. */
export const FIELD_COPY_TEXT_ATTR = "data-copy-text"

export const FIELD_COPY_SUCCESS_LABEL = "Đã sao chép"

/** HR / panel: viền solid rõ, legend cắt viền trên. */
export const FIELDSET_CUSTOM_CLASS =
  "relative box-border min-w-0 m-0 rounded-sm border-2 border-solid border-slate-300 bg-white px-2.5 pb-2.5 pt-6 dark:border-border dark:bg-card hover:border-primary/50"

/** Legend absolute top-left, nằm ngang trên border fieldset (khớp `.legend-custom`). */
export const FIELD_LEGEND_CUSTOM_CLASS =
  "w-fit absolute start-2.5 left-2.5 top-0 z-[1] -translate-y-1/2 border-0 bg-white px-2 text-[15px] font-bold uppercase leading-none tracking-wide text-foreground dark:bg-card"

/**
 * Card chi tiết admin: bo góc, viền solid đậm hơn slate-200.
 * Dùng `overflow-visible` để sticky toolbar / dropdown con không bị cắt.
 * Sidebar scroll: override bằng `overflow-y-auto` trên FieldSet.
 */
export const FIELDSET_SECTION_CLASS =
  "box-border flex min-w-0 flex-col overflow-visible rounded-xl border-2 border-solid border-slate-300 bg-white dark:border-border dark:bg-card hover:border-primary/50"

export const FIELD_LEGEND_SECTION_CLASS =
  "!float-none !-mt-0 block w-fit max-w-full border-0 ml-4 px-2 py-2 font-normal text-foreground"

export const FIELD_PANEL_ITEM_CLASS =
  "min-h-[2.75rem] bg-slate-50 px-2.5 py-2 text-sm leading-normal text-foreground dark:bg-muted/30"

/** Badge đếm góc phải header section (vd. số danh mục con). */
export const FIELD_SECTION_BADGE_CLASS =
  "inline-flex size-6 min-w-6 items-center justify-center rounded-md bg-secondary px-0 text-xs font-bold text-white"

function FieldSectionBadge({
  className,
  children,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="field-section-badge"
      className={cn(FIELD_SECTION_BADGE_CLASS, className)}
      {...props}
    >
      {children}
    </span>
  )
}

const fieldSetVariants = cva("", {
  variants: {
    variant: {
      default:
        "flex flex-col gap-4 has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3",
      /** `.fieldset-custom` — groove 2px, padding 5px 10px. */
      custom: FIELDSET_CUSTOM_CLASS,
      /** Alias `custom` (kèm FieldPanelGrid cho lưới đọc-only). */
      panel: FIELDSET_CUSTOM_CLASS,
      /** Section card trong trang chi tiết (không groove). */
      section: FIELDSET_SECTION_CLASS,
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

const fieldLegendVariants = cva("font-medium", {
  variants: {
    variant: {
      legend: "mb-1.5 text-base",
      label: "mb-1.5 text-sm",
      /** `.legend-custom` */
      custom: FIELD_LEGEND_CUSTOM_CLASS,
      panel: FIELD_LEGEND_CUSTOM_CLASS,
      /** Legend hàng ngang: icon + tiêu đề + badge. */
      section: FIELD_LEGEND_SECTION_CLASS,
    },
  },
  defaultVariants: {
    variant: "legend",
  },
})

const fieldSetContentVariants = cva("", {
  variants: {
    variant: {
      default: "",
      custom: "",
      panel: "",
      section: "px-6 pb-6",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

/** Reset viền mặc định UA (groove/inset) để Tailwind kiểm soát hoàn toàn. */
const FIELDSET_BASE_CLASS = "min-w-0 border-solid [border-image:initial]"

function FieldSet({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"fieldset"> & VariantProps<typeof fieldSetVariants>) {
  return (
    <fieldset
      data-slot="field-set"
      data-variant={variant}
      className={cn(
        FIELDSET_BASE_CLASS,
        fieldSetVariants({ variant }),
        className
      )}
      {...props}
    />
  )
}

function FieldLegend({
  className,
  variant = "legend",
  ...props
}: React.ComponentProps<"legend"> & VariantProps<typeof fieldLegendVariants>) {
  return (
    <legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(fieldLegendVariants({ variant }), className)}
      {...props}
    />
  )
}

/** Mô tả phụ dưới tiêu đề (đặt trong `FieldSectionHeader` hoặc `FieldLegend`). */
function FieldLegendDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="field-legend-description"
      className={cn(
        "mt-0.5 text-sm font-normal text-muted-foreground",
        className
      )}
      {...props}
    />
  )
}

type FieldSectionHeaderProps = {
  icon?: React.ComponentType<{ className?: string }>
  title: React.ReactNode
  description?: React.ReactNode
  badge?: React.ReactNode
  className?: string
}

/** Legend section card: icon + tiêu đề + mô tả (+ badge) — hiển thị trong `<legend>`. */
function FieldSectionLegend({
  icon: Icon,
  title,
  description,
  badge,
  className,
  ...props
}: FieldSectionHeaderProps &
  Omit<React.ComponentProps<typeof FieldLegend>, "title" | "variant">) {
  return (
    <FieldLegend
      variant="section"
      data-slot="field-section-legend"
      className={className}
      {...props}
    >
      <span className="flex w-full items-start gap-2.5">
        {Icon ? (
          <Icon className="mt-0.5 size-5 shrink-0 text-primary" aria-hidden />
        ) : null}
        <span className="min-w-0 flex-1">
          <span className="flex w-full items-center gap-2">
            <span className="text-[15px] leading-snug font-bold text-foreground">
              {title}
            </span>
            {badge ? <span className="ml-auto shrink-0">{badge}</span> : null}
          </span>
          {description != null && description !== "" ? (
            typeof description === "string" ? (
              <FieldLegendDescription>{description}</FieldLegendDescription>
            ) : (
              description
            )
          ) : null}
        </span>
      </span>
    </FieldLegend>
  )
}

/** @deprecated Dùng `FieldSectionLegend` (cùng API, render `<legend>`). */
function FieldSectionHeader(props: FieldSectionHeaderProps) {
  return <FieldSectionLegend {...props} />
}

/** Bọc nội dung sau legend — `clear-both` tránh chồng khi legend float UA. */
function FieldSetContent({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldSetContentVariants>) {
  return (
    <div
      data-slot="field-set-content"
      className={cn(fieldSetContentVariants({ variant }), className)}
      {...props}
    />
  )
}

const fieldPanelGridRowVariants = cva(
  "grid w-full divide-x divide-y divide-slate-300 overflow-hidden rounded-sm border border-slate-300 dark:divide-border dark:border-border",
  {
    variants: {
      columns: {
        1: "grid-cols-1",
        2: "grid-cols-1 sm:grid-cols-2",
        3: "grid-cols-1 sm:grid-cols-3",
        4: "grid-cols-1 sm:grid-cols-2 lg:grid-cols-4",
      },
    },
    defaultVariants: {
      columns: 3,
    },
  }
)

/** Lưới ô có viền chung (table-grid) — Tailwind thuần. */
function FieldPanelGrid({
  className,
  columns = 3,
  children,
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof fieldPanelGridRowVariants>) {
  return (
    <div
      data-slot="field-panel-grid"
      className={cn(fieldPanelGridRowVariants({ columns }), className)}
      {...props}
    >
      {children}
    </div>
  )
}

export type FieldPanelItemProps = React.ComponentProps<"div"> & {
  label: React.ReactNode
  /** Tự thêm " :" sau label nếu false. Mặc định true. */
  showColon?: boolean
  value?: React.ReactNode
  children?: React.ReactNode
}

/** Ô label đậm + giá trị (cùng dòng) trong lưới panel. */
function FieldPanelItem({
  label,
  showColon = true,
  value,
  children,
  className,
  ...props
}: FieldPanelItemProps) {
  const content = children ?? value

  return (
    <div
      data-slot="field-panel-item"
      className={cn(FIELD_PANEL_ITEM_CLASS, className)}
      {...props}
    >
      <span className="font-bold">{label}</span>
      {showColon ? <span className="font-bold"> :</span> : null}
      {content != null && content !== "" ? (
        <span className="font-normal"> {content}</span>
      ) : null}
    </div>
  )
}

/** Khung viền chỉ bọc giá trị — label đặt bên ngoài (không viền). */
export const FIELD_SECTION_VALUE_CLASS =
  "rounded-md border border-solid border-slate-300 bg-slate-50 px-3 py-2.5 text-sm text-foreground dark:border-border dark:bg-muted/30"

function isCopyPlaceholder(text: string): boolean {
  return text === "" || text === "—" || text === "-"
}

function readCopyTextFromProps(props: Record<string, unknown>): string | null {
  const attr = props[FIELD_COPY_TEXT_ATTR]
  if (typeof attr === "string") {
    const text = attr.trim()
    return isCopyPlaceholder(text) ? null : text
  }
  return null
}

function resolveFieldCopyText(
  copyText: string | undefined,
  children: ReactNode,
): string | null {
  if (copyText != null && copyText !== "") {
    const text = copyText.trim()
    return isCopyPlaceholder(text) ? null : text
  }
  if (typeof children === "string" || typeof children === "number") {
    const text = String(children).trim()
    return isCopyPlaceholder(text) ? null : text
  }
  if (isValidElement(children)) {
    const fromAttr = readCopyTextFromProps(
      children.props as Record<string, unknown>,
    )
    if (fromAttr) return fromAttr
    const nested = resolveFieldCopyText(
      undefined,
      (children.props as { children?: ReactNode }).children,
    )
    if (nested) return nested
  }
  if (Array.isArray(children)) {
    for (const child of children) {
      const nested = resolveFieldCopyText(undefined, child)
      if (nested) return nested
    }
  }
  return null
}

export type FieldCopyButtonProps = {
  text: string
  successMessage?: string
  className?: string
}

/** Badge trạng thái copy — idle (muted) / thành công (success). */
function FieldCopyButton({
  text,
  successMessage = FIELD_COPY_SUCCESS_LABEL,
  className,
}: FieldCopyButtonProps) {
  const [copied, setCopied] = useState(false)

  const onCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 2000)
    } catch {
      setCopied(false)
    }
  }, [text])

  return (
    <Badge
      render={<button type="button" />}
      data-slot="field-copy-button"
      data-copied={copied || undefined}
      variant={copied ? "success" : "muted"}
      size="xs"
      onClick={() => void onCopy()}
      aria-label={copied ? successMessage : "Sao chép nội dung"}
      className={cn(
        "shrink-0 cursor-pointer transition-opacity hover:opacity-90",
        className,
      )}
    >
      {copied ? (
        <>
          <Check className="size-3 shrink-0" aria-hidden />
          <span aria-live="polite">{successMessage}</span>
        </>
      ) : (
        <>
          <Copy className="size-3 shrink-0" aria-hidden />
          <span className="hidden sm:inline">Sao chép</span>
        </>
      )}
    </Badge>
  )
}

export type FieldSectionValueProps = React.ComponentProps<"div"> & {
  /** Bật nút copy; mặc định bật khi có `copyText` hoặc children là chuỗi/số. */
  copyable?: boolean
  /** Nội dung ghi clipboard — ưu tiên hơn text từ children. */
  copyText?: string
  /** Thông báo inline sau khi copy thành công. */
  copySuccessMessage?: string
}

function FieldSectionValue({
  className,
  children,
  copyable,
  copyText,
  copySuccessMessage,
  ...props
}: FieldSectionValueProps) {
  const resolvedCopyText = resolveFieldCopyText(copyText, children)
  const showCopy =
    (copyable ?? resolvedCopyText != null) && resolvedCopyText != null

  return (
    <div
      data-slot="field-section-value"
      data-copyable={showCopy || undefined}
      className={cn(
        FIELD_SECTION_VALUE_CLASS,
        showCopy && "flex items-start justify-between gap-2",
        className,
      )}
      {...props}
    >
      <div className="min-w-0 flex-1">{children}</div>
      {showCopy ? (
        <FieldCopyButton
          text={resolvedCopyText}
          successMessage={copySuccessMessage}
        />
      ) : null}
    </div>
  )
}

type FieldSectionFieldProps = {
  label: React.ReactNode
  icon?: React.ComponentType<{ className?: string }>
  className?: string
  valueClassName?: string
  children: React.ReactNode
  copyable?: boolean
  copyText?: string
  copySuccessMessage?: string
}

/** Một field section: label (không viền) + nội dung trong khung viền. */
function FieldSectionField({
  label,
  icon,
  className,
  valueClassName,
  children,
  copyable,
  copyText,
  copySuccessMessage,
}: FieldSectionFieldProps) {
  return (
    <div
      data-slot="field-section-field"
      className={cn("flex flex-col gap-1.5", className)}
    >
      <FieldSectionLabel icon={icon}>{label}</FieldSectionLabel>
      <FieldSectionValue
        className={valueClassName}
        copyable={copyable}
        copyText={copyText}
        copySuccessMessage={copySuccessMessage}
      >
        {children}
      </FieldSectionValue>
    </div>
  )
}

/** Nhãn uppercase trong section card (vd. SLUG / ĐƯỜNG DẪN). */
function FieldSectionLabel({
  className,
  icon: Icon,
  children,
  ...props
}: React.ComponentProps<"p"> & {
  icon?: React.ComponentType<{ className?: string }>
}) {
  return (
    <p
      data-slot="field-section-label"
      className={cn(
        "flex items-center gap-1.5 text-xs font-semibold tracking-wide text-muted-foreground uppercase",
        className
      )}
      {...props}
    >
      {Icon ? <Icon className="size-3 shrink-0" aria-hidden /> : null}
      {children}
    </p>
  )
}

/** Gạch ngang giữa các khối trong section card. */
function FieldSectionDivider({
  className,
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="field-section-divider"
      className={cn("bg-slate-100 dark:bg-border", className)}
      {...props}
    />
  )
}

function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-group"
      className={cn(
        "group/field-group @container/field-group flex w-full flex-col gap-5 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4",
        className
      )}
      {...props}
    />
  )
}

const fieldVariants = cva(
  "group/field flex w-full gap-2 data-[invalid=true]:text-destructive",
  {
    variants: {
      orientation: {
        vertical: "flex-col *:w-full [&>.sr-only]:w-auto",
        horizontal:
          "flex-row items-center has-[>[data-slot=field-content]]:items-start *:data-[slot=field-label]:flex-auto has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
        responsive:
          "flex-col *:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:*:w-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:*:data-[slot=field-label]:flex-auto [&>.sr-only]:w-auto @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
      },
    },
    defaultVariants: {
      orientation: "vertical",
    },
  }
)

function Field({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  )
}

function FieldContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-content"
      className={cn(
        "group/field-content flex flex-1 flex-col gap-0.5 leading-snug",
        className
      )}
      {...props}
    />
  )
}

function FieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-2 leading-snug group-data-[disabled=true]/field:opacity-50 has-data-checked:border-primary/30 has-data-checked:bg-primary/5 has-[>[data-slot=field]]:rounded-lg has-[>[data-slot=field]]:border *:data-[slot=field]:p-2.5 dark:has-data-checked:border-primary/20 dark:has-data-checked:bg-primary/10",
        "has-[>[data-slot=field]]:w-full has-[>[data-slot=field]]:flex-col",
        className
      )}
      {...props}
    />
  )
}

function FieldTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-label"
      className={cn(
        "flex w-fit items-center gap-2 text-sm font-medium group-data-[disabled=true]/field:opacity-50",
        className
      )}
      {...props}
    />
  )
}

function FieldDescription({ className, ...props }: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="field-description"
      className={cn(
        "text-left text-sm leading-normal font-normal text-muted-foreground group-has-data-horizontal/field:text-balance [[data-variant=legend]+&]:-mt-1.5",
        "last:mt-0 nth-last-2:-mt-1",
        "[&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        className
      )}
      {...props}
    />
  )
}

function FieldSeparator({
  children,
  className,
  ...props
}: React.ComponentProps<"div"> & {
  children?: React.ReactNode
}) {
  return (
    <div
      data-slot="field-separator"
      data-content={!!children}
      className={cn(
        "relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2",
        className
      )}
      {...props}
    >
      <Separator className="absolute inset-0 top-1/2" />
      {children && (
        <span
          className="relative mx-auto block w-fit bg-background px-2 text-muted-foreground"
          data-slot="field-separator-content"
        >
          {children}
        </span>
      )}
    </div>
  )
}

function FieldError({
  className,
  children,
  errors,
  ...props
}: React.ComponentProps<"div"> & {
  errors?: Array<{ message?: string } | undefined>
}) {
  const content = useMemo(() => {
    if (children) {
      return children
    }

    if (!errors?.length) {
      return null
    }

    const uniqueErrors = [
      ...new Map(errors.map((error) => [error?.message, error])).values(),
    ]

    if (uniqueErrors?.length == 1) {
      return uniqueErrors[0]?.message
    }

    return (
      <ul className="ml-4 flex list-disc flex-col gap-1">
        {uniqueErrors.map(
          (error, index) =>
            error?.message && <li key={index}>{error.message}</li>
        )}
      </ul>
    )
  }, [children, errors])

  if (!content) {
    return null
  }

  return (
    <div
      role="alert"
      data-slot="field-error"
      className={cn("text-sm font-normal text-destructive", className)}
      {...props}
    >
      {content}
    </div>
  )
}

export {
  Field,
  FieldCopyButton,
  FieldLabel,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLegend,
  FieldLegendDescription,
  FieldSectionBadge,
  FieldSectionDivider,
  FieldSectionField,
  FieldSectionHeader,
  FieldSectionLegend,
  FieldSectionLabel,
  FieldSectionValue,
  FieldPanelGrid,
  FieldPanelItem,
  FieldSeparator,
  FieldSet,
  FieldSetContent,
  FieldContent,
  FieldTitle,
  fieldLegendVariants,
  fieldPanelGridRowVariants,
  fieldSetContentVariants,
  fieldSetVariants,
}

src/components/flex.tsx.content:
"use client"

import { cn } from "../lib/utils"

type FlexDirection = "row" | "col"
type FlexAlign = "start" | "center" | "end" | "between" | "around" | "evenly"
type FlexJustify = "start" | "center" | "end" | "between" | "around" | "evenly"

const directionMap: Record<FlexDirection, string> = {
  row: "flex-row",
  col: "flex-col",
}

const alignMap: Record<FlexAlign, string> = {
  start: "items-start",
  center: "items-center",
  end: "items-end",
  between: "items-stretch",
  around: "items-stretch",
  evenly: "items-stretch",
}

const justifyMap: Record<FlexJustify, string> = {
  start: "justify-start",
  center: "justify-center",
  end: "justify-end",
  between: "justify-between",
  around: "justify-around",
  evenly: "justify-evenly",
}

export interface FlexProps extends React.HTMLAttributes<HTMLElement> {
  as?: React.ElementType
  direction?: FlexDirection
  align?: FlexAlign
  justify?: FlexJustify
  wrap?: boolean
  fullWidth?: boolean
  shrink?: boolean
  gap?: number
}

export function Flex({
  as: Tag = "div",
  direction = "row",
  align,
  justify,
  wrap = false,
  fullWidth = false,
  shrink = true,
  gap,
  className,
  children,
  ...props
}: FlexProps) {
  const gapStyle = gap != null ? { gap: `${gap * 0.25}rem` } : undefined

  return (
    <Tag
      className={cn(
        "flex",
        directionMap[direction],
        align ? alignMap[align] : undefined,
        justify ? justifyMap[justify] : undefined,
        wrap ? "flex-wrap" : undefined,
        fullWidth ? "w-full" : undefined,
        shrink ? "shrink" : "shrink-0",
        className
      )}
      style={gapStyle}
      {...props}
    >
      {children}
    </Tag>
  )
}

src/components/graphify/force-graph-3d.t.content:
"use client"

import { useMemo, useCallback, useRef, useState, useEffect } from "react"
import dynamic from "next/dynamic"
import type { GraphData, GraphNode } from "../../lib/graphify-context"
import { nodeColorByCommunity } from "../../lib/graphify-context"
import type * as THREE from "three"

const ForceGraph3D = dynamic(() => import("react-force-graph-3d"), {
  ssr: false,
})

interface Props {
  graph: GraphData
  selectedNode: GraphNode | null
  onNodeClick: (node: GraphNode) => void
  onBackgroundClick?: () => void
  hiddenNodes?: Set<string>
  linkedNodes?: Map<string, number>
}

type ThreeModule = Awaited<typeof import("three")>
let threeModule: ThreeModule | null = null
let threeLoading: Promise<ThreeModule> | null = null

async function getThree(): Promise<ThreeModule> {
  if (threeModule) return threeModule
  if (!threeLoading) {
    threeLoading = import("three").then((m) => {
      threeModule = m
      return m
    })
  }
  return threeLoading
}

function useThree(): ThreeModule | null {
  const [three, setThree] = useState<ThreeModule | null>(null)
  useEffect(() => {
    getThree().then(setThree)
  }, [])
  return three
}

async function createLabelSprite(
  text: string,
  color: string,
  fontSize = 28,
  opacity = 1
) {
  const THREE = await getThree()
  const canvas = document.createElement("canvas")
  const ctx = canvas.getContext("2d")!
  ctx.font = `bold ${fontSize}px ui-sans-serif, system-ui, sans-serif`
  const metrics = ctx.measureText(text)
  const w = Math.max(128, Math.ceil(metrics.width) + 24)
  const h = fontSize + 16
  canvas.width = w
  canvas.height = h

  ctx.fillStyle = `rgba(9,9,11,${0.6 * opacity})`
  ctx.fillRect(0, 0, w, h)

  ctx.fillStyle = color
  ctx.font = `bold ${fontSize}px ui-sans-serif, system-ui, sans-serif`
  ctx.textAlign = "center"
  ctx.textBaseline = "middle"
  ctx.fillText(text, w / 2, h / 2)

  const texture = new THREE.CanvasTexture(canvas)
  const material = new THREE.SpriteMaterial({
    map: texture,
    transparent: true,
    depthTest: false,
    opacity,
  })
  const sprite = new THREE.Sprite(material)
  sprite.scale.set(w / 16, h / 16, 1)
  sprite.position.y = 2.2
  return sprite
}

export function GraphifyForceGraph3D({
  graph,
  selectedNode,
  onNodeClick,
  onBackgroundClick,
  hiddenNodes,
  linkedNodes,
}: Props) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const fgRef = useRef<any>(null)
  const THREE = useThree()
  const threeReady = THREE !== null

  const degreeMap = useMemo(() => {
    const d = new Map<string, number>()
    for (const l of graph.links) {
      d.set(l.source, (d.get(l.source) ?? 0) + 1)
      d.set(l.target, (d.get(l.target) ?? 0) + 1)
    }
    return d
  }, [graph.links])

  const fgData = useMemo(() => {
    const nodes = graph.nodes
      .filter((n) => !hiddenNodes?.has(n.id))
      .map((n) => {
        const isSelected = n.id === selectedNode?.id
        const isLinked = linkedNodes?.has(n.id)
        const degree = degreeMap.get(n.id) ?? 0
        return {
          ...n,
          color: nodeColorByCommunity(n.community),
          val: isSelected
            ? 14
            : isLinked
              ? 10
              : Math.max(3, Math.min(8, 2 + degree * 0.5)),
          __degree: degree,
          __isSelected: isSelected,
          __isLinked: isLinked,
        }
      })

    const nodeIds = new Set(nodes.map((n) => n.id))
    const relatedIds = selectedNode
      ? new Set([selectedNode.id, ...(linkedNodes?.keys() ?? [])])
      : null
    const links = graph.links
      .filter((l) => nodeIds.has(l.source) && nodeIds.has(l.target))
      .map((l) => {
        const src =
          typeof l.source === "string"
            ? l.source
            : ((l.source as { id?: string })?.id ?? "")
        const tgt =
          typeof l.target === "string"
            ? l.target
            : ((l.target as { id?: string })?.id ?? "")
        const isConnectedToSelected = selectedNode
          ? src === selectedNode.id || tgt === selectedNode.id
          : false
        return {
          ...l,
          __isRelated: relatedIds
            ? relatedIds.has(src) && relatedIds.has(tgt)
            : false,
          __isDirectConnection: isConnectedToSelected,
        }
      })

    return { nodes, links }
  }, [graph, hiddenNodes, selectedNode, linkedNodes, degreeMap])

  const handleNodeClick = useCallback(
    (node: unknown) => {
      const n = node as GraphNode & { x?: number; y?: number; z?: number }
      onNodeClick(n)
      if (
        fgRef.current &&
        typeof fgRef.current.cameraPosition === "function" &&
        n.x != null
      ) {
        const dist = 140
        const ratio = 1 + dist / Math.hypot(n.x, n.y || 0, n.z || 0)
        fgRef.current.cameraPosition(
          { x: n.x * ratio, y: (n.y || 0) * ratio, z: (n.z || 0) * ratio },
          { x: n.x, y: n.y || 0, z: n.z || 0 },
          1200
        )
      }
    },
    [onNodeClick]
  )

  const linkThreeObject = useCallback(
    (l: unknown) => {
      const three = THREE!
      const link = l as {
        source: { x: number; y: number; z: number }
        target: { x: number; y: number; z: number }
        __isRelated?: boolean
        __isDirectConnection?: boolean
      }
      const start = new three.Vector3(
        link.source.x,
        link.source.y,
        link.source.z
      )
      const end = new three.Vector3(link.target.x, link.target.y, link.target.z)
      const direction = new three.Vector3().subVectors(end, start)
      const length = direction.length()
      const isDirect = link.__isDirectConnection ?? false
      const isRelated = link.__isRelated ?? false
      const hasSelection = selectedNode !== null
      const radius = isDirect
        ? 0.6
        : isRelated
          ? 0.4
          : hasSelection
            ? 0.08
            : 0.2

      let color: number
      let opacity: number
      if (isDirect) {
        color = 0xfbbf24
        opacity = 1.0
      } else if (isRelated) {
        color = 0xf59e0b
        opacity = 0.8
      } else if (hasSelection) {
        color = 0x52525b
        opacity = 0.25
      } else {
        color = 0xd4d4d8
        opacity = 0.8
      }
      const material = new three.MeshBasicMaterial({
        color,
        transparent: true,
        opacity,
      })

      const group = new three.Group()

      const cylinderGeo = new three.CylinderGeometry(
        radius,
        radius,
        length,
        8,
        1
      )
      cylinderGeo.rotateX(-Math.PI / 2)
      group.add(new three.Mesh(cylinderGeo, material))

      const arrowHeight = radius * 6
      const arrowRadius = radius * 3
      const coneGeo = new three.ConeGeometry(arrowRadius, arrowHeight, 8)
      coneGeo.rotateX(-Math.PI / 2)
      coneGeo.translate(0, 0, length / 2 - arrowHeight / 2)
      group.add(new three.Mesh(coneGeo, material))

      if (isDirect || isRelated || !hasSelection) {
        const glowRadius = radius * 2.5
        const glowGeo = new three.CylinderGeometry(
          glowRadius,
          glowRadius,
          length,
          8,
          1
        )
        glowGeo.rotateX(-Math.PI / 2)
        const glowMat = new three.MeshBasicMaterial({
          color,
          transparent: true,
          opacity: isDirect
            ? 0.04
            : isRelated
              ? 0.04
              : hasSelection
                ? 0.0
                : 0.1,
          depthWrite: false,
        })
        group.add(new three.Mesh(glowGeo, glowMat))
      }

      return group
    },
    [THREE, selectedNode]
  )

  const linkPositionUpdate = useCallback(
    (
      obj: unknown,
      {
        start,
        end,
      }: {
        start: { x: number; y: number; z: number }
        end: { x: number; y: number; z: number }
      }
    ) => {
      const group = obj as THREE.Group
      group.position.set(
        (start.x + end.x) / 2,
        (start.y + end.y) / 2,
        (start.z + end.z) / 2
      )
      group.lookAt(end.x, end.y, end.z)
    },
    []
  )

  const nodeThreeObject = useCallback(
    (n: unknown) => {
      const three = THREE!
      const node = n as GraphNode & {
        __degree: number
        __isSelected: boolean
        __isLinked: boolean
        color: string
        val: number
      }
      const group = new three.Group()

      const geo = new three.SphereGeometry(1, 16, 16)
      const isDimmed = selectedNode && !node.__isSelected && !node.__isLinked
      const mat = new three.MeshLambertMaterial({
        color: node.__isSelected
          ? 0xffffff
          : node.__isLinked
            ? 0xfbbf24
            : node.color,
        transparent: true,
        opacity: node.__isSelected
          ? 1.0
          : node.__isLinked
            ? 0.95
            : isDimmed
              ? 0.2
              : 0.92,
      })
      const mesh = new three.Mesh(geo, mat)
      mesh.scale.setScalar(node.val / 3)
      group.add(mesh)

      if (node.__isSelected || node.__isLinked) {
        const haloGeo = new three.SphereGeometry(1, 16, 16)
        const haloMat = new three.MeshBasicMaterial({
          color: node.__isSelected ? 0xffffff : 0xfbbf24,
          transparent: true,
          opacity: node.__isSelected ? 0.18 : 0.12,
          depthWrite: false,
        })
        const halo = new three.Mesh(haloGeo, haloMat)
        halo.scale.setScalar((node.val / 3) * 1.5)
        group.add(halo)
      }

      const labelColor = node.__isSelected
        ? "#ffffff"
        : node.__isLinked
          ? "#fbbf24"
          : "#a1a1aa"
      const fontSize = node.__isSelected ? 36 : node.__isLinked ? 30 : 20
      const opacity = node.__isSelected
        ? 1
        : node.__isLinked
          ? 0.95
          : selectedNode
            ? 0.3
            : 0.7
      createLabelSprite(node.label, labelColor, fontSize, opacity).then(
        (sprite) => {
          group.add(sprite)
        }
      )

      if (node.__isSelected) {
        const ringGeo = new three.RingGeometry(1.4, 1.65, 32)
        const ringMat = new three.MeshBasicMaterial({
          color: 0xffffff,
          transparent: true,
          opacity: 0.35,
          side: three.DoubleSide,
        })
        const ring = new three.Mesh(ringGeo, ringMat)
        ring.scale.setScalar(node.val / 3)
        ring.lookAt(new three.Vector3(0, 0, 1))
        group.add(ring)
      }

      if (node.__isLinked) {
        const ringGeo = new three.RingGeometry(1.35, 1.55, 32)
        const ringMat = new three.MeshBasicMaterial({
          color: 0xfbbf24,
          transparent: true,
          opacity: 0.25,
          side: three.DoubleSide,
        })
        const ring = new three.Mesh(ringGeo, ringMat)
        ring.scale.setScalar(node.val / 3)
        ring.lookAt(new three.Vector3(0, 0, 1))
        group.add(ring)
      }

      return group
    },
    [THREE, selectedNode]
  )

  if (!threeReady) {
    return (
      <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-zinc-950">
        <div className="text-sm text-zinc-400">Loading 3D graph...</div>
      </div>
    )
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-zinc-950">
      <ForceGraph3D
        ref={fgRef}
        graphData={fgData}
        backgroundColor="#09090b"
        nodeLabel={(n: unknown) => (n as GraphNode).label}
        onNodeClick={handleNodeClick}
        onBackgroundClick={onBackgroundClick}
        linkThreeObject={linkThreeObject}
        linkPositionUpdate={linkPositionUpdate}
        linkDirectionalParticles={(l: unknown) => {
          const link = l as {
            __isRelated?: boolean
            __isDirectConnection?: boolean
          }
          if (link.__isDirectConnection) return 8
          if (link.__isRelated) return 4
          return selectedNode ? 0 : 3
        }}
        linkDirectionalParticleWidth={3}
        linkDirectionalParticleSpeed={0.005}
        linkDirectionalParticleColor={(l: unknown) => {
          const link = l as {
            __isRelated?: boolean
            __isDirectConnection?: boolean
          }
          if (link.__isDirectConnection) return "rgba(251,191,36,1)"
          if (link.__isRelated) return "rgba(245,158,11,0.9)"
          return selectedNode
            ? "rgba(255,255,255,0.05)"
            : "rgba(255,255,255,0.8)"
        }}
        warmupTicks={80}
        cooldownTicks={80}
        nodeThreeObject={nodeThreeObject}
      />
    </div>
  )
}

src/components/graphify/graphify-page.ts.content:
"use client"

import { useGraphify } from "../../hooks/use-graphify"
import { useEffect, useState, useCallback, useMemo } from "react"
import { Button } from "../button"
import { Input } from "../input"
import { Badge } from "../badge"
import { Skeleton } from "../skeleton"
import { ScrollArea } from "../scroll-area"
import {
  Collapsible,
  CollapsibleTrigger,
  CollapsibleContent,
} from "../collapsible"
import { nodeColorByCommunity } from "../../lib/graphify-context"
import type { GraphNode } from "../../lib/graphify-context"
import { Heading, Text } from "../typography"
import { GraphifyForceGraph3D } from "./force-graph-3d"
import { cn } from "../../lib/utils"
import {
  Network,
  RefreshCw,
  AlertTriangle,
  Search,
  GripHorizontal,
  MousePointerClick,
  Maximize2,
  X,
  ChevronRight,
  Folder,
} from "lucide-react"

const TYPE_ICON: Record<string, React.ReactNode> = {
  page: <span className="text-blue-400">●</span>,
  layout: <span className="text-orange-400">■</span>,
  component: <span className="text-violet-400">◆</span>,
  hook: <span className="text-emerald-400">⚡</span>,
  util: <span className="text-cyan-400">◇</span>,
  styles: <span className="text-pink-400">▪</span>,
  code: <span className="text-zinc-400">○</span>,
  tsx: <span className="text-violet-300">⚛</span>,
  ts: <span className="text-blue-300">⊃</span>,
  api: <span className="text-amber-400">⚡</span>,
}

type TreeFolder = {
  name: string
  path: string
  children: Record<string, TreeFolder>
  files: GraphNode[]
}

function FolderNode({
  folder,
  selectedNode,
  linkedNodes,
  onNodeClick,
  defaultOpen = false,
}: {
  folder: TreeFolder
  selectedNode: GraphNode | null
  linkedNodes: Map<string, number>
  onNodeClick: (id: string) => void
  defaultOpen?: boolean
}) {
  const hasChildren = Object.keys(folder.children).length > 0
  const hasFiles = folder.files.length > 0

  if (!hasChildren && !hasFiles) return null

  const color = nodeColorByCommunity(
    folder.path === "" || folder.path === "Project" ? "root" : folder.path
  )

  return (
    <Collapsible defaultOpen={defaultOpen} className="w-full">
      <CollapsibleTrigger className="group flex w-full cursor-pointer items-center gap-1.5 rounded-md px-2 py-1.5 text-left transition-colors hover:bg-muted/50">
        <ChevronRight className="size-3.5 shrink-0 text-muted-foreground transition-transform group-data-[panel-open]:rotate-90" />
        <Folder
          className="size-4 shrink-0 transition-colors"
          style={{ color: color, fill: color, fillOpacity: 0.2 }}
        />
        <span className="truncate text-body-sm font-medium text-foreground">
          {folder.name || "Project"}
        </span>
        {(hasFiles || hasChildren) && (
          <Badge
            variant="outline"
            className="ml-auto flex h-4 min-w-4 shrink-0 items-center justify-center border-border/50 bg-muted/60 px-1 text-[10px] leading-none text-muted-foreground"
          >
            {folder.files.length + Object.keys(folder.children).length}
          </Badge>
        )}
      </CollapsibleTrigger>

      <CollapsibleContent>
        <div className="mt-0.5 ml-2 space-y-0.5 border-l border-border/40 pl-3">
          {Object.values(folder.children)
            .sort((a, b) => a.name.localeCompare(b.name))
            .map((child) => (
              <FolderNode
                key={child.path}
                folder={child}
                selectedNode={selectedNode}
                linkedNodes={linkedNodes}
                onNodeClick={onNodeClick}
              />
            ))}

          {folder.files.map((n) => {
            const isSelected = selectedNode?.id === n.id
            const isLinked = linkedNodes.has(n.id)
            return (
              <div
                key={n.id}
                onClick={() => onNodeClick(n.id)}
                className={`mt-0.5 flex cursor-pointer items-center gap-2 rounded-md px-2 py-1 text-body-sm transition-colors ${
                  isSelected
                    ? "bg-primary/20 font-semibold text-foreground"
                    : isLinked
                      ? "bg-warning/15 text-warning"
                      : "text-muted-foreground hover:bg-muted"
                }`}
              >
                <span className="flex w-4 shrink-0 items-center justify-center">
                  {TYPE_ICON[n.file_type] ?? TYPE_ICON.code}
                </span>
                <span className="min-w-0 flex-1 truncate">{n.label}</span>
                {isSelected && (
                  <span className="text-caption font-bold text-primary">★</span>
                )}
                {isLinked && !isSelected && (
                  <span className="text-caption text-amber-500">→</span>
                )}
              </div>
            )
          })}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

export interface GraphifyPageProps {
  _homeHref?: string
  _homeLabel?: string
  apiPath?: string
  /**
   * When `true`, the graph view fills the parent container's height
   * (used in admin shell where Page/PageContent wrappers are skipped).
   * When `false` (default), it uses `min-h-screen` for standalone pages.
   */
  sticky?: boolean
  /** Class overrides for fine-tuning layout per app context. */
  classes?: {
    /** Root container (default: `flex h-full w-full flex-col` or `min-h-screen flex w-full flex-col`) */
    root?: string
    /** Header bar */
    header?: string
    /** Left sidebar container */
    sidebar?: string
    /** ScrollArea inside sidebar */
    scrollArea?: string
    /** Graph area container */
    graphArea?: string
    /** Hints overlay at bottom-right */
    hints?: string
  }
}

export function GraphifyPage({
  _homeHref = "/",
  _homeLabel = "Home",
  apiPath = "/api/graphify",
  classes = {},
}: GraphifyPageProps) {
  const {
    data,
    loading,
    error,
    selectedNode,
    setSelectedNode,
    linkedNodes,
    communities,
    refresh,
  } = useGraphify(apiPath, 2)
  const [search, setSearch] = useState("")

  useEffect(() => {
    refresh()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const filteredCommunities = useMemo(() => {
    if (!data) return communities
    let result = communities
    if (selectedNode) {
      const allowed = new Set([selectedNode.id, ...linkedNodes.keys()])
      result = communities.map(([id, nodes]) => [
        id,
        nodes.filter((n) => allowed.has(n.id)),
      ]) as typeof communities
    }
    if (!search.trim()) return result
    const q = search.toLowerCase()
    return result.map(([id, nodes]) => [
      id,
      nodes.filter(
        (n) =>
          n.label.toLowerCase().includes(q) ||
          n.source_file.toLowerCase().includes(q)
      ),
    ]) as typeof communities
  }, [communities, search, data, selectedNode, linkedNodes])

  const folderTree = useMemo(() => {
    const tree: TreeFolder = {
      name: "Project",
      path: "",
      children: {},
      files: [],
    }
    filteredCommunities.forEach(([id, nodes]) => {
      if (nodes.length === 0 && search) return
      let current = tree
      const idStr = String(id)
      if (idStr !== "root") {
        const parts = idStr.split("/")
        let currentPath = ""
        for (const part of parts) {
          if (!part) continue
          currentPath = currentPath ? `${currentPath}/${part}` : part
          if (!current.children[part]) {
            current.children[part] = {
              name: part,
              path: currentPath,
              children: {},
              files: [],
            }
          }
          current = current.children[part]
        }
      }
      current.files.push(...nodes)
    })
    return tree
  }, [filteredCommunities, search])

  const handleNodeClick = useCallback(
    (id: string) => {
      const node = data?.graph.nodes.find((n) => n.id === id) ?? null
      setSelectedNode(node)
    },
    [data, setSelectedNode]
  )

  if (loading && !data) {
    return (
      <div className={classes.root ?? "flex h-full w-full flex-col"}>
        <header
          className={cn(
            "sticky top-0 z-10 flex shrink-0 items-center gap-3 border-b border-border/50 bg-background/80 px-4 py-3 backdrop-blur",
            classes.header
          )}
        >
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-4 w-32" />
        </header>
        <div className="flex min-h-0 flex-1">
          <Skeleton className="h-full w-72" />
          <Skeleton className="h-full flex-1" />
        </div>
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className={classes.root ?? "flex h-full flex-col"}>
        <div className="flex flex-1 items-center justify-center gap-4 text-foreground">
          <AlertTriangle className="size-10 text-destructive" />
          <Heading as="h1" size="title">
            Failed to load graph data
          </Heading>
          <Text variant="muted">{error}</Text>
          <Button onClick={refresh} variant="outline">
            <RefreshCw className="mr-2 size-4" /> Retry
          </Button>
        </div>
      </div>
    )
  }

  return (
    <div className={classes.root ?? "flex h-full w-full flex-col"}>
      {/* ── HEADER ── */}
      <header
        className={cn(
          "sticky top-0 z-10 flex shrink-0 items-center gap-3 border-b border-border/50 bg-background/80 px-4 py-3 backdrop-blur",
          classes.header
        )}
      >
        <Network className="size-4 text-primary" />
        <Text variant="body" className="font-semibold text-foreground">
          Graphify 3D Architecture
        </Text>
        <div className="ml-2 hidden items-center gap-1.5 sm:flex">
          {selectedNode ? (
            <>
              <Badge
                variant="outline"
                className="border-warning/40 bg-warning/10 text-caption text-warning"
              >
                {1 + linkedNodes.size} / {data.graph.nodes.length} visible
              </Badge>
              <Badge
                variant="outline"
                className="border-border bg-muted/60 text-caption text-foreground"
              >
                {communities.length} communities
              </Badge>
            </>
          ) : (
            <>
              <Badge
                variant="outline"
                className="border-border bg-muted/60 text-caption text-foreground"
              >
                {data.graph.nodes.length} nodes
              </Badge>
              <Badge
                variant="outline"
                className="border-border bg-muted/60 text-caption text-foreground"
              >
                {data.graph.links.length} links
              </Badge>
              <Badge
                variant="outline"
                className="border-border bg-muted/60 text-caption text-foreground"
              >
                {communities.length} communities
              </Badge>
            </>
          )}
        </div>
        <div className="ml-auto flex items-center gap-1">
          <Button
            variant="ghost"
            size="sm"
            onClick={refresh}
            title="Refresh data"
          >
            <RefreshCw className="size-3.5" />
          </Button>
        </div>
      </header>

      <div className="flex min-h-0 flex-1">
        {/* ── LEFT SIDEBAR ── */}
        <div
          className={cn(
            "flex w-72 shrink-0 flex-col border-r border-border/50 bg-card xl:w-80",
            classes.sidebar
          )}
        >
          {selectedNode && (
            <div className="flex items-center gap-2 px-3 pt-2">
              <span className="rounded-md border border-amber-500/30 bg-amber-500/15 px-2 py-1 text-caption text-amber-300">
                Focus: {linkedNodes.size} linked
              </span>
              <span className="text-caption text-muted-foreground">
                Click elsewhere to clear
              </span>
            </div>
          )}

          <div className="shrink-0 border-b border-border/40 p-3">
            <div className="relative">
              <Search className="absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search nodes..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-8 border-border bg-background pl-8 text-body-sm"
              />
              {search && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-sm"
                  onClick={() => setSearch("")}
                  className="absolute top-1/2 right-2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                  aria-label="Xóa tìm kiếm"
                >
                  <X className="size-3" />
                </Button>
              )}
            </div>
          </div>

          <ScrollArea
            className={cn(
              "max-h-[calc(100vh-12rem)] flex-1",
              classes.scrollArea
            )}
          >
            <div className="p-3">
              <FolderNode
                folder={folderTree}
                selectedNode={selectedNode}
                linkedNodes={linkedNodes}
                onNodeClick={handleNodeClick}
                defaultOpen={true}
              />
            </div>
          </ScrollArea>
        </div>

        {/* ── GRAPH AREA ── */}
        <div className={cn("relative min-w-0 flex-1", classes.graphArea)}>
          <GraphifyForceGraph3D
            graph={data.graph}
            selectedNode={selectedNode}
            onNodeClick={(n) => setSelectedNode(n)}
            onBackgroundClick={() => setSelectedNode(null)}
            linkedNodes={linkedNodes}
          />

          <div
            className={cn(
              "absolute right-3 bottom-3 rounded-lg border border-border/30 bg-background/80 px-3 py-2 backdrop-blur",
              classes.hints
            )}
          >
            <div className="flex items-center gap-3 text-caption text-muted-foreground">
              <span className="flex items-center gap-1">
                <GripHorizontal className="size-3" /> Drag to rotate
              </span>
              <span className="flex items-center gap-1">
                <Maximize2 className="size-3" /> Scroll to zoom
              </span>
              <span className="flex items-center gap-1">
                <MousePointerClick className="size-3" /> Click to select
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

