"use client"

import { useEffect, useMemo, useState } from "react"
import { CalendarIcon } from "lucide-react"
import { Button } from "../button"
import { Calendar } from "../calendar"
import { Popover, PopoverContent, PopoverTrigger } from "../popover"
import {
  pickerTriggerClassName,
  type PickerSize,
} from "./picker-trigger-styles"

export interface DatePickerProps {
  value: unknown
  onChange: (value: unknown) => void
  placeholder?: string
  id?: string
  /** Năm sớm nhất trong dropdown (mặc định: năm hiện tại − 50). */
  fromYear?: number
  /** Năm muộn nhất trong dropdown (mặc định: năm hiện tại + 20). */
  toYear?: number
  size?: PickerSize
  className?: string
}

function formatIsoDate(d: Date): string {
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, "0")
  const day = String(d.getDate()).padStart(2, "0")
  return `${y}-${m}-${day}`
}

/** Parse YYYY-MM-DD theo giờ local, tránh lệch ngày do UTC. */
export function parseIsoDateString(value: string): Date | undefined {
  const trimmed = value.trim()
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(trimmed)
  if (match) {
    const year = Number(match[1])
    const month = Number(match[2])
    const day = Number(match[3])
    const date = new Date(year, month - 1, day)
    return Number.isNaN(date.getTime()) ? undefined : date
  }
  const fallback = new Date(trimmed)
  return Number.isNaN(fallback.getTime()) ? undefined : fallback
}

function getDefaultYearBounds() {
  const currentYear = new Date().getFullYear()
  return { fromYear: currentYear - 50, toYear: currentYear + 20 }
}

export function DatePicker({
  value,
  onChange,
  placeholder = "Tất cả",
  id,
  fromYear,
  toYear,
  size = "default",
  className,
}: DatePickerProps) {
  const [open, setOpen] = useState(false)

  const { startMonth, endMonth } = useMemo(() => {
    const bounds = getDefaultYearBounds()
    const minYear = fromYear ?? bounds.fromYear
    const maxYear = toYear ?? bounds.toYear
    return {
      startMonth: new Date(minYear, 0),
      endMonth: new Date(maxYear, 11),
    }
  }, [fromYear, toYear])

  const dateValue =
    typeof value === "string" && value ? parseIsoDateString(value) : undefined

  const [month, setMonth] = useState<Date>(() => dateValue ?? new Date())

  useEffect(() => {
    if (dateValue) setMonth(dateValue)
  }, [dateValue])

  const displayLabel =
    dateValue && !Number.isNaN(dateValue.getTime())
      ? dateValue.toLocaleDateString("vi-VN", {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
        })
      : placeholder

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger>
        <Button
          type="button"
          variant="outline"
          id={id}
          className={pickerTriggerClassName(size, className)}
        >
          <span className="truncate">{displayLabel}</span>
          <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-2" align="start">
        <Calendar
          mode="single"
          captionLayout="dropdown"
          month={month}
          onMonthChange={setMonth}
          startMonth={startMonth}
          endMonth={endMonth}
          selected={dateValue}
          onSelect={(date) => {
            onChange(date ? formatIsoDate(date) : undefined)
            if (date) setOpen(false)
          }}
          initialFocus
        />
        {dateValue && (
          <div className="mt-2 border-t pt-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-8 w-full text-xs"
              onClick={() => {
                onChange(undefined)
                setOpen(false)
              }}
            >
              Xóa ngày
            </Button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

src/components/pickers/date-range-picker.content:
"use client"

import { useEffect, useState } from "react"
import { CalendarIcon } from "lucide-react"
import { Button } from "../button"
import { Calendar } from "../calendar"
import { Popover, PopoverContent, PopoverTrigger } from "../popover"
import { cn } from "../../lib/utils"
import {
  pickerTriggerClassName,
  type PickerSize,
} from "./picker-trigger-styles"

export interface DateRangePickerProps {
  value: unknown
  onChange: (value: unknown) => void
  placeholder?: string
  id?: string
  size?: PickerSize
  className?: string
}

function formatIsoDate(d: Date): string {
  const y = d.getFullYear()
  const m = String(d.getMonth() + 1).padStart(2, "0")
  const day = String(d.getDate()).padStart(2, "0")
  return `${y}-${m}-${day}`
}

function parseDateRangeValue(value: unknown): { from?: Date; to?: Date } {
  if (typeof value === "string" && value) {
    const [fromStr, toStr] = value.split(",")
    const from = fromStr ? new Date(fromStr) : undefined
    const to = toStr ? new Date(toStr) : undefined
    return {
      from: from && !Number.isNaN(from.getTime()) ? from : undefined,
      to: to && !Number.isNaN(to.getTime()) ? to : undefined,
    }
  }
  return {}
}

export function DateRangePicker({
  value,
  onChange,
  placeholder = "Tất cả",
  id,
  size = "default",
  className,
}: DateRangePickerProps) {
  const [open, setOpen] = useState(false)
  const [draftRange, setDraftRange] = useState<{ from?: Date; to?: Date }>(() =>
    parseDateRangeValue(value)
  )

  useEffect(() => {
    setDraftRange(parseDateRangeValue(value))
  }, [value])

  const fmt = (d?: Date) =>
    d
      ? d.toLocaleDateString("vi-VN", {
          day: "2-digit",
          month: "2-digit",
          year: "numeric",
        })
      : ""
  const displayLabel =
    draftRange.from || draftRange.to
      ? `${fmt(draftRange.from)}${draftRange.to ? ` - ${fmt(draftRange.to)}` : ""}`
      : placeholder

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger>
        <Button
          type="button"
          variant="outline"
          id={id}
          className={pickerTriggerClassName(
            size,
            cn(size === "default" && "min-w-[200px]", className)
          )}
        >
          <span className="truncate">{displayLabel}</span>
          <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-2" align="start">
        <Calendar
          mode="range"
          numberOfMonths={2}
          captionLayout="dropdown"
          selected={
            draftRange.from
              ? { from: draftRange.from, to: draftRange.to }
              : undefined
          }
          onSelect={(range) => {
            setDraftRange({ from: range?.from, to: range?.to })
          }}
          initialFocus
        />
        <div className="mt-2 flex gap-2 border-t pt-2">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-8 flex-1 text-xs"
            onClick={() => {
              setDraftRange({})
              onChange(undefined)
            }}
          >
            Xóa
          </Button>
          <Button
            type="button"
            variant="default"
            size="sm"
            className="h-8 flex-1 text-xs"
            onClick={() => {
              if (draftRange.from) {
                const f = formatIsoDate(draftRange.from)
                const t = draftRange.to ? formatIsoDate(draftRange.to) : ""
                onChange(`${f},${t}`)
              } else {
                onChange(undefined)
              }
              setOpen(false)
            }}
          >
            Áp dụng
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

