"use client"

import { useState, createElement } from "react"
import { Check, ChevronDown, FileText, Folder } from "lucide-react"
import { Button } from "../button"
import { Popover, PopoverContent, PopoverTrigger } from "../popover"
import { cn } from "../../lib/utils"
import {
  pickerTriggerClassName,
  type PickerSize,
} from "./picker-trigger-styles"
import { resolveIcon } from "../../lib/icons"

function DynamicIcon({
  name,
  className,
}: {
  name?: string
  className?: string
}) {
  if (!name) return null
  return createElement(resolveIcon(name), { className })
}

export interface TreeOption {
  value: string
  label: string
  icon?: string
  children?: TreeOption[]
}

export interface TreePickerProps {
  value: unknown
  onChange: (value: unknown) => void
  options: TreeOption[]
  placeholder?: string
  id?: string
  size?: PickerSize
  className?: string
}

function flattenTreeOptions(
  nodes: TreeOption[]
): { value: string; label: string; icon?: string }[] {
  const result: { value: string; label: string; icon?: string }[] = []
  for (const node of nodes) {
    result.push({ value: node.value, label: node.label, icon: node.icon })
    if (node.children?.length) {
      result.push(...flattenTreeOptions(node.children))
    }
  }
  return result
}

function TreeSelectItem({
  label,
  value,
  icon,
  depth,
  isParent,
  selected,
  onSelect,
}: {
  label: string
  value: string
  icon?: string
  depth: number
  isParent: boolean
  selected: string
  onSelect: (value: string) => void
}) {
  const isSelected = selected === value
  const iconClass = icon
    ? "size-4 shrink-0 text-muted-foreground"
    : isParent
      ? "size-4 shrink-0 text-amber-500"
      : "size-4 shrink-0 text-muted-foreground"
  return (
    <button
      type="button"
      onClick={() => onSelect(value)}
      className={cn(
        "flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm",
        isSelected && "bg-primary/10 font-medium text-primary",
        !isSelected && "cursor-pointer hover:bg-muted"
      )}
      style={{ paddingLeft: `${12 + depth * 20}px` }}
    >
      {icon ? (
        <DynamicIcon name={icon} className={iconClass} />
      ) : isParent ? (
        <Folder className={iconClass} />
      ) : (
        <FileText className={iconClass} />
      )}
      <span className="flex-1 truncate">{label}</span>
      {isSelected && <Check className="size-4 shrink-0" />}
    </button>
  )
}

function TreeSelectNode({
  node,
  depth,
  selected,
  onSelect,
}: {
  node: TreeOption
  depth: number
  selected: string
  onSelect: (value: string) => void
}) {
  const isParent = (node.children?.length ?? 0) > 0
  return (
    <div>
      <TreeSelectItem
        label={node.label}
        value={node.value}
        icon={node.icon}
        depth={depth}
        isParent={isParent}
        selected={selected}
        onSelect={onSelect}
      />
      {node.children?.map((child) => (
        <TreeSelectNode
          key={child.value}
          node={child}
          depth={depth + 1}
          selected={selected}
          onSelect={onSelect}
        />
      ))}
    </div>
  )
}

export function TreePicker({
  value,
  onChange,
  options,
  placeholder = "Tất cả",
  id,
  size = "default",
  className,
}: TreePickerProps) {
  const [open, setOpen] = useState(false)
  const selected =
    typeof value === "string"
      ? value
      : value != null && value !== ""
        ? String(value)
        : ""
  const flat = flattenTreeOptions(options)
  const found = selected ? flat.find((o) => o.value === selected) : undefined
  const selectedLabel = found?.label ?? (selected || placeholder)
  const selectedIcon = found?.icon

  const handleSelect = (next: string) => {
    onChange(next === "" ? undefined : next)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger>
        <Button
          type="button"
          variant="outline"
          id={id}
          className={pickerTriggerClassName(size, className)}
        >
          <span className="flex items-center gap-2 truncate">
            <DynamicIcon
              name={selectedIcon}
              className="size-4 shrink-0 text-muted-foreground"
            />
            <span className="truncate">{selectedLabel}</span>
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-2" align="start">
        {options.length === 0 ? (
          <p className="px-2 py-1 text-sm text-muted-foreground">
            Không có tùy chọn
          </p>
        ) : (
          <div className="max-h-[min(60vh,18rem)] space-y-0.5 overflow-y-auto">
            <button
              type="button"
              onClick={() => handleSelect("")}
              className={cn(
                "flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm",
                !selected && "bg-primary/10 font-medium text-primary",
                selected && "cursor-pointer hover:bg-muted"
              )}
            >
              <span className="flex-1 truncate">{placeholder}</span>
              {!selected && <Check className="size-4 shrink-0" />}
            </button>
            {options
              .filter((node) => node.value !== "")
              .map((node) => (
                <TreeSelectNode
                  key={node.value}
                  node={node}
                  depth={0}
                  selected={selected}
                  onSelect={handleSelect}
                />
              ))}
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

