src/components/product/product-detail-un.content:
"use client"

import type { ReactNode } from "react"
import { Tag } from "lucide-react"
import { Badge } from "../badge"
import { ProductDetailSectionLabel } from "./product-detail-section-label"
import { Tabs, TabsList, TabsTrigger } from "../tabs"
import { cn } from "../../lib/utils"

export type ProductDetailUnitOption = {
  type: string
  label: string
  currentPriceLabel: string
  listPriceLabel?: string | null
  hasPromo?: boolean
}

export type ProductDetailUnitPickerLayout = "tabs" | "chips"

/** Lưới tab compact: 3 đơn vị → 1 hàng 3 cột; còn lại 2 cột. */
function compactTabsGridClass(optionCount: number): string {
  if (optionCount <= 1) return "grid-cols-1"
  if (optionCount === 3) return "grid-cols-3"
  return "grid-cols-2"
}

function UnitPromoBadge({
  visible,
  size = "xs",
  inverted = false,
}: {
  visible: boolean
  size?: "xs" | "sm"
  inverted?: boolean
}) {
  if (!visible) return null
  return (
    <Badge
      variant={inverted ? "overlay" : "promo"}
      size={size}
      shape="pill"
      className="shrink-0"
    >
      {size === "sm" ? (
        <>
          <Tag aria-hidden /> KM
        </>
      ) : (
        "KM"
      )}
    </Badge>
  )
}

type UnitChipPickerProps = {
  options: readonly ProductDetailUnitOption[]
  selectedType: string
  onSelect: (type: string) => void
  label: string | ReactNode
  showLabel: boolean
  className?: string
}

function ProductDetailUnitChipPicker({
  options,
  selectedType,
  onSelect,
  label,
  showLabel,
  className,
}: UnitChipPickerProps) {
  const ariaLabel = typeof label === "string" ? label : "Loại đơn vị"

  return (
    <div className={cn("space-y-2", className)}>
      {showLabel ? (
        <ProductDetailSectionLabel variant="soft">{label}</ProductDetailSectionLabel>
      ) : null}
      <div
        role="radiogroup"
        aria-label={ariaLabel}
        className="flex flex-wrap gap-1.5"
      >
        {options.map((option) => {
          const selected = selectedType === option.type
          const isPromo = option.hasPromo ?? false

          return (
            <button
              key={option.type}
              type="button"
              role="radio"
              aria-checked={selected}
              onClick={() => onSelect(option.type)}
              className={cn(
                "inline-flex min-h-8 max-w-full items-center gap-1 rounded-full border px-2.5 py-1 text-xs font-semibold leading-snug transition-all",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:outline-none",
                selected
                  ? "border-primary bg-primary text-primary-foreground shadow-sm ring-1 ring-primary/20"
                  : "border-outline-variant/40 bg-background/90 text-foreground/80 hover:border-primary/30 hover:bg-muted/40 hover:text-foreground",
              )}
            >
              <span className="line-clamp-2 text-left">{option.label}</span>
              <UnitPromoBadge visible={isPromo} inverted={selected} />
            </button>
          )
        })}
      </div>
    </div>
  )
}

export type ProductDetailUnitPickerProps = {
  options: readonly ProductDetailUnitOption[]
  selectedType: string
  onSelect: (type: string) => void
  className?: string
  label?: string
  showPrice?: boolean
  /** @deprecated Dùng `layout="chips"`. */
  compact?: boolean
  /** @deprecated Dùng `layout="chips"`. */
  dense?: boolean
  showLabel?: boolean
  /** `chips` — pill (catalog, CTSP); `tabs` — thẻ có giá (admin preview). */
  layout?: ProductDetailUnitPickerLayout
}

function resolveLayout(
  layout: ProductDetailUnitPickerLayout | undefined,
  compact: boolean,
  dense: boolean,
): ProductDetailUnitPickerLayout {
  if (layout) return layout
  if (compact || dense) return "chips"
  return "tabs"
}

export function ProductDetailUnitPicker({
  options,
  selectedType,
  onSelect,
  className,
  label = "Loại đơn vị",
  showPrice = true,
  compact = false,
  dense = false,
  showLabel = true,
  layout: layoutProp,
}: ProductDetailUnitPickerProps) {
  if (options.length <= 1) return null

  const layout = resolveLayout(layoutProp, compact, dense)

  if (layout === "chips") {
    return (
      <ProductDetailUnitChipPicker
        options={options}
        selectedType={selectedType}
        onSelect={onSelect}
        label={label}
        showLabel={showLabel}
        className={className}
      />
    )
  }

  return (
    <div className={cn("space-y-2.5", className)}>
      {showLabel ? (
        <ProductDetailSectionLabel variant="default">{label}</ProductDetailSectionLabel>
      ) : null}

      <Tabs
        value={selectedType}
        onValueChange={onSelect}
        className="w-full gap-0"
      >
        <TabsList
          className="group-data-horizontal/tabs:h-auto h-auto w-full flex-wrap justify-start gap-2 bg-transparent p-0"
          aria-label={typeof label === "string" ? label : "Loại đơn vị"}
        >
          {options.map((option) => {
            const isPromo = option.hasPromo ?? false

            return (
              <TabsTrigger
                key={option.type}
                value={option.type}
                className={cn(
                  "h-auto min-w-[7.5rem] flex-col items-start gap-0.5 rounded-lg border px-3 py-2 text-sm font-bold",
                  selectedType === option.type
                    ? isPromo
                      ? "border-primary bg-primary text-primary-foreground shadow-sm ring-1 ring-primary/20"
                      : "border-secondary bg-secondary text-secondary-foreground shadow-sm ring-1 ring-secondary/20"
                    : "border-outline-variant/50 bg-muted/30 text-muted-foreground hover:border-primary/30 hover:bg-muted/50",
                )}
              >
                <span className="leading-tight">{option.label}</span>
                {showPrice ? (
                  <span
                    className={cn(
                      "flex flex-wrap items-baseline gap-1 text-xs font-semibold",
                      selectedType === option.type ? "opacity-95" : "text-primary",
                    )}
                  >
                    {option.listPriceLabel ? (
                      <span className="line-through opacity-60">
                        {option.listPriceLabel}
                      </span>
                    ) : null}
                    <span>{option.currentPriceLabel}</span>
                    {isPromo ? (
                      <Badge variant="promo" size="xs" shape="pill">
                        <Tag aria-hidden /> KM
                      </Badge>
                    ) : null}
                  </span>
                ) : null}
              </TabsTrigger>
            )
          })}
        </TabsList>
      </Tabs>
    </div>
  )
}

/** Tab dạng lưới — admin preview khi cần giá trên từng ô (không dùng cho catalog). */
export function ProductDetailUnitPickerCompactTabs({
  options,
  selectedType,
  onSelect,
  className,
  label = "Loại đơn vị",
  showLabel = true,
}: Pick<
  ProductDetailUnitPickerProps,
  "options" | "selectedType" | "onSelect" | "className" | "label" | "showLabel"
>) {
  if (options.length <= 1) return null

  return (
    <div className={cn("space-y-2", className)}>
      {showLabel ? (
        <ProductDetailSectionLabel variant="soft">{label}</ProductDetailSectionLabel>
      ) : null}
      <Tabs
        value={selectedType}
        onValueChange={onSelect}
        className="w-full gap-0"
      >
        <TabsList
          className={cn(
            "grid h-auto min-h-12 w-full gap-1 rounded-lg p-1.5 group-data-horizontal/tabs:h-auto",
            compactTabsGridClass(options.length),
          )}
          aria-label={typeof label === "string" ? label : "Loại đơn vị"}
        >
          {options.map((option) => {
            const isPromo = option.hasPromo ?? false
            return (
              <TabsTrigger
                key={option.type}
                value={option.type}
                className="flex h-auto min-h-11 w-full min-w-0 flex-none flex-col items-center justify-center gap-1 whitespace-normal rounded-lg px-2 py-1.5 text-sm font-semibold leading-snug"
              >
                <span className="line-clamp-2 w-full text-center">
                  {option.label}
                </span>
                <UnitPromoBadge visible={isPromo} size="sm" />
              </TabsTrigger>
            )
          })}
        </TabsList>
      </Tabs>
    </div>
  )
}

src/components/product/product-money.ts.content:
/** Format VND — đồng bộ storefront + admin (`1.250.000đ`). */
export function formatProductVnd(amount: number | null | undefined): string {
  if (amount === null || amount === undefined || Number.isNaN(amount)) {
    return "—"
  }
  return `${amount.toLocaleString("vi-VN")}đ`
}

src/components/product/promo-admin-detai.content:
"use client"

import type { PromoCode } from "@workspace/api-client"
import {
  CalendarClock,
  Hash,
  Percent,
  ShoppingBag,
  Tag,
  Ticket,
  Users,
} from "lucide-react"
import {
  AdminDetailLayout,
  AdminDetailMain,
  AdminDetailSidebar,
} from "../admin/pages/admin-detail-layout"
import { Badge } from "../badge"
import {
  FieldSectionField,
  FieldSectionLegend,
  FieldSet,
  FieldSetContent,
} from "../field"
import { formatAdminDateTime } from "../../lib/format-admin-datetime"
import { cn } from "../../lib/utils"
import { formatProductVnd } from "./product-money"
import { PromoAdminHeroCard } from "./promo-admin-hero-card"
import {
  formatPromoDiscountValue,
  formatPromoUsageCount,
  formatPromoUsageLimit,
  PROMO_DISCOUNT_KIND_LABELS,
  promoUsagePercent,
} from "./promo-admin-format"

export type PromoAdminDetailProps = {
  promo: PromoCode
  className?: string
}

function UsageProgress({
  usageCount,
  usageLimit,
}: {
  usageCount: number
  usageLimit: number | null | undefined
}) {
  const percent = promoUsagePercent(usageCount, usageLimit)
  if (percent == null) {
    return (
      <span className="font-semibold tabular-nums">
        {usageCount.toLocaleString("vi-VN")} lượt
      </span>
    )
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between gap-2 text-sm">
        <span className="font-semibold tabular-nums text-foreground">
          {formatPromoUsageCount(usageCount, usageLimit)}
        </span>
        <span className="text-xs text-muted-foreground">{percent}%</span>
      </div>
      <div
        className="h-2 overflow-hidden rounded-full bg-muted"
        role="progressbar"
        aria-valuenow={percent}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Tiến độ sử dụng mã"
      >
        <div
          className={cn(
            "h-full rounded-full transition-all",
            percent >= 90 ? "bg-destructive" : "bg-primary",
          )}
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  )
}

export function PromoAdminDetail({ promo, className }: PromoAdminDetailProps) {
  const hasValidity = promo.validFrom != null || promo.validUntil != null

  return (
    <AdminDetailLayout className={className}>
      <AdminDetailMain className="space-y-6">
        <FieldSet variant="section">
          <FieldSectionLegend
            icon={Ticket}
            title="Thông tin giảm giá"
            description="Cấu hình áp dụng tại checkout storefront."
          />
          <FieldSetContent
            variant="section"
            className="grid gap-4 sm:grid-cols-2"
          >
            <FieldSectionField
              label="Mã coupon"
              icon={Hash}
              copyable
              copyText={promo.code}
            >
              <Badge variant="coupon" className="font-mono" data-copy-text={promo.code}>
                {promo.code}
              </Badge>
            </FieldSectionField>
            <FieldSectionField label="Nhãn hiển thị" icon={Tag} copyable>
              {promo.label}
            </FieldSectionField>
            <FieldSectionField label="Kiểu giảm" icon={Percent} copyable={false}>
              <Badge variant={promo.discountKind === "percent" ? "promo" : "outline"}>
                {PROMO_DISCOUNT_KIND_LABELS[promo.discountKind]}
              </Badge>
            </FieldSectionField>
            <FieldSectionField label="Giá trị giảm" copyable={false}>
              <span className="text-base font-bold tabular-nums text-primary">
                {formatPromoDiscountValue(promo)}
              </span>
            </FieldSectionField>
            <FieldSectionField label="Đơn tối thiểu" icon={ShoppingBag} copyable={false}>
              <span className="font-semibold tabular-nums">
                {formatProductVnd(promo.minOrderSubtotal)}
              </span>
            </FieldSectionField>
            <FieldSectionField label="Giới hạn lượt dùng" icon={Users} copyable={false}>
              {formatPromoUsageLimit(promo.usageLimit)}
            </FieldSectionField>
          </FieldSetContent>
        </FieldSet>
      </AdminDetailMain>

      <AdminDetailSidebar className="space-y-4 lg:sticky lg:top-4 lg:self-start">
        <PromoAdminHeroCard promo={promo} />

        <FieldSet variant="section">
          <FieldSectionLegend title="Sử dụng" />
          <FieldSetContent variant="section" className="space-y-3 pt-0">
            <FieldSectionField label="Lượt đã dùng" copyable={false}>
              <UsageProgress
                usageCount={promo.usageCount}
                usageLimit={promo.usageLimit}
              />
            </FieldSectionField>
          </FieldSetContent>
        </FieldSet>

        <FieldSet variant="section">
          <FieldSectionLegend icon={CalendarClock} title="Thời gian" />
          <FieldSetContent variant="section" className="space-y-3 pt-0">
            {promo.validFrom ? (
              <FieldSectionField label="Hiệu lực từ" copyable={false}>
                {formatAdminDateTime(promo.validFrom)}
              </FieldSectionField>
            ) : null}
            {promo.validUntil ? (
              <FieldSectionField label="Hết hạn" copyable={false}>
                {formatAdminDateTime(promo.validUntil)}
              </FieldSectionField>
            ) : null}
            {!hasValidity ? (
              <p className="text-sm text-muted-foreground">
                Không giới hạn thời gian — mã áp dụng cho đến khi tắt thủ công.
              </p>
            ) : null}
            <FieldSectionField label="Tạo lúc" copyable={false}>
              {formatAdminDateTime(promo.createdAt)}
            </FieldSectionField>
            <FieldSectionField label="Cập nhật" copyable={false}>
              {formatAdminDateTime(promo.updatedAt)}
            </FieldSectionField>
          </FieldSetContent>
        </FieldSet>
      </AdminDetailSidebar>
    </AdminDetailLayout>
  )
}

src/components/product/promo-admin-disco.content:
"use client"

import type { PromoDiscountKind } from "@workspace/api-client"
import { Banknote, Percent } from "lucide-react"
import { cn } from "../../lib/utils"
import { PROMO_DISCOUNT_KIND_LABELS } from "./promo-admin-format"

const KIND_OPTIONS: {
  value: PromoDiscountKind
  icon: typeof Percent
  hint: string
}[] = [
  {
    value: "percent",
    icon: Percent,
    hint: "Giảm theo % trên tổng đơn",
  },
  {
    value: "fixed",
    icon: Banknote,
    hint: "Trừ cố định số tiền VND",
  },
]

export type PromoAdminDiscountKindPickerProps = {
  value: PromoDiscountKind
  onChange: (kind: PromoDiscountKind) => void
  disabled?: boolean
  className?: string
}

export function PromoAdminDiscountKindPicker({
  value,
  onChange,
  disabled,
  className,
}: PromoAdminDiscountKindPickerProps) {
  return (
    <div
      role="radiogroup"
      aria-label="Kiểu giảm giá"
      className={cn("grid gap-2 sm:grid-cols-2", className)}
    >
      {KIND_OPTIONS.map((option) => {
        const selected = value === option.value
        const Icon = option.icon
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={selected}
            disabled={disabled}
            onClick={() => onChange(option.value)}
            className={cn(
              "flex min-h-[4.5rem] flex-col items-start gap-1.5 rounded-xl border-2 px-3 py-2.5 text-left transition-all",
              "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:outline-none",
              "disabled:pointer-events-none disabled:opacity-50",
              selected
                ? "border-primary bg-primary/8 shadow-sm ring-1 ring-primary/15"
                : "border-outline-variant/35 bg-background hover:border-primary/25 hover:bg-muted/30",
            )}
          >
            <span className="flex w-full items-center gap-2">
              <span
                className={cn(
                  "flex size-8 shrink-0 items-center justify-center rounded-lg",
                  selected
                    ? "bg-primary/15 text-primary"
                    : "bg-muted text-muted-foreground",
                )}
              >
                <Icon className="size-4" aria-hidden />
              </span>
              <span className="text-sm font-semibold text-foreground">
                {PROMO_DISCOUNT_KIND_LABELS[option.value]}
              </span>
            </span>
            <span className="text-xs leading-snug text-muted-foreground">
              {option.hint}
            </span>
          </button>
