"use client"

import { useEffect, useState } from "react"
import { ArrowUp } from "lucide-react"
import { Button } from "./button"
import { cn } from "../lib/utils"

const VISIBILITY_THRESHOLD = 300

function getScrollY(): number {
  return (
    window.scrollY ??
    window.pageYOffset ??
    document.documentElement.scrollTop ??
    document.body.scrollTop ??
    0
  )
}

/** Nút cuộn lên — hỗ trợ `window` và `main` scroll (portal / admin). */
export function ScrollToTop() {
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const main = document.querySelector<HTMLElement>(
      "main[class*='overflow-y-auto']"
    )

    const checkScroll = () => {
      const scrollY = getScrollY()
      const mainScrollTop = main?.scrollTop ?? 0
      setVisible(Math.max(scrollY, mainScrollTop) > VISIBILITY_THRESHOLD)
    }

    window.addEventListener("scroll", checkScroll, { passive: true })
    if (main) main.addEventListener("scroll", checkScroll, { passive: true })

    const raf = requestAnimationFrame(checkScroll)

    return () => {
      window.removeEventListener("scroll", checkScroll)
      if (main) main.removeEventListener("scroll", checkScroll)
      cancelAnimationFrame(raf)
    }
  }, [])

  const scrollToTop = () => {
    const main = document.querySelector<HTMLElement>(
      "main[class*='overflow-y-auto']"
    )
    if (main && main.scrollTop > 0) {
      main.scrollTo({ top: 0, behavior: "smooth" })
    } else {
      window.scrollTo({ top: 0, behavior: "smooth" })
    }
  }

  return (
    <Button
      variant="secondary"
      size="icon"
      aria-label="Cuộn lên đầu trang"
      onClick={scrollToTop}
      className={cn(
        "fixed right-6 bottom-6 z-50 flex size-10 items-center justify-center rounded-full bg-secondary text-secondary-foreground shadow-lg transition-all duration-300 hover:bg-secondary/90 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        visible
          ? "translate-y-0 opacity-100"
          : "pointer-events-none translate-y-2 opacity-0"
      )}
    >
      <ArrowUp className="size-5 text-secondary-foreground" />
    </Button>
  )
}

