          key={`${index}-${typeof item.title === "string" ? item.title : "timeline-item"}`}
          className="relative grid gap-4 md:grid-cols-2 md:gap-8"
        >
          <div
            className={cn(
              "relative pl-10 md:pl-0",
              index % 2 === 0 ? "md:pr-10" : "md:order-2 md:pl-10"
            )}
          >
            <div className="absolute top-1 left-0 flex size-6 items-center justify-center rounded-full border border-primary/30 bg-background text-primary shadow-sm md:top-2 md:right-[-12px] md:left-auto md:size-6">
