import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "../lib/utils"

/** Ba tông trạng thái sử dụng chuẩn admin. */
export type UsageStatusTone = "success" | "warning" | "danger"

export const USAGE_STATUS_LABELS: Record<UsageStatusTone, string> = {
  success: "Đang sử dụng",
  warning: "Cần lưu ý",
  danger: "Ngừng sử dụng",
}

const usageStatusBadgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center rounded-lg border border-transparent px-2.5 py-1 text-caption font-medium whitespace-nowrap",
  {
    variants: {
      tone: {
        success: "bg-success/10 text-success dark:bg-success/20",
        warning: "bg-warning/10 text-warning dark:bg-warning/20",
        danger: "bg-destructive/10 text-destructive dark:bg-destructive/20",
      },
    },
    defaultVariants: {
      tone: "success",
    },
  }
)

export type UsageStatusBadgeProps = React.ComponentProps<"span"> &
  VariantProps<typeof usageStatusBadgeVariants> & {
    tone: UsageStatusTone
    /** Ghi đè nhãn mặc định theo `tone`. */
    label?: string
  }

/** Badge trạng thái sử dụng — success / warning / danger. */
export function UsageStatusBadge({
  tone,
  label,
  className,
  children,
  ...props
}: UsageStatusBadgeProps) {
  const text = children ?? label ?? USAGE_STATUS_LABELS[tone]
  return (
    <span
      data-slot="usage-status-badge"
      data-tone={tone}
      className={cn(usageStatusBadgeVariants({ tone }), className)}
      {...props}
    >
      {text}
    </span>
  )
}

/**
 * Suy `tone` từ giá trị phổ biến trong admin (`1` hoạt động, `2` cảnh báo, còn lại ngừng/khóa).
 * Boolean: `true` → success, `false` → danger.
 */
export function resolveUsageStatusTone(
  value: number | boolean | UsageStatusTone
): UsageStatusTone {
  if (value === "success" || value === "warning" || value === "danger") {
    return value
  }
  if (typeof value === "boolean") return value ? "success" : "danger"
  if (value === 1) return "success"
  if (value === 2) return "warning"
  return "danger"
}

export type UsageStatusFromValueLabels = {
  success?: string
  warning?: string
  danger?: string
  /** `status === 1` */
  active?: string
  /** `status === 0` */
  locked?: string
}

export function resolveUsageStatusLabel(
  tone: UsageStatusTone,
  value?: number | boolean,
  labels?: UsageStatusFromValueLabels
): string {
  if (typeof value === "number") {
    if (value === 1 && labels?.active?.trim()) return labels.active.trim()
    if (value === 0 && labels?.locked?.trim()) return labels.locked.trim()
  }
  if (typeof value === "boolean") {
    if (value && labels?.active?.trim()) return labels.active.trim()
    if (!value && labels?.locked?.trim()) return labels.locked.trim()
  }
  const custom = labels?.[tone]?.trim()
  return custom || USAGE_STATUS_LABELS[tone]
}

export type UsageStatusFromValueProps = Omit<
  UsageStatusBadgeProps,
  "tone" | "label" | "children"
> & {
  value: number | boolean | UsageStatusTone
  labels?: UsageStatusFromValueLabels
}

/** Badge từ `status` số/boolean — dùng cho cột «Trạng thái» bảng admin. */
export function UsageStatusFromValue({
  value,
  labels,
  className,
  ...props
}: UsageStatusFromValueProps) {
  const tone = resolveUsageStatusTone(value)
  const label = resolveUsageStatusLabel(
    tone,
    typeof value === "number" || typeof value === "boolean" ? value : undefined,
    labels
  )
  return (
    <UsageStatusBadge
      tone={tone}
      label={label}
      className={className}
      {...props}
    />
  )
}

src/hooks/use-admin-mutation.ts.content:
"use client"

import {
  useMutation,
  type UseMutationOptions,
  type UseMutationResult,
} from "@tanstack/react-query"
import {
  adminToastMeta,
  defaultAdminOperationToast,
  inferAdminToastFromMutationKey,
  type AdminOperationToastMessages,
} from "../lib/admin-operation-toast"
import {
  adminToastSuppressMeta,
  type AdminToastSuppressMeta,
} from "../lib/admin-toast-suppress"

type AdminMutationLifecycleCallbacks<
  TData = unknown,
  TError = Error,
  TVariables = void,
> = {
  /** TanStack Query v5 không còn gọi callback trên `useMutation` — hook này tự forward. */
  onSuccess?: (
    data: TData,
    variables: TVariables,
    ...rest: unknown[]
  ) => void | Promise<void>
  onError?: (
    error: TError,
    variables: TVariables,
    ...rest: unknown[]
  ) => void | Promise<void>
  onSettled?: (
    data: TData | undefined,
    error: TError | null,
    variables: TVariables,
    ...rest: unknown[]
  ) => void | Promise<void>
}

export type UseAdminMutationOptions<
  TData = unknown,
  TError = Error,
  TVariables = void,
  TContext = unknown,
> = Omit<
  UseMutationOptions<TData, TError, TVariables, TContext>,
  "onSuccess" | "onError" | "onSettled"
> &
  AdminMutationLifecycleCallbacks<TData, TError, TVariables> & {
    /** `false` = tắt toast; `undefined` = mặc định loading/success/error */
    toast?:
      | Partial<AdminOperationToastMessages<TData, TVariables, TError>>
      | false
    /** Chặn toast socket trùng sau khi API trả 2xx (mặc định suy từ mutationKey[0]/[1]). */
    suppressRealtime?: AdminToastSuppressMeta | false
  }

export function useAdminMutation<
  TData = unknown,
  TError = Error,
  TVariables = void,
  TContext = unknown,
>(
  options: UseAdminMutationOptions<TData, TError, TVariables, TContext>
): UseMutationResult<TData, TError, TVariables, TContext> {
  const {
    toast: toastOverride,
    suppressRealtime,
    meta,
    mutationKey,
    onSuccess: userOnSuccess,
    onError: userOnError,
    onSettled: userOnSettled,
    mutationFn,
    ...rest
  } = options

  let mergedMeta = meta

  if (suppressRealtime !== false) {
    const resource =
      suppressRealtime?.resource ??
      (Array.isArray(mutationKey) && mutationKey[0]
        ? String(mutationKey[0])
        : undefined)
    const action =
      suppressRealtime?.action ??
      (Array.isArray(mutationKey) && mutationKey[1]
        ? String(mutationKey[1])
        : undefined)
    if (resource) {
      mergedMeta = {
        ...mergedMeta,
        ...adminToastSuppressMeta({ resource, action }),
      }
    }
  }

  if (toastOverride !== false) {
    const inferred = inferAdminToastFromMutationKey(mutationKey)
    const messages: AdminOperationToastMessages<TData, TVariables, TError> = {
      ...defaultAdminOperationToast,
      ...inferred,
      ...toastOverride,
      loading:
        toastOverride?.loading ??
        inferred?.loading ??
        defaultAdminOperationToast.loading,
      success:
        toastOverride?.success ??
        inferred?.success ??
        defaultAdminOperationToast.success,
      error:
        toastOverride?.error ??
        inferred?.error ??
        defaultAdminOperationToast.error,
    }
    mergedMeta = { ...meta, ...adminToastMeta(messages) }
  }

  const mutation = useMutation<TData, TError, TVariables, TContext>({
    ...rest,
    mutationKey,
    meta: mergedMeta,
    mutationFn: mutationFn!,
  })

  return {
    ...mutation,
    mutate: (variables, mutateOptions) => {
      mutation.mutate(variables, {
        ...mutateOptions,
        onSuccess: (data, vars, _ctx, mutateCtx) => {
          void userOnSuccess?.(data, vars, _ctx, mutateCtx)
          mutateOptions?.onSuccess?.(data, vars, _ctx, mutateCtx)
        },
        onError: (error, vars, _ctx, mutateCtx) => {
          void userOnError?.(error, vars, _ctx, mutateCtx)
          mutateOptions?.onError?.(error, vars, _ctx, mutateCtx)
        },
        onSettled: (data, error, vars, _ctx, mutateCtx) => {
          void userOnSettled?.(data, error, vars, _ctx, mutateCtx)
          mutateOptions?.onSettled?.(data, error, vars, _ctx, mutateCtx)
        },
      })
    },
    mutateAsync: async (variables, mutateOptions) => {
      let settledCtx: unknown
      let settledMutateCtx: unknown
      try {
        const data = await mutation.mutateAsync(variables, {
          ...mutateOptions,
          onSuccess: (result, vars, ctx, mCtx) => {
            settledCtx = ctx
            settledMutateCtx = mCtx
            mutateOptions?.onSuccess?.(result, vars, ctx, mCtx)
          },
        })
        await userOnSuccess?.(data, variables, settledCtx, settledMutateCtx)
        await userOnSettled?.(
          data,
          null,
          variables,
          settledCtx,
          settledMutateCtx
        )
        return data
      } catch (error) {
        await userOnError?.(error as TError, variables)
        await userOnSettled?.(undefined, error as TError, variables)
        throw error
      }
    },
  }
}

src/hooks/use-graphify.ts.content:
"use client"

import { useState, useCallback } from "react"
import type { GraphifyPayload, GraphNode } from "../lib/graphify-context"
import {
  getLinkedNodes,
  communityBreakdown,
  topHubs,
  routeFiles,
} from "../lib/graphify-context"

export interface UseGraphifyReturn {
  data: GraphifyPayload | null
  loading: boolean
  error: string | null
  selectedNode: GraphNode | null
  setSelectedNode: (n: GraphNode | null) => void
  linkedNodes: Map<string, number>
  communities: ReturnType<typeof communityBreakdown>
  hubs: ReturnType<typeof topHubs>
  routes: ReturnType<typeof routeFiles>
  refresh: () => Promise<void>
}

export function useGraphify(
  apiPath = "/api/graphify",
  maxDegree = 1
): UseGraphifyReturn {
  const [data, setData] = useState<GraphifyPayload | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null)

  const refresh = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch(apiPath)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const payload: GraphifyPayload = await res.json()
      setData(payload)
    } catch (e) {
      setError(e instanceof Error ? e.message : "Unknown error")
    } finally {
      setLoading(false)
    }
  }, [apiPath])

  const linkedNodes =
    selectedNode && data
      ? getLinkedNodes(selectedNode.id, data.graph, maxDegree)
      : new Map<string, number>()

  return {
    data,
    loading,
    error,
    selectedNode,
    setSelectedNode,
    linkedNodes,
    communities: data ? communityBreakdown(data.graph) : [],
    hubs: data ? topHubs(data.context) : [],
    routes: data ? routeFiles(data.context) : [],
    refresh,
  }
}

