"use client"

import { useCallback, useTransition, type MouseEvent } from "react"
import { useRouter } from "next/navigation"
import { useAdminRouteProgress } from "./admin-route-progress"

/** Prefetch route + điều hướng trong `startTransition` (chuyển trang mượt, ưu tiên tương tác). */
export function useAdminNavLink(href: string) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const { startIfNavigating } = useAdminRouteProgress()

  const prefetch = useCallback(() => {
    try {
      router.prefetch(href)
    } catch {
      // best-effort
    }
  }, [href, router])

  const onClick = useCallback(
    (event: MouseEvent<HTMLAnchorElement>, afterClick?: () => void) => {
      if (
        event.metaKey ||
        event.ctrlKey ||
        event.shiftKey ||
        event.altKey ||
        event.button !== 0 ||
        event.defaultPrevented
      ) {
        return
      }

      afterClick?.()
      event.preventDefault()
      prefetch()
      startIfNavigating(href)
      startTransition(() => {
        router.push(href)
      })
    },
    [href, prefetch, router, startIfNavigating]
  )

  return { isPending, prefetch, onClick }
}

src/lib/admin-operation-toast.ts.content:
"use client"

import {
  MutationCache,
  type Mutation,
  type MutationKey,
} from "@tanstack/react-query"
import { toast } from "./hub-toast"
import { suppressRealtimeToastAfterMutation } from "./admin-toast-suppress"

export type AdminOperationToastMessages<
  TData = unknown,
  TVariables = unknown,
  TError = unknown,
> = {
  loading: string
  success: string | ((data: TData, variables: TVariables) => string)
  error?: string | ((err: TError, variables: TVariables) => string)
}

export const defaultAdminOperationToast: AdminOperationToastMessages = {
  loading: "Đang thực hiện…",
  success: "Đã thực hiện thành công",
  error: (err) => resolveAdminOperationError(err),
}

/** Toast mặc định cho bulk delete / restore / hard-delete. */
export const defaultBulkOperationToast: AdminOperationToastMessages<
  unknown,
  { action: string; ids: string[] }
> = {
  loading: "Đang xử lý hàng loạt…",
  success: (_data, variables) => {
    const count = variables.ids?.length ?? 0
    if (variables.action === "delete") {
      return `Đã đưa ${count} mục vào thùng rác`
    }
    if (variables.action === "restore") {
      return `Đã khôi phục ${count} mục`
    }
    return `Đã xóa vĩnh viễn ${count} mục`
  },
  error: (err) => resolveAdminOperationError(err),
}

const toastIds = new WeakMap<
  Mutation<unknown, unknown, unknown, unknown>,
  string | number
>()

function resolveMessage(
  message: string | ((...args: never[]) => string),
  ...args: unknown[]
): string {
  return typeof message === "function"
    ? (message as (...a: unknown[]) => string)(...args)
    : message
}

export function resolveAdminOperationError(err: unknown): string {
  if (err instanceof Error && err.message.trim()) return err.message.trim()
  if (typeof err === "object" && err !== null && "message" in err) {
    const message = (err as { message: unknown }).message
    if (typeof message === "string" && message.trim()) return message.trim()
  }
  return "Không thực hiện được thao tác"
}

export function adminToastMeta<
  TData = unknown,
  TVariables = unknown,
  TError = unknown,
>(
  messages: AdminOperationToastMessages<TData, TVariables, TError>
): { adminToast: AdminOperationToastMessages<TData, TVariables, TError> } {
  return { adminToast: messages }
}

type AdminMutationMeta = {
  adminToast?: AdminOperationToastMessages<unknown, unknown, unknown>
  adminToastSuppress?: { resource?: string; action?: string }
}

function getAdminMutationMeta(
  mutation: Mutation<unknown, unknown, unknown, unknown>
): AdminMutationMeta | undefined {
  return mutation.meta as AdminMutationMeta | undefined
}

function getAdminToastMeta(
  mutation: Mutation<unknown, unknown, unknown, unknown>
): AdminOperationToastMessages | undefined {
  return getAdminMutationMeta(mutation)?.adminToast
}

export function createAdminMutationCache(): MutationCache {
  return new MutationCache({
    onMutate: (_variables, mutation) => {
      const adminToast = getAdminToastMeta(mutation)
      if (!adminToast?.loading) return
      const id = toast.loading(adminToast.loading)
      toastIds.set(mutation, id)
    },
    onSuccess: (data, variables, _context, mutation) => {
      const adminToast = getAdminToastMeta(mutation)
      if (!adminToast) return
      const id = toastIds.get(mutation)
      const message = resolveMessage(adminToast.success, data, variables)
      if (id != null) {
        toast.success(message, { id })
      } else {
        toast.success(message)
      }
      toastIds.delete(mutation)
      const meta = getAdminMutationMeta(mutation)
      suppressRealtimeToastAfterMutation(
        mutation.options.mutationKey,
        meta?.adminToastSuppress,
        data,
        variables
      )
    },
    onError: (error, variables, _context, mutation) => {
      const adminToast = getAdminToastMeta(mutation)
      if (!adminToast) return
      const id = toastIds.get(mutation)
      const message = adminToast.error
        ? resolveMessage(adminToast.error, error, variables)
        : resolveAdminOperationError(error)
      if (id != null) {
        toast.error(message, { id })
      } else {
        toast.error(message)
      }
      toastIds.delete(mutation)
    },
  })
}

/** Gợi ý toast theo mutationKey (tùy chọn). */
export function inferAdminToastFromMutationKey(
  key: MutationKey | undefined
): Partial<AdminOperationToastMessages> | undefined {
  if (!key || !Array.isArray(key) || key.length === 0) return undefined
  const action = String(key[1] ?? "mutate")
  const labels: Record<string, string> = {
    create: "tạo",
    update: "cập nhật",
    delete: "xóa",
    restore: "khôi phục",
    review: "duyệt",
    approve: "duyệt",
    reject: "từ chối",
  }
  const verb = labels[action] ?? "thực hiện"
  return {
    loading: `Đang ${verb}…`,
    success: `Đã ${verb} thành công`,
    error: (err) => `Lỗi ${verb}: ${resolveAdminOperationError(err)}`,
  }
}

src/lib/admin-route-progress.ts.content:
"use client"

import { useCallback } from "react"
import { useTopLoader } from "nextjs-toploader"

function normalizeRoutePath(href: string): string {
  if (typeof window === "undefined") return href
  try {
    const url = new URL(href, window.location.origin)
    return url.pathname + url.search
  } catch {
    return href.split("#")[0] ?? href
  }
}

/**
 * Bật thanh tiến trình (nextjs-toploader) khi điều hướng bằng `router.push`
 * — NextTopLoader mặc định chỉ bắt click `<a>`, không bắt nút bảng / CRUD.
 */
export function useAdminRouteProgress() {
  const loader = useTopLoader()

  const startIfNavigating = useCallback(
    (href: string) => {
      if (typeof window === "undefined") return
      const target = normalizeRoutePath(href)
      const current = window.location.pathname + window.location.search
      if (target === current) return
      loader.start()
    },
    [loader]
  )

  return { startIfNavigating }
}

src/lib/admin-table-export.ts.content:
import type { ColumnDef } from "@tanstack/react-table"
import {
  buildAdminTableXlsxExport,
  type AdminTableExportTemplateId,
  type AdminTableXlsxExportOptions,
} from "../components/admin/presets/table-xlsx-export"
import {
  buildCsvFromColumns,
  type BuildCsvFromColumnsOptions,
} from "./build-table-csv"
import {
  buildExportFromFields,
  type ExportFieldDef,
} from "./build-field-export"
import {
  downloadXlsxFile,
  downloadXlsxWorkbook,
  type XlsxExportOptions,
  type XlsxRelatedSection,
  type XlsxSheetPayload,
} from "./export-xlsx"

export type { XlsxRelatedSection, XlsxSheetPayload }

export type AdminTableExportData = {
  headers: string[]
  rows: string[][]
  columnWidths?: Array<number | undefined>
  columnWraps?: Array<boolean | undefined>
}

export type DownloadAdminTableXlsxParams<T> = {
  templateId: AdminTableExportTemplateId
  data: T[]
  /** Cột DataTable — mặc định dùng `buildCsvFromColumns`. */
  columns?: ColumnDef<T, unknown>[]
  /** Định nghĩa field phẳng — ưu tiên hơn `columns` khi có quan hệ / parse đặc biệt. */
  fields?: ExportFieldDef<T>[]
  options?: AdminTableXlsxExportOptions
  csvOptions?: BuildCsvFromColumnsOptions<T>
  /** Các bảng con / liên kết — sheet riêng trong cùng file. */
  relatedSheets?: Array<
    XlsxSheetPayload & {
      templateId?: AdminTableExportTemplateId
      options?: AdminTableXlsxExportOptions
    }
  >
  /** Các bảng con — chèn tiếp trên cùng sheet sau dữ liệu chính. */
  relatedSections?: XlsxRelatedSection[]
}

function resolveExportData<T>(
  params: DownloadAdminTableXlsxParams<T>
): AdminTableExportData {
  if (params.fields?.length) {
    return buildExportFromFields(params.data, params.fields)
  }
  if (!params.columns?.length) {
    return { headers: [], rows: [] }
  }
  return buildCsvFromColumns(params.data, params.columns, params.csvOptions)
}

/**
 * Xuất Excel chuẩn admin: template (title, metadata, merge section) + dữ liệu bảng.
 * Dùng chung cho mọi danh sách admin Next (`apps/main/backend`, …) gắn `AdminDataTable`.
 */
export async function downloadAdminTableXlsx<T>(
  params: DownloadAdminTableXlsxParams<T>
): Promise<void> {
  const mainConfig = buildAdminTableXlsxExport(
    params.templateId,
    params.options ?? {}
  )
  const { headers, rows, columnWidths, columnWraps } = resolveExportData(params)

  const mainOptions: XlsxExportOptions = {
    title: mainConfig.title,
    subtitle: mainConfig.subtitle,
    metadata: mainConfig.metadata,
    columnWidths,
    columnWraps,
    relatedSections: params.relatedSections,
  }

  if (params.relatedSheets?.length) {
    const sheets: XlsxSheetPayload[] = [
      {
        sheetName: mainConfig.sheetName,
        headers,
        rows,
        options: mainOptions,
      },
      ...params.relatedSheets.map((sheet) => {
        const cfg = sheet.templateId
          ? buildAdminTableXlsxExport(sheet.templateId, sheet.options ?? {})
          : null
        return {
          sheetName: sheet.sheetName,
          headers: sheet.headers,
          rows: sheet.rows,
          options: {
            title: sheet.options?.title ?? cfg?.title,
            subtitle: sheet.options?.subtitle ?? cfg?.subtitle,
            metadata: sheet.options?.metadata ?? cfg?.metadata,
            columnWidths: sheet.options?.columnWidths,
            columnWraps: sheet.options?.columnWraps,
            relatedSections: sheet.options?.relatedSections,
          },
        }
      }),
    ]
    await downloadXlsxWorkbook(mainConfig.fileName, sheets)
    return
  }

  await downloadXlsxFile(
    mainConfig.fileName,
    headers,
    rows,
    mainConfig.sheetName,
    mainOptions
  )
}

