/* ── Base layer ─────────────────────────────────────────────────────────── */
@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  :focus-visible {
    @apply outline-2 outline-offset-2 outline-ring;
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }

  body {
    @apply bg-background text-foreground;
    line-height: 1.4285;
  }

  html {
    @apply font-sans;
    font-size: 16px;
    transition: font-size 0.2s ease-in-out;
  }

  html[data-text-size="sm"] {
    font-size: 14px;
  }

  html[data-text-size="base"] {
    font-size: 16px;
  }

  html[data-text-size="lg"] {
    font-size: 18px;
  }

  /* Scrollbar theme (global + Base UI overlays) */
  * {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklab, var(--color-scrollbar) 78%, transparent)
      var(--color-scrollbar-track);
  }

  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  *::-webkit-scrollbar-track {
    background: var(--color-scrollbar-track);
  }

  *::-webkit-scrollbar-thumb {
    border: 2px solid transparent;
    border-radius: 9999px;
    background-clip: padding-box;
    background: color-mix(in oklab, var(--color-scrollbar) 78%, transparent);
  }

  *::-webkit-scrollbar-thumb:hover {
    background: color-mix(
      in oklab,
      var(--color-scrollbar-hover) 82%,
      transparent
    );
  }

  *::-webkit-scrollbar-corner {
    background: transparent;
  }

  [data-base-ui-inert] {
    scrollbar-width: thin;
    scrollbar-color: color-mix(in oklab, var(--color-scrollbar) 68%, transparent)
      transparent;
  }

  [data-base-ui-inert]::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  [data-base-ui-inert]::-webkit-scrollbar-thumb {
    border: 1px solid transparent;
    border-radius: 9999px;
    background-clip: padding-box;
    background: color-mix(in oklab, var(--color-scrollbar) 68%, transparent);
  }

  [data-base-ui-inert]::-webkit-scrollbar-thumb:hover {
    background: color-mix(
      in oklab,
      var(--color-scrollbar-hover) 76%,
      transparent
    );
  }
}

/* ── Typography utilities — Responsive rem scale ──────────────────────── */
@utility text-display {
  font-size: clamp(2.5rem, 6vw + 1rem, 5rem);
  line-height: 1.1;
  font-weight: 900;
}

@utility text-section {
  font-size: clamp(2rem, 4vw + 0.5rem, 3.5rem);
  line-height: 1.2;
  font-weight: 800;
}

@utility text-title {
  font-size: clamp(1.25rem, 2vw + 0.5rem, 2rem);
  line-height: 1.3;
  font-weight: 700;
}

@utility text-body {
  font-size: clamp(1rem, 0.5vw + 0.75rem, 1.125rem);
  line-height: 1.5;
  font-weight: 400;
}

@utility text-body-lg {
  font-size: clamp(1rem, 0.6vw + 0.8rem, 1.125rem);
  line-height: 1.5;
  font-weight: 400;
}

@utility text-body-sm {
  font-size: clamp(0.75rem, 0.3vw + 0.65rem, 0.875rem);
  line-height: 1.5;
  font-weight: 400;
}

@utility text-caption {
  font-size: clamp(0.625rem, 0.2vw + 0.55rem, 0.75rem);
  line-height: 1.33;
  font-weight: 400;
}

@utility text-label {
  font-size: clamp(0.625rem, 0.2vw + 0.55rem, 0.75rem);
  line-height: 1.33;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

/* Elevation */
@utility shadow-level-1 {
  box-shadow: var(--shadow-1);
}

@utility shadow-level-2 {
  box-shadow: var(--shadow-2);
}

@utility shadow-level-3 {
  box-shadow: var(--shadow-3);
}

/* Chip (category filter) */
@utility chip {
  display: inline-flex;
  align-items: center;
  padding: 6px 12px;
  border-radius: 9999px;
  font-size: clamp(0.875rem, 0.5vw + 0.75rem, 1rem);
  font-weight: 500;
  background-color: var(--secondary);
  color: var(--secondary-foreground);
  white-space: nowrap;
  cursor: pointer;
}

@utility chip-active {
  background-color: var(--primary);
  color: var(--primary-foreground);
}

/* Admin loading / skeleton */
@keyframes skeleton-shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes admin-loader-bar {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(320%);
  }
}

